#[allow(clippy::too_many_arguments)]
fn start_writer_workers_inner<F>(
    dataset_root: &Path,
    provenance: &RuntimeProvenance,
    manifest_tx: &mpsc::Sender<ManifestCommand>,
    runtime_stats: &Arc<SourceQueueBackpressureStats>,
    ready_tx: Option<&mpsc::Sender<StartupParticipant>>,
    raw_day_gate: Option<Arc<RawDayGate>>,
    dataset_lease: Option<Arc<File>>,
    mut before_spawn: F,
) -> Result<(
    BTreeMap<String, SourceWriterHandle>,
    Vec<StartupReleaseSender>,
)>
where
    F: FnMut(usize) -> io::Result<()>,
{
    let mut handles = BTreeMap::new();
    let mut releases = Vec::new();
    for (index, source_kind) in LIVE_SOURCES.iter().enumerate() {
        if let Err(error) = before_spawn(index) {
            converge_partial_writer_spawn(handles, releases, STARTUP_GATE_TIMEOUT);
            return Err(error.into());
        }
        let (tx, rx) = std::sync::mpsc::sync_channel(DEFAULT_WRITER_CHANNEL_CAPACITY);
        let queue_rows = Arc::new(AtomicU64::new(0));
        let queue_rows_for_worker = Arc::clone(&queue_rows);
        let accepting_commands = Arc::new(Mutex::new(true));
        let accepting_commands_for_worker = Arc::clone(&accepting_commands);
        let runtime_stats = Arc::clone(runtime_stats);
        let dataset_root = dataset_root.to_path_buf();
        let provenance = provenance.clone();
        let manifest_tx = manifest_tx.clone();
        let source_kind_owned = (*source_kind).to_owned();
        let report_source_kind = source_kind_owned.clone();
        let (result_tx, result_rx) = std::sync::mpsc::sync_channel(1);
        let writer_epoch = WriterEpochCell::default();
        let worker_epoch = writer_epoch.clone();
        let lifecycle_gate = raw_day_gate.clone();
        let writer_rendezvous_gate = raw_day_gate.clone();
        let writer_dataset_lease = dataset_lease.clone();
        let startup_gate = ready_tx.map(|ready_tx| {
            let participant = StartupParticipant::writer(source_kind);
            let (release_tx, release_rx) = oneshot::channel();
            releases.push(StartupReleaseSender {
                participant,
                sender: release_tx,
            });
            WriterStartupGate {
                participant,
                ready_tx: ready_tx.clone(),
                release_rx,
            }
        });
        let thread = match std::thread::Builder::new()
            .name(format!("data-collect-writer-{source_kind_owned}"))
            .spawn(move || {
                let _dataset_lease = writer_dataset_lease;
                let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    source_writer_worker_with_startup(
                        dataset_root,
                        provenance,
                        source_kind_owned,
                        rx,
                        queue_rows_for_worker,
                        accepting_commands_for_worker,
                        runtime_stats,
                        manifest_tx,
                        startup_gate,
                        worker_epoch.clone(),
                        writer_rendezvous_gate,
                    )
                }));
                let outcome = match result {
                    Ok(result) => WriterTaskOutcome::Returned(result),
                    Err(payload) => WriterTaskOutcome::Panicked(
                        payload
                            .downcast_ref::<&str>()
                            .map(|message| (*message).to_owned())
                            .or_else(|| payload.downcast_ref::<String>().cloned())
                            .unwrap_or_else(|| "writer thread panicked".to_owned()),
                    ),
                };
                let lifecycle_close = match &outcome {
                    WriterTaskOutcome::Returned(Ok(output)) => output.coordinated_close.clone(),
                    WriterTaskOutcome::Returned(Err(_))
                    | WriterTaskOutcome::Panicked(_)
                    | WriterTaskOutcome::MissingReport(_) => None,
                };
                let worker_epoch_snapshot = worker_epoch.snapshot();
                let lifecycle = if lifecycle_close.is_none() {
                    lifecycle_gate.as_ref().map(|gate| {
                        let cause = match &outcome {
                            WriterTaskOutcome::Panicked(_) => RuntimeCloseCause::WriterPanic {
                                source_kind: report_source_kind.clone(),
                            },
                            _ => RuntimeCloseCause::WriterReturn {
                                source_kind: report_source_kind.clone(),
                            },
                        };
                        let unclean_cause = matches!(&outcome, WriterTaskOutcome::Panicked(_))
                            .then_some(cause.clone());
                        gate.observe_source_terminal_now(
                            cause,
                            unclean_cause,
                            worker_epoch_snapshot.as_ref(),
                        )
                    })
                } else {
                    None
                };
                let first_observed_utc_ms = lifecycle
                    .as_ref()
                    .map_or_else(now_ms, |lifecycle| lifecycle.observed_utc_ms);
                let lifecycle_epoch = lifecycle
                    .as_ref()
                    .and_then(|lifecycle| lifecycle.epoch.clone())
                    .or_else(|| {
                        lifecycle_close.as_ref().map(|close| RuntimeEpoch {
                            utc_day: close.utc_day.clone(),
                            generation: close.generation,
                        })
                    });
                let termination_kind = if lifecycle_close.is_some() {
                    WriterTerminationKind::CoordinatedClose
                } else {
                    lifecycle.as_ref().map_or_else(
                        || match &outcome {
                            WriterTaskOutcome::Panicked(_)
                            | WriterTaskOutcome::MissingReport(_) => WriterTerminationKind::Unclean,
                            WriterTaskOutcome::Returned(_) => WriterTerminationKind::ReliableReturn,
                        },
                        |lifecycle| match lifecycle.termination_kind {
                            SourceTaskTerminationKind::ReliableReturn => {
                                WriterTerminationKind::ReliableReturn
                            }
                            SourceTaskTerminationKind::CoordinatedAbort
                            | SourceTaskTerminationKind::Unclean => WriterTerminationKind::Unclean,
                        },
                    )
                };
                let lifecycle_record_error =
                    lifecycle.and_then(|lifecycle| lifecycle.lifecycle_record_error);
                let _ = result_tx.send(WriterTaskReport {
                    source_kind: report_source_kind,
                    first_observed_utc_ms,
                    worker_epoch: worker_epoch_snapshot,
                    lifecycle_epoch,
                    termination_kind,
                    lifecycle_close,
                    lifecycle_record_error,
                    outcome,
                });
            }) {
            Ok(thread) => thread,
            Err(error) => {
                converge_partial_writer_spawn(handles, releases, STARTUP_GATE_TIMEOUT);
                return Err(
                    io::Error::other(format!("spawn writer thread failed: {error}")).into(),
                );
            }
        };
        handles.insert(
            (*source_kind).to_owned(),
            SourceWriterHandle {
                tx,
                queue_rows,
                accepting_commands,
                result_rx,
                completed_result: None,
                thread: Some(thread),
            },
        );
    }
    Ok((handles, releases))
}

fn converge_partial_writer_spawn(
    handles: BTreeMap<String, SourceWriterHandle>,
    releases: Vec<StartupReleaseSender>,
    budget: Duration,
) {
    drop(releases);
    let deadline = Instant::now() + budget;
    for (_, writer) in handles {
        let SourceWriterHandle {
            tx,
            queue_rows: _,
            accepting_commands: _,
            result_rx,
            completed_result: _,
            thread,
        } = writer;
        drop(tx);
        let remaining = deadline.saturating_duration_since(Instant::now());
        if !remaining.is_zero() {
            let _ = result_rx.recv_timeout(remaining);
        }
        let Some(thread) = thread else {
            continue;
        };
        while !thread.is_finished() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(1));
        }
        if thread.is_finished() {
            let _ = thread.join();
        }
    }
}

struct WriterCompletionNotice {
    message: String,
    worker_epoch: Option<RuntimeEpoch>,
    rendezvous_epoch: Option<RuntimeEpoch>,
    lifecycle_epoch: Option<RuntimeEpoch>,
    termination_kind: WriterTerminationKind,
}

fn poll_writer_completion(
    writers: &mut BTreeMap<String, SourceWriterHandle>,
    raw_day_gate: &RawDayGate,
    post_fence_epoch: Option<&RuntimeEpoch>,
) -> Option<WriterCompletionNotice> {
    for (source_kind, writer) in writers {
        if writer.completed_result.is_none() {
            match writer.result_rx.try_recv() {
                Ok(result) => writer.completed_result = Some(result),
                Err(std::sync::mpsc::TryRecvError::Empty) => continue,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    let message = format!("writer_result_channel_disconnected:{source_kind}");
                    let cause = RuntimeCloseCause::WriterReportDisconnected {
                        source_kind: source_kind.clone(),
                    };
                    let rendezvous_epoch = post_fence_epoch
                        .cloned()
                        .or_else(|| raw_day_gate.writer_rendezvous_epoch());
                    let lifecycle = raw_day_gate.observe_source_terminal_now(
                        cause.clone(),
                        Some(cause),
                        rendezvous_epoch.as_ref(),
                    );
                    let lifecycle_epoch = lifecycle.epoch.clone();
                    writer.completed_result = Some(WriterTaskReport {
                        source_kind: source_kind.clone(),
                        first_observed_utc_ms: lifecycle.observed_utc_ms,
                        worker_epoch: None,
                        lifecycle_epoch: lifecycle.epoch,
                        termination_kind: WriterTerminationKind::Unclean,
                        lifecycle_close: None,
                        lifecycle_record_error: lifecycle.lifecycle_record_error,
                        outcome: WriterTaskOutcome::MissingReport(message.clone()),
                    });
                    return Some(WriterCompletionNotice {
                        message,
                        worker_epoch: None,
                        rendezvous_epoch,
                        lifecycle_epoch,
                        termination_kind: WriterTerminationKind::Unclean,
                    });
                }
            }
        }
        if let Some(report) = writer.completed_result.as_ref() {
            let message = match &report.outcome {
                WriterTaskOutcome::Returned(Ok(_)) => {
                    format!("writer_ended_unexpectedly:{source_kind}")
                }
                WriterTaskOutcome::Returned(Err(error)) => {
                    format!("writer_failed:{source_kind}:{error}")
                }
                WriterTaskOutcome::Panicked(error) => {
                    format!("writer_panicked:{source_kind}:{error}")
                }
                WriterTaskOutcome::MissingReport(error) => error.clone(),
            };
            return Some(WriterCompletionNotice {
                message,
                worker_epoch: report.worker_epoch.clone(),
                rendezvous_epoch: raw_day_gate.writer_rendezvous_epoch(),
                lifecycle_epoch: report.lifecycle_epoch.clone(),
                termination_kind: report.termination_kind,
            });
        }
    }
    None
}

#[cfg(test)]
fn start_writer_workers_with_hung_result(
    dataset_root: &Path,
    provenance: &RuntimeProvenance,
    dataset_lease: Option<Arc<File>>,
) -> Result<BTreeMap<String, SourceWriterHandle>> {
    let _ = (dataset_root, provenance);
    let mut handles = BTreeMap::new();
    let (tx, _command_rx) = std::sync::mpsc::sync_channel(DEFAULT_WRITER_CHANNEL_CAPACITY);
    let (result_tx, result_rx) = std::sync::mpsc::sync_channel(1);
    let thread = std::thread::Builder::new()
        .name("data-collect-writer-hung".to_owned())
        .spawn(move || {
            let _dataset_lease = dataset_lease;
            let _result_tx = result_tx;
            std::thread::sleep(Duration::from_secs(60));
        })
        .map_err(|err| io::Error::other(format!("spawn hung writer thread failed: {err}")))?;
    handles.insert(
        "hung_writer".to_owned(),
        SourceWriterHandle {
            tx,
            queue_rows: Arc::new(AtomicU64::new(0)),
            accepting_commands: Arc::new(Mutex::new(true)),
            result_rx,
            completed_result: None,
            thread: Some(thread),
        },
    );
    Ok(handles)
}

async fn flush_all_batches(
    writers: &mut BTreeMap<String, SourceWriterHandle>,
    batches: &mut BTreeMap<String, Vec<InflightRawEvent>>,
    gaps: &SharedSourceGaps,
    runtime_stats: &SourceQueueBackpressureStats,
    writer_queue_tracker: &mut QueueDurationTracker,
    run_started: Instant,
) -> Result<()> {
    let sources = batches.keys().cloned().collect::<Vec<_>>();
    for source_kind in sources {
        let Some(batch) = batches.get_mut(&source_kind) else {
            continue;
        };
        flush_source_batch(
            writers,
            &source_kind,
            batch,
            gaps,
            runtime_stats,
            writer_queue_tracker,
            run_started,
        )
        .await?;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
async fn handle_ingress_control(
    control: IngressControl,
    writers: &mut BTreeMap<String, SourceWriterHandle>,
    batches: &mut BTreeMap<String, Vec<InflightRawEvent>>,
    gaps: &SharedSourceGaps,
    runtime_stats: &SourceQueueBackpressureStats,
    writer_queue_tracker: &mut QueueDurationTracker,
    run_started: Instant,
    manifest_tx: &mpsc::Sender<ManifestCommand>,
    rollover_coordinator: &mut RolloverCoordinatorState,
) -> Result<()> {
    match control {
        IngressControl::FinalizeSourceHour {
            source_kind,
            utc_hour,
        } => {
            let batch = batches.get_mut(&source_kind).ok_or_else(|| {
                invalid_data(format!(
                    "missing source batch for hour finalize: {source_kind}"
                ))
            })?;
            flush_source_batch(
                writers,
                &source_kind,
                batch,
                gaps,
                runtime_stats,
                writer_queue_tracker,
                run_started,
            )
            .await?;
            send_writer_hour_finalize(writers, &source_kind, &utc_hour).await?;
        }
        IngressControl::DayBarrier {
            producer,
            close,
            reply,
        } => {
            rollover_coordinator.register_producer_barrier(
                producer.clone(),
                close.clone(),
                reply,
            )?;
            flush_all_batches(
                writers,
                batches,
                gaps,
                runtime_stats,
                writer_queue_tracker,
                run_started,
            )
            .await?;
            send_writer_day_finalize(writers, &producer, &close).await?;
            let gap_snapshot = gaps
                .lock()
                .expect("source gap mutex poisoned")
                .reasons_for_day(&close.utc_day);
            let operational_counters = runtime_stats.drain_operational_day(&close.utc_day);
            manifest_tx
                .send(ManifestCommand::ProducerBarrier {
                    close,
                    producer,
                    gaps: gap_snapshot,
                    operational_counters,
                })
                .await
                .map_err(|_| {
                    io::Error::new(
                        io::ErrorKind::BrokenPipe,
                        "daily manifest owner channel closed during producer barrier",
                    )
                })?;
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
async fn process_ingress_event(
    mut inflight_event: InflightRawEvent,
    writers: &mut BTreeMap<String, SourceWriterHandle>,
    batches: &mut BTreeMap<String, Vec<InflightRawEvent>>,
    coverage: &mut BTreeMap<String, CoverageStats>,
    received_rows: &mut u64,
    average_event_bytes: &mut u64,
    gaps: &SharedSourceGaps,
    runtime_stats: &SourceQueueBackpressureStats,
    writer_queue_tracker: &mut QueueDurationTracker,
    run_started: Instant,
    manifest_tx: &mpsc::Sender<ManifestCommand>,
    rollover_coordinator: &mut RolloverCoordinatorState,
) -> Result<()> {
    if let Some(control) = inflight_event.control.take() {
        drop(inflight_event);
        return handle_ingress_control(
            control,
            writers,
            batches,
            gaps,
            runtime_stats,
            writer_queue_tracker,
            run_started,
            manifest_tx,
            rollover_coordinator,
        )
        .await;
    }
    if !inflight_event.admission_gaps.is_empty() {
        return Err(invalid_data("production raw event retained pre-admission gap effects").into());
    }
    let permit = inflight_event
        .raw_day_permit
        .as_ref()
        .ok_or_else(|| invalid_data("production raw event missing day/generation permit"))?;
    let event_day = utc_day_string_from_ms(inflight_event.event.recv_time_utc_ms)
        .ok_or_else(|| invalid_data("UTC day unavailable for inflight raw event"))?;
    if event_day != permit.utc_day || permit.generation == 0 {
        return Err(invalid_data(format!(
            "inflight raw-day permit mismatch: event_day={event_day} permit={permit:?}"
        ))
        .into());
    }
    *received_rows = received_rows.saturating_add(1);
    let event = &inflight_event.event;
    update_coverage(coverage, event);
    *average_event_bytes = rolling_average_bytes(
        *average_event_bytes,
        estimated_event_bytes(event),
        *received_rows,
    );
    let source_kind = event.source_kind.clone();
    let batch = batches.entry(source_kind.clone()).or_default();
    batch.push(inflight_event);
    if batch.len() >= DEFAULT_FLUSH_ROWS {
        flush_source_batch(
            writers,
            &source_kind,
            batch,
            gaps,
            runtime_stats,
            writer_queue_tracker,
            run_started,
        )
        .await?;
    }
    Ok(())
}

async fn flush_source_batch(
    writers: &mut BTreeMap<String, SourceWriterHandle>,
    source_kind: &str,
    batch: &mut Vec<InflightRawEvent>,
    gaps: &SharedSourceGaps,
    runtime_stats: &SourceQueueBackpressureStats,
    writer_queue_tracker: &mut QueueDurationTracker,
    run_started: Instant,
) -> Result<()> {
    if batch.is_empty() {
        return Ok(());
    }
    let rows = batch.len() as u64;
    let events = std::mem::take(batch);
    let drop_facts = events
        .iter()
        .map(|event| {
            (
                event.event.source_kind.clone(),
                event.event.recv_time_utc_ms,
            )
        })
        .collect::<Vec<_>>();
    let Some(writer) = writers.get(source_kind) else {
        writer_queue_tracker.record_drop(rows);
        record_writer_drop_facts(runtime_stats, &drop_facts);
        let gap = format!("writer_missing_for_source:{source_kind}");
        record_gap(gaps, gap.clone());
        return Err(io::Error::new(io::ErrorKind::BrokenPipe, gap).into());
    };
    let mut command = WriterCommand::Events(events);
    writer.queue_rows.fetch_add(rows, Ordering::Relaxed);
    match try_send_writer_command(writer, command) {
        Ok(()) => {
            writer_queue_tracker.observe(
                monotonic_ms(run_started),
                writers
                    .values()
                    .map(|handle| handle.queue_rows.load(Ordering::Relaxed))
                    .sum::<u64>(),
                0,
            );
            return Ok(());
        }
        Err(std::sync::mpsc::TrySendError::Full(returned)) => {
            writer.queue_rows.fetch_sub(rows, Ordering::Relaxed);
            writer_queue_tracker.record_backpressure_wait();
            command = returned;
        }
        Err(std::sync::mpsc::TrySendError::Disconnected(_)) => {
            writer.queue_rows.fetch_sub(rows, Ordering::Relaxed);
            writer_queue_tracker.record_drop(rows);
            record_writer_drop_facts(runtime_stats, &drop_facts);
            let gap = format!("writer_queue_disconnected:{source_kind}");
            record_gap(gaps, gap.clone());
            return Err(io::Error::new(io::ErrorKind::BrokenPipe, gap).into());
        }
    }
    match timeout(BUFFER_ACQUIRE_TIMEOUT, async {
        loop {
            writer.queue_rows.fetch_add(rows, Ordering::Relaxed);
            match try_send_writer_command(writer, command) {
                Ok(()) => return None,
                Err(std::sync::mpsc::TrySendError::Full(returned)) => {
                    writer.queue_rows.fetch_sub(rows, Ordering::Relaxed);
                    command = returned;
                    sleep(Duration::from_millis(50)).await;
                }
                Err(std::sync::mpsc::TrySendError::Disconnected(_)) => {
                    writer.queue_rows.fetch_sub(rows, Ordering::Relaxed);
                    return Some(format!("writer_queue_disconnected:{source_kind}"));
                }
            }
        }
    })
    .await
    {
        Ok(Some(gap)) => {
            writer_queue_tracker.record_drop(rows);
            record_writer_drop_facts(runtime_stats, &drop_facts);
            record_gap(gaps, gap.clone());
            Err(io::Error::new(io::ErrorKind::BrokenPipe, gap).into())
        }
        Ok(None) => Ok(()),
        Err(_) => {
            writer_queue_tracker.record_backpressure_timeout();
            writer_queue_tracker.record_drop(rows);
            record_writer_drop_facts(runtime_stats, &drop_facts);
            let gap = format!("writer_queue_backpressure_timeout:{source_kind}");
            record_gap(gaps, gap.clone());
            Err(io::Error::new(io::ErrorKind::TimedOut, gap).into())
        }
    }
}

fn try_send_writer_command(
    writer: &SourceWriterHandle,
    command: WriterCommand,
) -> std::result::Result<(), std::sync::mpsc::TrySendError<WriterCommand>> {
    let accepting = writer
        .accepting_commands
        .lock()
        .expect("writer accepting-command mutex poisoned");
    if !*accepting {
        return Err(std::sync::mpsc::TrySendError::Disconnected(command));
    }
    writer.tx.try_send(command)
}

fn record_writer_drop_facts(
    runtime_stats: &SourceQueueBackpressureStats,
    drop_facts: &[(String, i64)],
) {
    runtime_stats.record_drop(drop_facts.len() as u64);
    for (source_kind, recv_time_utc_ms) in drop_facts {
        runtime_stats.record_operational_drop(source_kind, *recv_time_utc_ms, 1);
    }
}

fn producer_writer_sources(producer: &str) -> Result<&'static [&'static str]> {
    match producer {
        "polymarket" => Ok(&["polymarket_market", "polymarket_market_metadata"]),
        "polymarket_rtds" => Ok(&["polymarket_rtds_chainlink_btc_usd"]),
        "binance_depth" => Ok(&["binance_depth_snapshot", "binance_depth_update"]),
        "binance_aggtrade" => Ok(&["binance_aggtrade"]),
        other => Err(invalid_data(format!("unknown logical producer: {other}")).into()),
    }
}

fn logical_producer_for_source_kind(source_kind: &str) -> Result<&'static str> {
    match source_kind {
        "polymarket_market" | "polymarket_market_metadata" => Ok("polymarket"),
        "polymarket_rtds_chainlink_btc_usd" => Ok("polymarket_rtds"),
        "binance_depth_snapshot" | "binance_depth_update" => Ok("binance_depth"),
        "binance_aggtrade" => Ok("binance_aggtrade"),
        other => Err(invalid_data(format!(
            "raw event source has no mandatory logical producer mapping: {other}"
        ))
        .into()),
    }
}

fn validate_mandatory_producer_source_mapping() -> Result<()> {
    let producers = LOGICAL_PRODUCERS.iter().copied().collect::<BTreeSet<_>>();
    if producers.len() != LOGICAL_PRODUCERS.len() {
        return Err(invalid_data("mandatory logical producer list contains duplicates").into());
    }
    let live_sources = LIVE_SOURCES.iter().copied().collect::<BTreeSet<_>>();
    if live_sources.len() != LIVE_SOURCES.len() {
        return Err(invalid_data("mandatory live source list contains duplicates").into());
    }

    let mut forward_sources = BTreeSet::new();
    for producer in LOGICAL_PRODUCERS {
        let sources = producer_writer_sources(producer)?;
        if sources.is_empty() {
            return Err(invalid_data(format!(
                "mandatory logical producer has no writer source: {producer}"
            ))
            .into());
        }
        for source_kind in sources {
            if !live_sources.contains(source_kind) {
                return Err(invalid_data(format!(
                    "producer mapping references non-live source: producer={producer} source={source_kind}"
                ))
                .into());
            }
            if !forward_sources.insert(*source_kind) {
                return Err(invalid_data(format!(
                    "live source is mapped by more than one producer: {source_kind}"
                ))
                .into());
            }
            if logical_producer_for_source_kind(source_kind)? != *producer {
                return Err(invalid_data(format!(
                    "producer/source mapping is not bidirectionally consistent: producer={producer} source={source_kind}"
                ))
                .into());
            }
        }
    }
    if forward_sources != live_sources {
        return Err(invalid_data(format!(
            "producer mapping does not cover the exact live source set: mapped={forward_sources:?} live={live_sources:?}"
        ))
        .into());
    }
    for source_kind in LIVE_SOURCES {
        let producer = logical_producer_for_source_kind(source_kind)?;
        if !producers.contains(producer)
            || !producer_writer_sources(producer)?.contains(source_kind)
        {
            return Err(invalid_data(format!(
                "live source inverse mapping is not present in the producer mapping: source={source_kind} producer={producer}"
            ))
            .into());
        }
    }
    Ok(())
}

async fn send_writer_day_finalize(
    writers: &BTreeMap<String, SourceWriterHandle>,
    producer: &str,
    close: &RawDayClose,
) -> Result<()> {
    for source_kind in producer_writer_sources(producer)? {
        let writer = writers.get(*source_kind).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::BrokenPipe,
                format!("writer missing for day barrier: {source_kind}"),
            )
        })?;
        let mut command = WriterCommand::FinalizeDay {
            close: close.clone(),
        };
        timeout(BUFFER_ACQUIRE_TIMEOUT, async {
            loop {
                match try_send_writer_command(writer, command) {
                    Ok(()) => return Ok(()),
                    Err(std::sync::mpsc::TrySendError::Full(returned)) => {
                        command = returned;
                        sleep(Duration::from_millis(50)).await;
                    }
                    Err(std::sync::mpsc::TrySendError::Disconnected(_)) => {
                        return Err(io::Error::new(
                            io::ErrorKind::BrokenPipe,
                            format!("writer queue disconnected during day barrier: {source_kind}"),
                        ));
                    }
                }
            }
        })
        .await
        .map_err(|_| {
            io::Error::new(
                io::ErrorKind::TimedOut,
                format!("writer day barrier timeout: {source_kind}"),
            )
        })??;
    }
    Ok(())
}

async fn send_writer_hour_finalize(
    writers: &BTreeMap<String, SourceWriterHandle>,
    source_kind: &str,
    utc_hour: &str,
) -> Result<()> {
    let writer = writers.get(source_kind).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::BrokenPipe,
            format!("writer missing for hour finalize: {source_kind}"),
        )
    })?;
    let mut command = WriterCommand::FinalizeHour {
        utc_hour: utc_hour.to_owned(),
    };
    timeout(BUFFER_ACQUIRE_TIMEOUT, async {
        loop {
            match try_send_writer_command(writer, command) {
                Ok(()) => return Ok(()),
                Err(std::sync::mpsc::TrySendError::Full(returned)) => {
                    command = returned;
                    sleep(Duration::from_millis(50)).await;
                }
                Err(std::sync::mpsc::TrySendError::Disconnected(_)) => {
                    return Err(io::Error::new(
                        io::ErrorKind::BrokenPipe,
                        format!("writer queue disconnected during hour finalize: {source_kind}"),
                    ));
                }
            }
        }
    })
    .await
    .map_err(|_| {
        io::Error::new(
            io::ErrorKind::TimedOut,
            format!("writer hour finalize timeout: {source_kind}"),
        )
    })??;
    Ok(())
}

async fn stop_writer_workers_with_budget(
    writers: BTreeMap<String, SourceWriterHandle>,
    budget: Duration,
) -> WriterStopOutcome {
    stop_writer_workers_with_optional_close(writers, None, budget).await
}

async fn shutdown_writer_workers_with_budget(
    writers: BTreeMap<String, SourceWriterHandle>,
    close: RuntimeCloseIdentity,
    budget: Duration,
) -> WriterStopOutcome {
    stop_writer_workers_with_optional_close(writers, Some(close), budget).await
}

async fn send_writer_shutdown(
    source_kind: &str,
    writer: &SourceWriterHandle,
    close: &RuntimeCloseIdentity,
    deadline: Instant,
) -> std::result::Result<(), String> {
    let mut command = WriterCommand::Shutdown {
        close: close.clone(),
    };
    loop {
        command = {
            let mut accepting = writer
                .accepting_commands
                .lock()
                .expect("writer accepting-command mutex poisoned");
            if !*accepting {
                return Err(format!(
                    "{source_kind} writer stopped accepting before coordinated shutdown"
                ));
            }
            match writer.tx.try_send(command) {
                Ok(()) => {
                    *accepting = false;
                    return Ok(());
                }
                Err(std::sync::mpsc::TrySendError::Full(returned)) => returned,
                Err(std::sync::mpsc::TrySendError::Disconnected(_)) => {
                    return Err(format!(
                        "{source_kind} writer queue disconnected before coordinated shutdown"
                    ));
                }
            }
        };
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err(format!(
                "{source_kind} writer coordinated-shutdown command timeout"
            ));
        }
        sleep(remaining.min(Duration::from_millis(25))).await;
    }
}

fn collect_writer_report(
    source_kind: &str,
    report: WriterTaskReport,
    expected_close: Option<&RuntimeCloseIdentity>,
    outputs: &mut Vec<SourceWriterOutput>,
    errors: &mut Vec<String>,
    proven: &mut BTreeSet<String>,
) {
    let report_identity_matches = report.source_kind == source_kind;
    if !report_identity_matches {
        errors.push(format!(
            "writer result identity mismatch: expected={source_kind} actual={}",
            report.source_kind
        ));
    }
    if let Some(error) = report.lifecycle_record_error.as_ref() {
        errors.push(format!(
            "{source_kind} writer lifecycle recording failed at {}: {error}",
            report.first_observed_utc_ms
        ));
    }
    let lifecycle_epoch_matches = expected_close.is_none_or(|expected| {
        report.lifecycle_epoch.as_ref()
            == Some(&RuntimeEpoch {
                utc_day: expected.utc_day.clone(),
                generation: expected.generation,
            })
    });
    let reliable_return_proves_close = report_identity_matches
        && report.termination_kind == WriterTerminationKind::ReliableReturn
        && lifecycle_epoch_matches
        && report.lifecycle_record_error.is_none()
        && matches!(&report.outcome, WriterTaskOutcome::Returned(_));
    match report.outcome {
        WriterTaskOutcome::Returned(Ok(output)) => {
            let identity_matches = output.source_kind == source_kind && report_identity_matches;
            let coordinated_close_matches = expected_close.is_none_or(|expected| {
                output.coordinated_close.as_ref() == Some(expected)
                    && report.lifecycle_close.as_ref() == Some(expected)
                    && report.worker_epoch.as_ref()
                        == Some(&RuntimeEpoch {
                            utc_day: expected.utc_day.clone(),
                            generation: expected.generation,
                        })
                    && lifecycle_epoch_matches
                    && report.lifecycle_record_error.is_none()
            });
            let close_proven = match report.termination_kind {
                WriterTerminationKind::CoordinatedClose => coordinated_close_matches,
                WriterTerminationKind::ReliableReturn => reliable_return_proves_close,
                WriterTerminationKind::Unclean => false,
            };
            if !identity_matches {
                errors.push(format!(
                    "writer output identity mismatch: expected={source_kind} actual={}",
                    output.source_kind
                ));
            }
            if let Some(expected) = expected_close
                && !close_proven
            {
                errors.push(format!(
                    "{source_kind} writer terminal proof mismatch: expected={expected:?} kind={:?} output={:?} report={:?} worker_epoch={:?} lifecycle_epoch={:?}",
                    report.termination_kind,
                    output.coordinated_close,
                    report.lifecycle_close,
                    report.worker_epoch,
                    report.lifecycle_epoch,
                ));
            }
            if identity_matches && close_proven && expected_close.is_some() {
                proven.insert(source_kind.to_owned());
            }
            outputs.push(output);
        }
        WriterTaskOutcome::Returned(Err(error)) => {
            if expected_close.is_some() && reliable_return_proves_close {
                proven.insert(source_kind.to_owned());
            } else if let Some(expected) = expected_close {
                errors.push(format!(
                    "{source_kind} writer reliable-return proof mismatch: expected={expected:?} kind={:?} lifecycle_epoch={:?}",
                    report.termination_kind, report.lifecycle_epoch
                ));
            }
            errors.push(format!(
                "{source_kind} writer failed at {}: {error}",
                report.first_observed_utc_ms
            ));
        }
        WriterTaskOutcome::Panicked(error) => {
            errors.push(format!(
                "{source_kind} writer panicked at {}: {error}",
                report.first_observed_utc_ms
            ));
        }
        WriterTaskOutcome::MissingReport(error) => {
            errors.push(format!(
                "{source_kind} writer report missing at {}: {error}",
                report.first_observed_utc_ms
            ));
        }
    }
}

async fn stop_writer_workers_with_optional_close(
    mut writers: BTreeMap<String, SourceWriterHandle>,
    expected_close: Option<RuntimeCloseIdentity>,
    budget: Duration,
) -> WriterStopOutcome {
    let deadline = Instant::now() + budget;
    let mut errors = Vec::new();
    let required = LIVE_SOURCES
        .iter()
        .map(|source| (*source).to_owned())
        .collect::<BTreeSet<_>>();
    let actual = writers.keys().cloned().collect::<BTreeSet<_>>();
    let mandatory_keys_exact = expected_close.is_none() || actual == required;
    if expected_close.is_some() && !mandatory_keys_exact {
        let missing = required.difference(&actual).cloned().collect::<Vec<_>>();
        let extra = actual.difference(&required).cloned().collect::<Vec<_>>();
        errors.push(format!(
            "writer mandatory key mismatch: missing={missing:?} extra={extra:?}"
        ));
    }
    if let Some(close) = expected_close.as_ref() {
        for (source_kind, writer) in &writers {
            if writer.completed_result.is_some() {
                continue;
            }
            if let Err(error) = send_writer_shutdown(source_kind, writer, close, deadline).await {
                errors.push(error);
            }
        }
    }

    let mut receivers = Vec::new();
    let mut threads = Vec::new();
    let mut outputs = Vec::new();
    let mut proven = BTreeSet::new();
    for (source_kind, writer) in std::mem::take(&mut writers) {
        let SourceWriterHandle {
            tx,
            queue_rows: _,
            accepting_commands: _,
            result_rx,
            completed_result,
            thread,
        } = writer;
        drop(tx);
        threads.push((source_kind.clone(), thread));
        match completed_result {
            Some(report) => collect_writer_report(
                &source_kind,
                report,
                expected_close.as_ref(),
                &mut outputs,
                &mut errors,
                &mut proven,
            ),
            None => receivers.push((source_kind, result_rx)),
        }
    }
    for (source_kind, result_rx) in receivers {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            match result_rx.try_recv() {
                Ok(report) => collect_writer_report(
                    &source_kind,
                    report,
                    expected_close.as_ref(),
                    &mut outputs,
                    &mut errors,
                    &mut proven,
                ),
                Err(std::sync::mpsc::TryRecvError::Empty) => {
                    errors.push(format!(
                        "writer finalize timeout before {source_kind} completed"
                    ));
                }
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    errors.push(format!("{source_kind} writer result channel disconnected"));
                }
            }
            continue;
        }
        match result_rx.recv_timeout(remaining) {
            Ok(report) => collect_writer_report(
                &source_kind,
                report,
                expected_close.as_ref(),
                &mut outputs,
                &mut errors,
                &mut proven,
            ),
            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
                errors.push(format!("writer finalize timeout for {source_kind}"));
            }
            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
                errors.push(format!("{source_kind} writer result channel disconnected"));
            }
        }
    }
    let mut all_terminal = true;
    for (source_kind, thread) in threads {
        let Some(thread) = thread else {
            all_terminal = false;
            proven.remove(&source_kind);
            errors.push(format!("{source_kind} writer thread owner missing"));
            continue;
        };
        while !thread.is_finished() && Instant::now() < deadline {
            sleep(Duration::from_millis(1)).await;
        }
        if !thread.is_finished() {
            all_terminal = false;
            proven.remove(&source_kind);
            errors.push(format!("writer thread join timeout for {source_kind}"));
            continue;
        }
        if thread.join().is_err() {
            proven.remove(&source_kind);
            errors.push(format!("writer thread join panicked for {source_kind}"));
        }
    }
    let all_close_proven = expected_close.is_none()
        || (mandatory_keys_exact && proven == required && actual == required);
    WriterStopOutcome {
        outputs,
        errors,
        all_terminal,
        all_close_proven,
    }
}

fn writer_outputs_or_record_failure(
    outcome: WriterStopOutcome,
    source_gaps: &SharedSourceGaps,
    runtime_failure: &mut Option<String>,
) -> (Vec<SourceWriterOutput>, bool, bool) {
    if !outcome.errors.is_empty() {
        let message = format!("writer_finalize_failed:{}", outcome.errors.join(" | "));
        record_gap(source_gaps, message.clone());
        *runtime_failure = Some(message);
    }
    (
        outcome.outputs,
        outcome.all_terminal,
        outcome.all_close_proven,
    )
}

#[cfg(test)]
#[allow(clippy::too_many_arguments)]
fn source_writer_worker(
    dataset_root: PathBuf,
    provenance: RuntimeProvenance,
    source_kind: String,
    rx: std::sync::mpsc::Receiver<WriterCommand>,
    queue_rows: Arc<AtomicU64>,
    accepting_commands: Arc<Mutex<bool>>,
    runtime_stats: Arc<SourceQueueBackpressureStats>,
    manifest_tx: mpsc::Sender<ManifestCommand>,
) -> Result<SourceWriterOutput> {
    source_writer_worker_with_startup(
        dataset_root,
        provenance,
        source_kind,
        rx,
        queue_rows,
        accepting_commands,
        runtime_stats,
        manifest_tx,
        None,
        WriterEpochCell::default(),
        None,
    )
}

#[allow(clippy::too_many_arguments)]
fn source_writer_worker_with_startup(
    dataset_root: PathBuf,
    provenance: RuntimeProvenance,
    source_kind: String,
    rx: std::sync::mpsc::Receiver<WriterCommand>,
    queue_rows: Arc<AtomicU64>,
    accepting_commands: Arc<Mutex<bool>>,
    runtime_stats: Arc<SourceQueueBackpressureStats>,
    manifest_tx: mpsc::Sender<ManifestCommand>,
    startup_gate: Option<WriterStartupGate>,
    writer_epoch: WriterEpochCell,
    raw_day_gate: Option<Arc<RawDayGate>>,
) -> Result<SourceWriterOutput> {
    let mut active = None::<ActiveSegment>;
    let mut finalized_segments = Vec::new();
    let mut stats = SourceWriterStatsBuilder::new(source_kind.clone());
    let partition_policy = HourlyPartitionPolicy::new(&dataset_root)?;
    let mut expected_raw_epoch = None::<RawDayPermit>;
    let mut coordinated_close = None::<RuntimeCloseIdentity>;
    let run_after_startup = if let Some(startup_gate) = startup_gate {
        startup_gate
            .ready_tx
            .blocking_send(startup_gate.participant)
            .map_err(|_| {
                invalid_data(format!(
                    "startup ready channel closed before writer ready: {}",
                    startup_gate.participant.name
                ))
            })?;
        match startup_gate.release_rx.blocking_recv().map_err(|_| {
            invalid_data(format!(
                "startup activation gate closed before writer release: {}",
                startup_gate.participant.name
            ))
        })? {
            StartupReleasePhase::Run => true,
            StartupReleasePhase::Stop(close) => {
                writer_epoch.set_close(&close);
                coordinated_close = Some(close);
                false
            }
        }
    } else {
        true
    };
    if run_after_startup {
        while let Ok(command) = rx.recv() {
            match command {
                WriterCommand::Events(events) => {
                    queue_rows.fetch_sub(events.len() as u64, Ordering::Relaxed);
                    let mut events = events.into_iter();
                    while let Some(inflight_event) = events.next() {
                        let event = &inflight_event.event;
                        let process_result = (|| -> Result<()> {
                            if let Some(permit) = inflight_event.raw_day_permit.as_ref() {
                                let event_day = utc_day_string_from_ms(event.recv_time_utc_ms)
                                    .ok_or_else(|| {
                                        invalid_data("UTC day unavailable in source writer")
                                    })?;
                                if event_day != permit.utc_day {
                                    return Err(invalid_data(format!(
                                    "writer raw-day permit mismatch: source={source_kind} event_day={event_day} permit={permit:?}"
                                ))
                                .into());
                                }
                                match expected_raw_epoch.as_ref() {
                                    Some(expected) if expected != permit => {
                                        return Err(invalid_data(format!(
                                        "writer raw-day generation mismatch: source={source_kind} expected={expected:?} actual={permit:?}"
                                    ))
                                    .into());
                                    }
                                    None => {
                                        expected_raw_epoch = Some(permit.clone());
                                        writer_epoch.set(permit);
                                    }
                                    Some(_) => {}
                                }
                            }
                            let current_partition = partition_policy.partition(
                                &source_kind,
                                event.recv_time_utc_ms,
                                None,
                            )?;
                            if let Some(reason) = active.as_ref().and_then(|segment| {
                                live_segment_rollover_reason(segment, &current_partition.utc_hour)
                            }) {
                                let segment = active.take().expect("active segment exists");
                                finalized_segments.push(finalize_segment_with_drop_accounting(
                                    segment,
                                    reason,
                                    &provenance,
                                    &manifest_tx,
                                    &runtime_stats,
                                )?);
                            }
                            if active.is_none() {
                                let (naming, selected_hour_part) = next_available_hourly_partition(
                                    &partition_policy,
                                    &source_kind,
                                    event.recv_time_utc_ms,
                                    None,
                                )?;
                                active = Some(ActiveSegment::new(
                                    naming,
                                    &source_kind,
                                    selected_hour_part,
                                )?);
                            }
                            let segment = active.as_mut().expect("active segment exists");
                            let write_started = Instant::now();
                            let written_rows = segment.writer.write_event(event)?;
                            let write_events_us = write_started.elapsed().as_micros() as u64;
                            segment.observe(event, written_rows);
                            stats.record_written_event(
                                event.recv_time_utc_ms,
                                written_rows,
                                write_events_us,
                            );
                            Ok(())
                        })();
                        if let Err(error) = process_result {
                            if let Some(segment) = active.as_ref() {
                                record_unfinalized_segment_drop(&runtime_stats, segment);
                            }
                            record_writer_drop_facts(
                                &runtime_stats,
                                &std::iter::once(inflight_event)
                                    .chain(events)
                                    .map(|event| {
                                        (event.event.source_kind, event.event.recv_time_utc_ms)
                                    })
                                    .collect::<Vec<_>>(),
                            );
                            stop_accepting_and_record_queued_drops(
                                &accepting_commands,
                                &rx,
                                &queue_rows,
                                &runtime_stats,
                            );
                            return Err(error);
                        }
                    }
                }
                WriterCommand::FinalizeHour { utc_hour } => {
                    if active
                        .as_ref()
                        .is_some_and(|segment| segment.utc_hour < utc_hour)
                    {
                        let segment = active.as_ref().expect("active segment exists");
                        let error = invalid_data(format!(
                            "writer hour barrier skipped UTC hour: source={source_kind} active={} barrier={utc_hour}",
                            segment.utc_hour
                        ));
                        record_unfinalized_segment_drop(&runtime_stats, segment);
                        stop_accepting_and_record_queued_drops(
                            &accepting_commands,
                            &rx,
                            &queue_rows,
                            &runtime_stats,
                        );
                        return Err(error.into());
                    }
                    if active
                        .as_ref()
                        .is_some_and(|segment| segment.utc_hour == utc_hour)
                    {
                        let segment = active.take().expect("active segment exists");
                        let finalized = finalize_segment_with_drop_accounting(
                            segment,
                            "utc_hour_boundary",
                            &provenance,
                            &manifest_tx,
                            &runtime_stats,
                        );
                        match finalized {
                            Ok(finalized) => finalized_segments.push(finalized),
                            Err(error) => {
                                stop_accepting_and_record_queued_drops(
                                    &accepting_commands,
                                    &rx,
                                    &queue_rows,
                                    &runtime_stats,
                                );
                                return Err(error);
                            }
                        }
                    }
                }
                WriterCommand::FinalizeDay { close } => {
                    let utc_day = &close.utc_day;
                    if let Some(expected) = expected_raw_epoch.as_ref()
                        && (expected.utc_day != close.utc_day
                            || expected.generation != close.generation)
                    {
                        let error = invalid_data(format!(
                            "writer finalize identity mismatch: source={source_kind} expected={expected:?} close={close:?}"
                        ));
                        if let Some(segment) = active.as_ref() {
                            record_unfinalized_segment_drop(&runtime_stats, segment);
                        }
                        stop_accepting_and_record_queued_drops(
                            &accepting_commands,
                            &rx,
                            &queue_rows,
                            &runtime_stats,
                        );
                        return Err(error.into());
                    }
                    if active
                        .as_ref()
                        .is_some_and(|segment| segment.utc_day.as_str() <= utc_day.as_str())
                    {
                        if active
                            .as_ref()
                            .is_some_and(|segment| segment.utc_day != *utc_day)
                        {
                            let error = invalid_data(format!(
                                "writer day barrier skipped UTC day: source={source_kind} active={} barrier={utc_day}",
                                active.as_ref().expect("active segment exists").utc_day
                            ));
                            record_unfinalized_segment_drop(
                                &runtime_stats,
                                active.as_ref().expect("active segment exists"),
                            );
                            stop_accepting_and_record_queued_drops(
                                &accepting_commands,
                                &rx,
                                &queue_rows,
                                &runtime_stats,
                            );
                            return Err(error.into());
                        }
                        let segment = active.take().expect("active segment exists");
                        let finalized = finalize_segment_with_drop_accounting(
                            segment,
                            "utc_day_barrier",
                            &provenance,
                            &manifest_tx,
                            &runtime_stats,
                        );
                        match finalized {
                            Ok(finalized) => finalized_segments.push(finalized),
                            Err(error) => {
                                stop_accepting_and_record_queued_drops(
                                    &accepting_commands,
                                    &rx,
                                    &queue_rows,
                                    &runtime_stats,
                                );
                                return Err(error);
                            }
                        }
                    }
                    if let Err(error) = manifest_tx
                        .blocking_send(ManifestCommand::WriterDayFinalized {
                            close: close.clone(),
                            source_kind: source_kind.clone(),
                            raw_day_gate: raw_day_gate.clone().ok_or_else(|| {
                                invalid_data(
                                    "writer day finalize requires the production raw-day gate",
                                )
                            })?,
                        })
                        .map_err(|_| {
                            io::Error::new(
                                io::ErrorKind::BrokenPipe,
                                "daily manifest owner channel closed during writer day finalize",
                            )
                        })
                    {
                        stop_accepting_and_record_queued_drops(
                            &accepting_commands,
                            &rx,
                            &queue_rows,
                            &runtime_stats,
                        );
                        return Err(error.into());
                    }
                    expected_raw_epoch = Some(RawDayPermit {
                        utc_day: close.next_utc_day,
                        generation: close.next_generation,
                    });
                    writer_epoch.set(
                        expected_raw_epoch
                            .as_ref()
                            .expect("writer next epoch was assigned"),
                    );
                }
                WriterCommand::Shutdown { close } => {
                    if let Some(expected) = expected_raw_epoch.as_ref()
                        && (expected.utc_day != close.utc_day
                            || expected.generation != close.generation)
                    {
                        let error = invalid_data(format!(
                            "writer shutdown identity mismatch: source={source_kind} expected={expected:?} close={close:?}"
                        ));
                        if let Some(segment) = active.as_ref() {
                            record_unfinalized_segment_drop(&runtime_stats, segment);
                        }
                        stop_accepting_and_record_queued_drops(
                            &accepting_commands,
                            &rx,
                            &queue_rows,
                            &runtime_stats,
                        );
                        return Err(error.into());
                    }
                    if active
                        .as_ref()
                        .is_some_and(|segment| segment.utc_day != close.utc_day)
                    {
                        let error = invalid_data(format!(
                            "writer shutdown active-day mismatch: source={source_kind} active={} close={}",
                            active.as_ref().expect("active segment exists").utc_day,
                            close.utc_day
                        ));
                        record_unfinalized_segment_drop(
                            &runtime_stats,
                            active.as_ref().expect("active segment exists"),
                        );
                        stop_accepting_and_record_queued_drops(
                            &accepting_commands,
                            &rx,
                            &queue_rows,
                            &runtime_stats,
                        );
                        return Err(error.into());
                    }
                    *accepting_commands
                        .lock()
                        .expect("writer accepting-command mutex poisoned") = false;
                    if expected_raw_epoch.is_none() {
                        writer_epoch.set_close(&close);
                    }
                    coordinated_close = Some(close);
                    break;
                }
            }
        }
    }
    if let Some(segment) = active.take() {
        finalized_segments.push(finalize_segment_with_drop_accounting(
            segment,
            "shutdown_finalize",
            &provenance,
            &manifest_tx,
            &runtime_stats,
        )?);
    }
    let stats = stats.finish(&finalized_segments);
    Ok(SourceWriterOutput {
        source_kind,
        finalized_segments,
        stats,
        coordinated_close,
        observed_utc_ms: now_ms(),
    })
}

fn finalize_segment_with_drop_accounting(
    segment: ActiveSegment,
    rollover_reason: &str,
    provenance: &RuntimeProvenance,
    manifest_tx: &mpsc::Sender<ManifestCommand>,
    runtime_stats: &SourceQueueBackpressureStats,
) -> Result<LiveFinalizedSegment> {
    let final_path = segment.writer.final_path().to_path_buf();
    let source_kind = segment.source_kind.clone();
    let recv_time_utc_ms = segment.segment_start_recv_time_utc_ms;
    let rows = segment.rows;
    match finalize_segment(segment, rollover_reason, provenance, manifest_tx) {
        Ok(finalized) => Ok(finalized),
        Err(error) => {
            if rows > 0 && !final_path.exists() {
                runtime_stats.record_drop(rows);
                runtime_stats.record_operational_drop(&source_kind, recv_time_utc_ms, rows);
            }
            Err(error)
        }
    }
}

fn record_unfinalized_segment_drop(
    runtime_stats: &SourceQueueBackpressureStats,
    segment: &ActiveSegment,
) {
    if segment.rows == 0 || segment.writer.final_path().exists() {
        return;
    }
    runtime_stats.record_drop(segment.rows);
    runtime_stats.record_operational_drop(
        &segment.source_kind,
        segment.segment_start_recv_time_utc_ms,
        segment.rows,
    );
}

fn stop_accepting_and_record_queued_drops(
    accepting_commands: &Mutex<bool>,
    rx: &std::sync::mpsc::Receiver<WriterCommand>,
    queue_rows: &AtomicU64,
    runtime_stats: &SourceQueueBackpressureStats,
) {
    let mut accepting = accepting_commands
        .lock()
        .expect("writer accepting-command mutex poisoned");
    *accepting = false;
    let mut drop_facts = Vec::new();
    while let Ok(command) = rx.try_recv() {
        if let WriterCommand::Events(events) = command {
            queue_rows.fetch_sub(events.len() as u64, Ordering::Relaxed);
            drop_facts.extend(
                events
                    .into_iter()
                    .map(|event| (event.event.source_kind, event.event.recv_time_utc_ms)),
            );
        }
    }
    drop(accepting);
    record_writer_drop_facts(runtime_stats, &drop_facts);
}

fn finalize_segment(
    mut segment: ActiveSegment,
    rollover_reason: &str,
    provenance: &RuntimeProvenance,
    manifest_tx: &mpsc::Sender<ManifestCommand>,
) -> Result<LiveFinalizedSegment> {
    let source_kind = segment.source_kind.clone();
    let schema_version = typed_schema_version(&source_kind);
    let manifest_context = SegmentManifestContext::from_segment(&segment);
    let facts = segment_daily_facts(
        &manifest_context,
        schema_version,
        rollover_reason,
        provenance,
    );
    let recovery_metadata = DailyFileRecoveryMetadata {
        source_kind: source_kind.clone(),
        utc_hour: manifest_context.utc_hour.clone(),
        part: manifest_context.hour_part,
        rows: manifest_context.rows,
        schema_version: schema_version.to_owned(),
        first_recv_time_utc_ms: manifest_context.segment_start_recv_time_utc_ms,
        last_recv_time_utc_ms: manifest_context.last_recv_time_utc_ms,
        source_timestamp_start: manifest_context.source_ts_start.clone(),
        source_timestamp_end: manifest_context.source_ts_end.clone(),
        event_type_counts: manifest_context.event_type_counts.clone(),
        facts: facts.clone(),
    };
    segment.writer.append_key_value_metadata(
        DAILY_FILE_RECOVERY_METADATA_KEY,
        serde_json::to_string(&recovery_metadata)?,
    )?;
    let published = segment.writer.finalize()?;
    if published.row_count != recovery_metadata.rows
        || published.schema_version != recovery_metadata.schema_version
    {
        return Err(invalid_data(format!(
            "finalized Parquet recovery metadata mismatch: source={source_kind} rows={} metadata_rows={} schema={} metadata_schema={}",
            published.row_count,
            recovery_metadata.rows,
            published.schema_version,
            recovery_metadata.schema_version,
        ))
        .into());
    }
    let bytes = fs::metadata(&published.final_path)?.len();
    let delta = DailyFinalizedFileDelta {
        utc_day: manifest_context.utc_day.clone(),
        source_kind: source_kind.clone(),
        utc_hour: manifest_context.utc_hour.clone(),
        part: manifest_context.hour_part,
        final_path: published.final_path.clone(),
        rows: published.row_count,
        bytes,
        sha256: published.sha256.clone(),
        schema_version: published.schema_version.clone(),
        first_recv_time_utc_ms: manifest_context.segment_start_recv_time_utc_ms,
        last_recv_time_utc_ms: manifest_context.last_recv_time_utc_ms,
        source_timestamp_start: manifest_context.source_ts_start.clone(),
        source_timestamp_end: manifest_context.source_ts_end.clone(),
        event_type_counts: manifest_context.event_type_counts.clone(),
        facts,
    };
    manifest_tx
        .blocking_send(ManifestCommand::Finalized(delta))
        .map_err(|_| {
            io::Error::new(
                io::ErrorKind::BrokenPipe,
                "daily manifest owner channel closed during finalize",
            )
        })?;
    Ok(LiveFinalizedSegment {
        source_kind,
        parquet_path: published.final_path,
        row_count: published.row_count,
        sha256: published.sha256,
    })
}

fn next_available_hourly_partition(
    partition_policy: &HourlyPartitionPolicy,
    source_kind: &str,
    recv_time_utc_ms: i64,
    preferred_part: Option<u32>,
) -> Result<(HourlyPartition, u32)> {
    let mut part = preferred_part.unwrap_or_default();
    for _ in 0..10_000 {
        let partition_part = if part == 0 { None } else { Some(part) };
        let partition =
            partition_policy.partition(source_kind, recv_time_utc_ms, partition_part)?;
        if !partition.running_path.exists() && !partition.final_path.exists() {
            return Ok((partition, part));
        }
        part = part.saturating_add(1);
    }
    Err(io::Error::new(
        io::ErrorKind::AlreadyExists,
        format!("no available hourly part for source {source_kind}"),
    )
    .into())
}

#[derive(Clone, Debug)]
struct SegmentManifestContext {
    source_kind: String,
    utc_day: String,
    utc_hour: String,
    hour_start_utc_ms: i64,
    hour_end_utc_ms: i64,
    hour_part: u32,
    segment_start_recv_time_utc_ms: i64,
    last_recv_time_utc_ms: i64,
    source_ts_start: Option<String>,
    source_ts_end: Option<String>,
    rows: u64,
    event_type_counts: BTreeMap<String, u64>,
    backfill_rows: u64,
    book_rows_with_bids_asks: u64,
    covered_market_slugs: BTreeSet<String>,
    covered_condition_ids: BTreeSet<String>,
    covered_asset_ids: BTreeSet<String>,
    depth_snapshot_last_update_id: Option<u64>,
    depth_stitch_applied_rows: u64,
    depth_stitch_gap_rows: u64,
    depth_resnapshot_count: u64,
    depth_local_u_min: Option<u64>,
    depth_local_u_max: Option<u64>,
    depth_first_update_bridged_snapshot: bool,
    depth_source_gaps: BTreeSet<String>,
    metadata_complete_rows: u64,
    metadata_unavailable_rows: u64,
}

impl SegmentManifestContext {
    fn from_segment(segment: &ActiveSegment) -> Self {
        Self {
            source_kind: segment.source_kind.clone(),
            utc_day: segment.utc_day.clone(),
            utc_hour: segment.utc_hour.clone(),
            hour_start_utc_ms: segment.hour_start_utc_ms,
            hour_end_utc_ms: segment.hour_end_utc_ms,
            hour_part: segment.hour_part,
            segment_start_recv_time_utc_ms: segment.segment_start_recv_time_utc_ms,
            last_recv_time_utc_ms: segment.last_recv_time_utc_ms,
            source_ts_start: segment.source_ts_start.clone(),
            source_ts_end: segment.source_ts_end.clone(),
            rows: segment.rows,
            event_type_counts: segment.event_type_counts.clone(),
            backfill_rows: segment.backfill_rows,
            book_rows_with_bids_asks: segment.book_rows_with_bids_asks,
            covered_market_slugs: segment.covered_market_slugs.clone(),
            covered_condition_ids: segment.covered_condition_ids.clone(),
            covered_asset_ids: segment.covered_asset_ids.clone(),
            depth_snapshot_last_update_id: segment.depth_snapshot_last_update_id,
            depth_stitch_applied_rows: segment.depth_stitch_applied_rows,
            depth_stitch_gap_rows: segment.depth_stitch_gap_rows,
            depth_resnapshot_count: segment.depth_resnapshot_count,
            depth_local_u_min: segment.depth_local_u_min,
            depth_local_u_max: segment.depth_local_u_max,
            depth_first_update_bridged_snapshot: segment.depth_first_update_bridged_snapshot,
            depth_source_gaps: segment.depth_source_gaps.clone(),
            metadata_complete_rows: segment.metadata_complete_rows,
            metadata_unavailable_rows: segment.metadata_unavailable_rows,
        }
    }
}

fn segment_daily_facts(
    segment: &SegmentManifestContext,
    schema_version: &str,
    rollover_reason: &str,
    provenance: &RuntimeProvenance,
) -> Value {
    let sort_order = typed_sort_order(schema_version, &segment.source_kind);
    json!({
        "rollover_reason": rollover_reason,
        "hour_window_utc_ms": {
            "start": segment.hour_start_utc_ms,
            "end": segment.hour_end_utc_ms,
        },
        "layout_family": layout_family_for_source(&segment.source_kind),
        "sort_order": sort_order,
        "compression": "zstd_level_3",
        "backfill_rows": segment.backfill_rows,
        "book_rows_with_bids_asks": segment.book_rows_with_bids_asks,
        "covered_market_slugs": segment.covered_market_slugs,
        "covered_condition_ids": segment.covered_condition_ids,
        "covered_asset_ids": segment.covered_asset_ids,
        "binance_depth_stitch": {
            "snapshot_last_update_id": segment.depth_snapshot_last_update_id,
            "stitch_applied_rows": segment.depth_stitch_applied_rows,
            "gap_rows": segment.depth_stitch_gap_rows,
            "resnapshot_count": segment.depth_resnapshot_count,
            "local_u_min": segment.depth_local_u_min,
            "local_u_max": segment.depth_local_u_max,
            "first_update_bridged_snapshot": segment.depth_first_update_bridged_snapshot,
        },
        "source_gaps": segment.depth_source_gaps,
        "metadata_complete_rows": segment.metadata_complete_rows,
        "metadata_unavailable_rows": segment.metadata_unavailable_rows,
        "code_version": provenance.code_version,
        "collector_binary_sha256": provenance.collector_binary_sha256,
        "source_config_digest": provenance.source_config_digest,
        "collector_host_id": provenance.collector_host_id,
        "collector_region": provenance.collector_region,
    })
}

fn layout_family_for_source(source_kind: &str) -> &'static str {
    match source_kind {
        "polymarket_market" => "pmxt_inspired_polymarket_orderbook",
        "polymarket_market_metadata" => "pmxt_inspired_polymarket_market_metadata",
        _ => "source_specific_hourly_typed_raw",
    }
}

struct BudgetedPolymarketMessage {
    message: WsMessage,
    recv_time_utc_ms: i64,
    _global_reservation: InflightReservation,
    _decoded_reservation: InflightReservation,
}

#[allow(clippy::large_enum_variant)]
enum PolymarketDrainEvent {
    Message(BudgetedPolymarketMessage),
    Fence { id: u64, stop_after_fence: bool },
}

#[derive(Debug)]
enum PolymarketDrainTerminal {
    Sdk(SdkStreamError),
    Capacity {
        reason: String,
        recv_time_utc_ms: i64,
        error_kind: io::ErrorKind,
    },
    QueueClosed,
}

enum PolymarketPumpControl {
    Fence {
        id: u64,
        stop_after_fence: bool,
        resume_after_fence: Option<oneshot::Receiver<()>>,
    },
}

#[allow(clippy::large_enum_variant)]
enum PolymarketPumpItem {
    Message(BudgetedPolymarketMessage),
    Fence { id: u64, stop_after_fence: bool },
    Terminal(PolymarketDrainTerminal),
}

enum PolymarketFenceRequest {
    Queued(u64),
    Paused {
        id: u64,
        resume: oneshot::Sender<()>,
    },
    PumpClosed,
}

struct PolymarketDrainRuntime {
    sdk: MarketSdkRuntime,
    events: mpsc::Receiver<PolymarketPumpItem>,
    controls: mpsc::Sender<PolymarketPumpControl>,
    pump: Option<tokio::task::JoinHandle<()>>,
    next_fence_id: u64,
    #[cfg(test)]
    #[allow(dead_code)]
    decoded_budget: InflightBudget,
}

impl PolymarketDrainRuntime {
    fn new(endpoint: String, config: WsConfig, global_budget: InflightBudget) -> Result<Self> {
        Self::new_with_recv_clock(endpoint, config, global_budget, Arc::new(now_ms))
    }

    fn new_with_recv_clock(
        endpoint: String,
        config: WsConfig,
        global_budget: InflightBudget,
        recv_utc_now: Arc<dyn Fn() -> i64 + Send + Sync>,
    ) -> Result<Self> {
        let mut sdk = MarketSdkRuntime::new(endpoint, config)?;
        let receiver = sdk.take_message_receiver()?;
        let decoded_budget = InflightBudget::with_limits(
            POLYMARKET_DECODED_QUEUE_CAPACITY,
            POLYMARKET_DECODED_MAX_BYTES,
        );
        let (event_tx, event_rx) =
            mpsc::channel::<PolymarketPumpItem>(POLYMARKET_DECODED_QUEUE_CAPACITY);
        let (control_tx, control_rx) =
            mpsc::channel::<PolymarketPumpControl>(POLYMARKET_CONTROL_CHANNEL_CAPACITY);
        let pump_decoded_budget = decoded_budget.clone();
        let pump = tokio::spawn(run_polymarket_fast_drain(
            receiver,
            event_tx,
            control_rx,
            global_budget,
            pump_decoded_budget,
            recv_utc_now,
        ));
        Ok(Self {
            sdk,
            events: event_rx,
            controls: control_tx,
            pump: Some(pump),
            next_fence_id: 0,
            #[cfg(test)]
            decoded_budget,
        })
    }

    async fn request_fence(&mut self, stop_after_fence: bool) -> Result<PolymarketFenceRequest> {
        self.request_fence_inner(stop_after_fence, None).await
    }

    async fn request_paused_fence(&mut self) -> Result<PolymarketFenceRequest> {
        let (resume, resume_after_fence) = oneshot::channel();
        match self
            .request_fence_inner(false, Some(resume_after_fence))
            .await?
        {
            PolymarketFenceRequest::Queued(id) => Ok(PolymarketFenceRequest::Paused { id, resume }),
            PolymarketFenceRequest::PumpClosed => Ok(PolymarketFenceRequest::PumpClosed),
            PolymarketFenceRequest::Paused { .. } => {
                Err(invalid_data("nested Polymarket paused fence request").into())
            }
        }
    }

    async fn request_fence_inner(
        &mut self,
        stop_after_fence: bool,
        resume_after_fence: Option<oneshot::Receiver<()>>,
    ) -> Result<PolymarketFenceRequest> {
        self.next_fence_id = self
            .next_fence_id
            .checked_add(1)
            .ok_or_else(|| invalid_data("Polymarket source fence revision overflow"))?;
        let id = self.next_fence_id;
        match timeout(
            BUFFER_ACQUIRE_TIMEOUT,
            self.controls.send(PolymarketPumpControl::Fence {
                id,
                stop_after_fence,
                resume_after_fence,
            }),
        )
        .await
        {
            Err(_) => Err(invalid_data("Polymarket fast-drain control queue timeout").into()),
            Ok(Ok(())) => Ok(PolymarketFenceRequest::Queued(id)),
            Ok(Err(_)) => Ok(PolymarketFenceRequest::PumpClosed),
        }
    }

    async fn recv(
        &mut self,
        timeout_duration: Duration,
    ) -> std::result::Result<Option<PolymarketDrainEvent>, PolymarketDrainTerminal> {
        match timeout(timeout_duration, self.events.recv()).await {
            Err(_) => Ok(None),
            Ok(Some(PolymarketPumpItem::Message(message))) => {
                Ok(Some(PolymarketDrainEvent::Message(message)))
            }
            Ok(Some(PolymarketPumpItem::Fence {
                id,
                stop_after_fence,
            })) => Ok(Some(PolymarketDrainEvent::Fence {
                id,
                stop_after_fence,
            })),
            Ok(Some(PolymarketPumpItem::Terminal(error))) => Err(error),
            Ok(None) => Err(PolymarketDrainTerminal::QueueClosed),
        }
    }

    async fn wait_pump_stopped(&mut self) -> Result<()> {
        let Some(mut pump) = self.pump.take() else {
            return Ok(());
        };
        match timeout(BUFFER_ACQUIRE_TIMEOUT, &mut pump).await {
            Ok(result) => {
                result.map_err(|error| {
                    invalid_data(format!("Polymarket fast-drain task failed:{error}"))
                })?;
                Ok(())
            }
            Err(_) => {
                pump.abort();
                let _ = pump.await;
                Err(invalid_data("Polymarket fast-drain task stop timeout").into())
            }
        }
    }

    async fn abort_pump_and_wait(&mut self) {
        if let Some(pump) = self.pump.take() {
            pump.abort();
            let _ = pump.await;
        }
    }
}

impl Drop for PolymarketDrainRuntime {
    fn drop(&mut self) {
        if let Some(pump) = &self.pump {
            pump.abort();
        }
    }
}

async fn run_polymarket_fast_drain(
    mut receiver: MarketSdkMessageReceiver,
    events: mpsc::Sender<PolymarketPumpItem>,
    mut controls: mpsc::Receiver<PolymarketPumpControl>,
    global_budget: InflightBudget,
    decoded_budget: InflightBudget,
    recv_utc_now: Arc<dyn Fn() -> i64 + Send + Sync>,
) {
    loop {
        tokio::select! {
            biased;
            control = controls.recv() => {
                let Some(PolymarketPumpControl::Fence {
                    id,
                    stop_after_fence,
                    resume_after_fence,
                }) = control else {
                    break;
                };
                let terminal_before_snapshot = receiver.terminal_snapshot();
                let pending_at_fence = receiver.pending_len();
                let terminal_at_fence = terminal_before_snapshot.or_else(|| receiver.terminal_snapshot());
                for _ in 0..pending_at_fence {
                    match receiver.try_recv() {
                        Ok(Some(message)) => {
                            if !enqueue_polymarket_decoded_message(
                                message,
                                &events,
                                &global_budget,
                                &decoded_budget,
                                recv_utc_now(),
                            )
                            .await
                            {
                                return;
                            }
                        }
                        Ok(None) => break,
                        Err(error) => {
                            send_polymarket_terminal(
                                &events,
                                PolymarketDrainTerminal::Sdk(error),
                            )
                            .await;
                            return;
                        }
                    }
                }
                if let Some(error) = terminal_at_fence {
                    send_polymarket_terminal(
                        &events,
                        PolymarketDrainTerminal::Sdk(error),
                    )
                    .await;
                    return;
                }
                if events.send(PolymarketPumpItem::Fence { id, stop_after_fence }).await.is_err() {
                    break;
                }
                if stop_after_fence {
                    break;
                }
                if let Some(resume) = resume_after_fence
                    && resume.await.is_err()
                {
                    break;
                }
            }
            received = receiver.recv(Duration::from_millis(250)) => {
                let message = match received {
                    Ok(Some(message)) => message,
                    Ok(None) => continue,
                    Err(error) => {
                        send_polymarket_terminal(
                            &events,
                            PolymarketDrainTerminal::Sdk(error),
                        )
                        .await;
                        break;
                    }
                };
                if !enqueue_polymarket_decoded_message(
                    message,
                    &events,
                    &global_budget,
                    &decoded_budget,
                    recv_utc_now(),
                )
                .await
                {
                    break;
                }
            }
        }
    }
}

async fn enqueue_polymarket_decoded_message(
    message: WsMessage,
    events: &mpsc::Sender<PolymarketPumpItem>,
    global_budget: &InflightBudget,
    decoded_budget: &InflightBudget,
    recv_time_utc_ms: i64,
) -> bool {
    if !message.is_market() {
        return true;
    }
    let owned_bytes = owned_polymarket_message_bytes(&message);
    if owned_bytes > MAX_TYPED_ROW_BYTES {
        let reason = format!(
            "operator_intervention_required:Polymarket decoded message exceeds {MAX_TYPED_ROW_BYTES} bytes:bytes={owned_bytes}"
        );
        send_polymarket_terminal(
            events,
            PolymarketDrainTerminal::Capacity {
                reason,
                recv_time_utc_ms,
                error_kind: io::ErrorKind::InvalidData,
            },
        )
        .await;
        return false;
    }
    let acquire_deadline = Instant::now() + BUFFER_ACQUIRE_TIMEOUT;
    let global_reservation =
        match acquire_polymarket_fast_path(global_budget, 1, owned_bytes, BUFFER_ACQUIRE_TIMEOUT)
            .await
        {
            Ok(reservation) => reservation,
            Err(error) => {
                let error_kind = error.kind();
                let reason = format!("polymarket_decoded_global_budget_failed:{error}");
                send_polymarket_terminal(
                    events,
                    PolymarketDrainTerminal::Capacity {
                        reason,
                        recv_time_utc_ms,
                        error_kind,
                    },
                )
                .await;
                return false;
            }
        };
    let remaining = acquire_deadline.saturating_duration_since(Instant::now());
    let decoded_reservation =
        match acquire_polymarket_fast_path(decoded_budget, 1, owned_bytes, remaining).await {
            Ok(reservation) => reservation,
            Err(error) => {
                drop(global_reservation);
                let error_kind = error.kind();
                let reason = format!("polymarket_decoded_budget_failed:{error}");
                send_polymarket_terminal(
                    events,
                    PolymarketDrainTerminal::Capacity {
                        reason,
                        recv_time_utc_ms,
                        error_kind,
                    },
                )
                .await;
                return false;
            }
        };
    let item = PolymarketPumpItem::Message(BudgetedPolymarketMessage {
        message,
        recv_time_utc_ms,
        _global_reservation: global_reservation,
        _decoded_reservation: decoded_reservation,
    });
    match events.try_send(item) {
        Ok(()) => true,
        Err(mpsc::error::TrySendError::Full(item)) => {
            match timeout(BUFFER_ACQUIRE_TIMEOUT, events.send(item)).await {
                Ok(Ok(())) => true,
                Ok(Err(_)) => false,
                Err(_) => {
                    let reason = "polymarket_decoded_queue_backpressure_timeout".to_owned();
                    send_polymarket_terminal(
                        events,
                        PolymarketDrainTerminal::Capacity {
                            reason,
                            recv_time_utc_ms,
                            error_kind: io::ErrorKind::TimedOut,
                        },
                    )
                    .await;
                    false
                }
            }
        }
        Err(mpsc::error::TrySendError::Closed(_)) => false,
    }
}

async fn send_polymarket_terminal(
    events: &mpsc::Sender<PolymarketPumpItem>,
    terminal: PolymarketDrainTerminal,
) {
    let _ = events.send(PolymarketPumpItem::Terminal(terminal)).await;
}

async fn acquire_polymarket_fast_path(
    budget: &InflightBudget,
    rows: usize,
    bytes: usize,
    wait: Duration,
) -> io::Result<InflightReservation> {
    match budget.try_acquire_available(rows, bytes) {
        Ok(reservation) => Ok(reservation),
        Err(error) if error.kind() == io::ErrorKind::WouldBlock => {
            budget.acquire(rows, bytes, wait).await
        }
        Err(error) => Err(error),
    }
}

async fn wait_for_polymarket_dedupe_restore(
    mut restore: tokio::task::JoinHandle<Result<Option<LifecycleFingerprintSets>>>,
    cancel: Arc<AtomicBool>,
    control_rx: &mut mpsc::Receiver<PolymarketSourceControl>,
) -> Result<Option<LifecycleFingerprintSets>> {
    loop {
        tokio::select! {
            biased;
            control = control_rx.recv() => {
                let Some(PolymarketSourceControl::Fence {
                    stop_after_fence,
                    resume_after_barrier,
                    reply,
                }) = control else {
                    cancel.store(true, Ordering::Relaxed);
                    restore.await.map_err(|error| {
                        invalid_data(format!(
                            "operator_intervention_required:Polymarket restore join failed:{error}"
                        ))
                    })??;
                    return Ok(None);
                };
                if stop_after_fence {
                    cancel.store(true, Ordering::Relaxed);
                    let joined = restore.await.map_err(|error| {
                        invalid_data(format!(
                            "operator_intervention_required:Polymarket restore join failed:{error}"
                        ))
                    })?;
                    if let Err(error) = joined {
                        let message = format!(
                            "operator_intervention_required:Polymarket restore failed:{error}"
                        );
                        let _ = reply.send(Err(message.clone()));
                        return Err(invalid_data(message).into());
                    }
                    let _ = reply.send(Ok(()));
                    return Ok(None);
                }
                let _ = reply.send(Ok(()));
                if let Some(resume) = resume_after_barrier
                    && resume.await.is_err()
                {
                    cancel.store(true, Ordering::Relaxed);
                    restore.await.map_err(|error| {
                        invalid_data(format!(
                            "operator_intervention_required:Polymarket restore join failed:{error}"
                        ))
                    })??;
                    return Err(
                        invalid_data("Polymarket restore day-barrier resume dropped").into(),
                    );
                }
            }
            joined = &mut restore => {
                let restored = joined
                    .map_err(|error| {
                        invalid_data(format!(
                            "operator_intervention_required:Polymarket restore join failed:{error}"
                        ))
                    })?
                    .map_err(|error| {
                        invalid_data(format!(
                            "operator_intervention_required:Polymarket restore failed:{error}"
                        ))
                    })?;
                return restored.ok_or_else(|| {
                    invalid_data("operator_intervention_required:Polymarket restore cancelled without stop").into()
                }).map(Some);
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn run_polymarket_source_with_spec(
    spec: PolymarketSourceSpec,
    dataset_root: PathBuf,
    sink: SourceEventSink,
    collector_identity: CollectorIdentity,
    deadline_ms: Option<i64>,
    run_started: Instant,
    mut control_rx: mpsc::Receiver<PolymarketSourceControl>,
) -> Result<()> {
    let gamma = GammaClient::new(&spec.gamma_endpoint)?;
    let deadline = deadline_ms.map(|deadline_ms| {
        Instant::now()
            + Duration::from_millis(
                u64::try_from(deadline_ms.saturating_sub(now_ms())).unwrap_or(0),
            )
    });
    let mut recovery = SourceRecoverySupervisor::new(
        "polymarket_market",
        u64::try_from(now_ms()).unwrap_or_default(),
    );
    #[cfg(test)]
    recovery.set_wait_override(spec.recovery_wait_override);
    let mut dedupe = LifecycleFingerprintSets::with_limit(POLYMARKET_FINGERPRINTS_PER_LIFECYCLE);
    let mut dedupe_restored = false;
    let mut last_discovery = None::<BtcUpdownDiscovery>;
    while deadline_ms.is_none_or(|deadline_ms| now_ms() < deadline_ms) {
        let discovery = match discover_initial_polymarket_context(
            &gamma,
            spec.discovery_wait,
            spec.discovery_retry_delay,
            &mut control_rx,
        )
        .await
        {
            Ok(Some(discovery)) if gamma_discovery_is_current(&discovery, now_ms()) => discovery,
            Ok(Some(_)) => continue,
            Ok(None) => return Ok(()),
            Err(PolymarketDiscoveryError::Unavailable(_)) => {
                if !wait_for_source_recovery(&mut recovery, &sink, deadline).await {
                    break;
                }
                continue;
            }
            Err(PolymarketDiscoveryError::Integrity(error)) => {
                record_gap(
                    &sink.gaps,
                    format!("polymarket_discovery_integrity:{error}"),
                );
                return Err(invalid_data(error).into());
            }
        };
        if let Some(previous) = &last_discovery
            && let Err(error) =
                validate_polymarket_discovery_identity_continuity(previous, &discovery)
        {
            record_gap(
                &sink.gaps,
                format!("polymarket_discovery_identity_integrity:{error}"),
            );
            return Err(error);
        }
        last_discovery = Some(discovery.clone());
        if !dedupe_restored {
            let dataset_root = dataset_root.clone();
            let lifecycles = expected_lifecycle_slugs(&discovery);
            let restore_cancel = Arc::new(AtomicBool::new(false));
            let worker_cancel = Arc::clone(&restore_cancel);
            let restore =
                tokio::task::spawn_blocking(move || -> Result<Option<LifecycleFingerprintSets>> {
                    let mut dedupe =
                        LifecycleFingerprintSets::with_limit(POLYMARKET_FINGERPRINTS_PER_LIFECYCLE);
                    dedupe
                        .replace_lifecycles(lifecycles)
                        .map_err(operator_dedupe_error)?;
                    if !restore_polymarket_dedupe_until_cancelled(
                        &dataset_root,
                        &mut dedupe,
                        &worker_cancel,
                    )? {
                        return Ok(None);
                    }
                    Ok(Some(dedupe))
                });
            let Some(restored) =
                wait_for_polymarket_dedupe_restore(restore, restore_cancel, &mut control_rx)
                    .await?
            else {
                return Ok(());
            };
            if !gamma_discovery_is_current(&discovery, now_ms()) {
                continue;
            }
            dedupe = restored;
            dedupe_restored = true;
        } else {
            dedupe
                .replace_lifecycles(expected_lifecycle_slugs(&discovery))
                .map_err(operator_dedupe_error)?;
        }
        let mut market_runtime = PolymarketDrainRuntime::new(
            spec.market_ws_endpoint.clone(),
            spec.ws_config.clone(),
            sink.inflight_budget.clone(),
        )?;
        let mut context = PolymarketProcessingContext::new(discovery.clone());
        let collected = collect_polymarket_single_receiver(
            discovery,
            &mut context,
            &sink,
            &collector_identity,
            deadline_ms,
            run_started,
            &mut market_runtime,
            &gamma,
            &mut dedupe,
            &mut recovery,
            &mut control_rx,
            spec.discovery_wait,
            spec.discovery_retry_delay,
            production_polymarket_timeline_now,
        )
        .await;
        let collected = match collected {
            Ok(()) if market_runtime.pump.is_some() => {
                fence_polymarket_processor(
                    &mut market_runtime,
                    true,
                    &mut context,
                    &sink,
                    &collector_identity,
                    run_started,
                    &mut dedupe,
                    &mut recovery,
                )
                .await
            }
            Err(error) if market_runtime.pump.is_some() => {
                stop_polymarket_after_processing_error(
                    error,
                    &mut market_runtime,
                    &mut context,
                    &sink,
                    &collector_identity,
                    run_started,
                    &mut dedupe,
                    &mut recovery,
                )
                .await
            }
            result => result,
        };
        if let Some(active) = context.discovery_snapshot() {
            last_discovery = Some(active);
        }
        drop(market_runtime);
        match collected {
            Ok(()) => return Ok(()),
            Err(error) if market_source_error_is_retryable(error.as_ref()) => {
                if !wait_for_source_recovery(&mut recovery, &sink, deadline).await {
                    break;
                }
            }
            Err(error) => return Err(error),
        }
    }
    Ok(())
}

fn market_source_error_is_retryable(error: &(dyn Error + 'static)) -> bool {
    matches!(
        error.downcast_ref::<SdkStreamError>(),
        Some(
            SdkStreamError::Connection(_)
                | SdkStreamError::Subscription(_)
                | SdkStreamError::TerminalDisconnected
                | SdkStreamError::Timeout(_)
        )
    ) || matches!(
        error.downcast_ref::<PolymarketDiscoveryError>(),
        Some(PolymarketDiscoveryError::Unavailable(_))
    )
}

#[derive(Debug, PartialEq, Eq)]
enum PolymarketDiscoveryError {
    Unavailable(String),
    Integrity(String),
}

impl std::fmt::Display for PolymarketDiscoveryError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Unavailable(message) => write!(formatter, "Gamma unavailable: {message}"),
            Self::Integrity(message) => write!(formatter, "Gamma integrity failure: {message}"),
        }
    }
}

impl Error for PolymarketDiscoveryError {}

async fn discover_initial_polymarket_context(
    gamma: &GammaClient,
    discovery_wait: Duration,
    discovery_retry_delay: Duration,
    control_rx: &mut mpsc::Receiver<PolymarketSourceControl>,
) -> std::result::Result<Option<BtcUpdownDiscovery>, PolymarketDiscoveryError> {
    let discovery = discover_markets_with_wait(gamma, discovery_wait, discovery_retry_delay);
    tokio::pin!(discovery);
    loop {
        tokio::select! {
            result = &mut discovery => return result.map(Some),
            control = control_rx.recv() => {
                let Some(PolymarketSourceControl::Fence {
                    stop_after_fence,
                    resume_after_barrier,
                    reply,
                }) = control else {
                    return Ok(None);
                };
                let _ = reply.send(Ok(()));
                if stop_after_fence {
                    return Ok(None);
                }
                if let Some(resume) = resume_after_barrier {
                    resume.await.map_err(|_| PolymarketDiscoveryError::Integrity(
                        "Polymarket initial discovery barrier resume dropped".to_owned()
                    ))?;
                }
            }
        }
    }
}

#[derive(Clone, Debug)]
struct PolymarketWsTerminalEvidence {
    source_received_at_utc_ms: i64,
    validation_completed_at_utc_ms: i64,
    source_payload_json: String,
    source_payload_sha256: String,
    platform_timestamp_raw: String,
    platform_timestamp_utc_ms: i64,
    winning_asset_id: String,
    winning_outcome: String,
}

impl PolymarketWsTerminalEvidence {
    fn dynamic_owned_bytes(&self) -> usize {
        self.source_payload_json
            .capacity()
            .saturating_add(self.source_payload_sha256.capacity())
            .saturating_add(self.platform_timestamp_raw.capacity())
            .saturating_add(self.winning_asset_id.capacity())
            .saturating_add(self.winning_outcome.capacity())
    }
}

#[derive(Clone, Debug)]
enum PolymarketTerminalClaim {
    MarketResolvedWs(PolymarketWsTerminalEvidence),
    GammaBySlug(Box<PolymarketMarketMetadataV3Row>),
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct PendingPolymarketIdentity {
    slug: String,
    market_id: String,
    condition_id: String,
    up_asset_id: String,
    down_asset_id: String,
    market_start_utc_ms: i64,
    market_end_utc_ms: i64,
    fixed_identity_verified_at_utc_ms: i64,
    discovery_source_received_at_utc_ms: i64,
    discovery_source_raw_sha256: String,
}

impl PendingPolymarketIdentity {
    fn from_discovered(market: &DiscoveredBtcUpdownMarket) -> Result<Self> {
        Ok(Self {
            slug: market.slug.clone(),
            market_id: market.id.clone(),
            condition_id: market.condition_id.clone(),
            up_asset_id: market.up_asset_id.clone(),
            down_asset_id: market.down_asset_id.clone(),
            market_start_utc_ms: market.start_ts_s.saturating_mul(1_000),
            market_end_utc_ms: market.end_ts_s.saturating_mul(1_000),
            fixed_identity_verified_at_utc_ms: market.fixed_identity_verified_at_utc_ms,
            discovery_source_received_at_utc_ms: market.metadata_received_utc_ms.ok_or_else(
                || invalid_data("pending Polymarket identity is missing discovery receive time"),
            )?,
            discovery_source_raw_sha256: market
                .raw_json_sha256
                .clone()
                .filter(|digest| !digest.trim().is_empty())
                .ok_or_else(|| {
                    invalid_data("pending Polymarket identity is missing discovery digest")
                })?,
        })
    }

    fn owned_bytes(&self) -> usize {
        std::mem::size_of::<Self>()
            .saturating_add(self.slug.capacity())
            .saturating_add(self.market_id.capacity())
            .saturating_add(self.condition_id.capacity())
            .saturating_add(self.up_asset_id.capacity())
            .saturating_add(self.down_asset_id.capacity())
            .saturating_add(self.discovery_source_raw_sha256.capacity())
    }

    fn gamma_terminal_identity(&self) -> GammaTerminalFixedIdentity {
        GammaTerminalFixedIdentity {
            slug: self.slug.clone(),
            market_id: self.market_id.clone(),
            condition_id: self.condition_id.clone(),
            up_asset_id: self.up_asset_id.clone(),
            down_asset_id: self.down_asset_id.clone(),
            market_end_utc_ms: self.market_end_utc_ms,
        }
    }
}

#[derive(Debug)]
struct PendingPolymarketResolution {
    identity: PendingPolymarketIdentity,
    next_attempt_ordinal: u8,
    in_flight_ordinal: Option<u8>,
    poll_abort_handle: Option<tokio::task::AbortHandle>,
    attempts_recorded: u32,
    valid_response_count: u32,
    transport_unavailable_count: u32,
    missed_slot_count: u32,
    last_valid_metadata_received_at_utc_ms: Option<i64>,
    claim: Option<PolymarketTerminalClaim>,
    exhaustion_requested: bool,
    fatal_integrity_error: bool,
    buffered_attempt_rows: Vec<PolymarketMarketMetadataV3Row>,
    ws_fingerprints: VecDeque<[u8; 32]>,
}

impl PendingPolymarketResolution {
    fn new(
        identity: PendingPolymarketIdentity,
        early_claim: Option<PolymarketWsTerminalEvidence>,
    ) -> Self {
        Self {
            identity,
            next_attempt_ordinal: 1,
            in_flight_ordinal: None,
            poll_abort_handle: None,
            attempts_recorded: 0,
            valid_response_count: 0,
            transport_unavailable_count: 0,
            missed_slot_count: 0,
            last_valid_metadata_received_at_utc_ms: None,
            claim: early_claim.map(PolymarketTerminalClaim::MarketResolvedWs),
            exhaustion_requested: false,
            fatal_integrity_error: false,
            buffered_attempt_rows: Vec::new(),
            ws_fingerprints: VecDeque::new(),
        }
    }

    fn budget_horizon_utc_ms(&self) -> i64 {
        self.identity.market_end_utc_ms.saturating_add(8 * 60_000)
    }

    fn slot_utc_ms(&self, ordinal: u8) -> i64 {
        self.identity
            .market_end_utc_ms
            .saturating_add(POLYMARKET_RESOLUTION_FIRST_SLOT_DELAY_MS)
            .saturating_add(
                i64::from(ordinal.saturating_sub(1))
                    .saturating_mul(POLYMARKET_RESOLUTION_SLOT_INTERVAL_MS),
            )
    }

    fn requires_fence(&self) -> bool {
        (self.claim.is_some() || self.exhaustion_requested)
            && self.in_flight_ordinal.is_none()
            && self.poll_abort_handle.is_none()
    }

    fn observe_ws_payload(&mut self, payload: &str) -> bool {
        let digest: [u8; 32] = Sha256::digest(payload.as_bytes()).into();
        if self.ws_fingerprints.contains(&digest) {
            return false;
        }
        if self.ws_fingerprints.len() == POLYMARKET_PENDING_WS_FINGERPRINT_LIMIT {
            self.ws_fingerprints.pop_front();
        }
        self.ws_fingerprints.push_back(digest);
        true
    }

    fn owned_bytes(&self) -> usize {
        let claim_bytes = match &self.claim {
            Some(PolymarketTerminalClaim::MarketResolvedWs(claim)) => claim.dynamic_owned_bytes(),
            Some(PolymarketTerminalClaim::GammaBySlug(row)) => row
                .to_draft_json()
                .map_or(MAX_TYPED_ROW_BYTES.saturating_add(1), |json| json.len()),
            None => 0,
        };
        let buffered_bytes = self
            .buffered_attempt_rows
            .iter()
            .fold(0_usize, |total, row| {
                total.saturating_add(
                    row.to_draft_json()
                        .map_or(MAX_TYPED_ROW_BYTES.saturating_add(1), |json| json.len()),
                )
            });
        std::mem::size_of::<Self>()
            .saturating_add(self.identity.owned_bytes())
            .saturating_add(claim_bytes)
            .saturating_add(buffered_bytes)
            .saturating_add(self.ws_fingerprints.capacity().saturating_mul(32))
    }
}

#[derive(Debug)]
enum GammaResolutionPollFailure {
    Transport {
        class: ResolutionTransportErrorClass,
        http_status: Option<u16>,
    },
    SdkDecodeOrSchema,
}

#[derive(Debug)]
struct GammaResolutionPollCompletion {
    slug: String,
    ordinal: u8,
    scheduled_at_utc_ms: i64,
    fetch_start_utc_ms: i64,
    completed_at_utc_ms: i64,
    result: std::result::Result<SdkGammaMarket, GammaResolutionPollFailure>,
}

struct PolymarketProcessingContext {
    current: Option<DiscoveredBtcUpdownMarket>,
    next: Option<DiscoveredBtcUpdownMarket>,
    pending: BTreeMap<String, PendingPolymarketResolution>,
    early_ws_claims: BTreeMap<String, PolymarketWsTerminalEvidence>,
    source_authorities: Vec<PolymarketMetadataV3ReferenceRecord>,
    active_asset_to_slug: BTreeMap<String, String>,
    asset_to_slug: BTreeMap<String, String>,
    actor_now_utc_ms: i64,
    actor_utc_now: Option<Arc<dyn Fn() -> i64 + Send + Sync>>,
}

#[derive(Clone, Copy, Debug)]
struct PolymarketTimelineNow {
    utc_ms: i64,
    monotonic: TokioInstant,
}

fn production_polymarket_timeline_now() -> PolymarketTimelineNow {
    PolymarketTimelineNow {
        utc_ms: now_ms(),
        monotonic: TokioInstant::now(),
    }
}

impl PolymarketProcessingContext {
    fn new(discovery: BtcUpdownDiscovery) -> Self {
        let mut context = Self {
            current: Some(discovery.current),
            next: discovery.next,
            pending: BTreeMap::new(),
            early_ws_claims: BTreeMap::new(),
            source_authorities: Vec::new(),
            active_asset_to_slug: BTreeMap::new(),
            asset_to_slug: BTreeMap::new(),
            actor_now_utc_ms: 0,
            actor_utc_now: None,
        };
        context.rebuild_asset_to_slug();
        context
    }

    fn replace_discovery(&mut self, discovery: BtcUpdownDiscovery) {
        self.current = Some(discovery.current);
        self.next = discovery.next;
        self.rebuild_asset_to_slug();
    }

    fn discovery_snapshot(&self) -> Option<BtcUpdownDiscovery> {
        self.current.clone().map(|current| BtcUpdownDiscovery {
            current,
            next: self.next.clone(),
            relation: None,
        })
    }

    fn rebuild_asset_to_slug(&mut self) {
        self.active_asset_to_slug.clear();
        self.asset_to_slug.clear();
        for market in self.current.iter().chain(self.next.iter()) {
            self.active_asset_to_slug
                .insert(market.up_asset_id.clone(), market.slug.clone());
            self.active_asset_to_slug
                .insert(market.down_asset_id.clone(), market.slug.clone());
            self.asset_to_slug
                .insert(market.up_asset_id.clone(), market.slug.clone());
            self.asset_to_slug
                .insert(market.down_asset_id.clone(), market.slug.clone());
        }
        for pending in self.pending.values() {
            self.asset_to_slug.insert(
                pending.identity.up_asset_id.clone(),
                pending.identity.slug.clone(),
            );
            self.asset_to_slug.insert(
                pending.identity.down_asset_id.clone(),
                pending.identity.slug.clone(),
            );
        }
        let owned_slugs = self
            .current
            .iter()
            .chain(self.next.iter())
            .map(|market| market.slug.as_str())
            .chain(self.pending.keys().map(String::as_str))
            .collect::<BTreeSet<_>>();
        self.early_ws_claims
            .retain(|slug, _| owned_slugs.contains(slug.as_str()));
        self.source_authorities.retain(|authority| {
            self.current
                .iter()
                .chain(self.next.iter())
                .any(|market| polymarket_authority_matches_discovered(authority, market))
                || self.pending.values().any(|pending| {
                    polymarket_authority_matches_identity(authority, &pending.identity)
                })
        });
    }

    fn desired_assets(&self) -> Result<BTreeSet<U256>> {
        self.asset_to_slug
            .keys()
            .map(|asset| U256::from_str(asset).map_err(Into::into))
            .collect()
    }

    fn matched_resolved_slug(&self, event: &MarketResolved) -> Option<String> {
        let condition_id = event.market.to_string();
        let event_assets = event
            .asset_ids
            .iter()
            .map(ToString::to_string)
            .collect::<BTreeSet<_>>();
        let winner = event.winning_asset_id.to_string();
        if let Some(market) = self.current.iter().chain(self.next.iter()).find(|market| {
            market.id == event.id
                || market.condition_id == condition_id
                || event.slug.as_deref() == Some(market.slug.as_str())
                || event_assets.contains(&market.up_asset_id)
                || event_assets.contains(&market.down_asset_id)
                || winner == market.up_asset_id
                || winner == market.down_asset_id
        }) {
            return Some(market.slug.clone());
        }
        self.pending.values().find_map(|pending| {
            let identity = &pending.identity;
            (identity.market_id == event.id
                || identity.condition_id == condition_id
                || event.slug.as_deref() == Some(identity.slug.as_str())
                || event_assets.contains(&identity.up_asset_id)
                || event_assets.contains(&identity.down_asset_id)
                || winner == identity.up_asset_id
                || winner == identity.down_asset_id)
                .then(|| identity.slug.clone())
        })
    }

    fn pending_requires_fence(&self) -> bool {
        self.pending
            .values()
            .any(PendingPolymarketResolution::requires_fence)
    }

    fn pending_owned_bytes(&self) -> usize {
        let pending = self.pending.values().fold(0_usize, |total, pending| {
            total.saturating_add(pending.owned_bytes())
        });
        let early_claims = self
            .early_ws_claims
            .iter()
            .fold(pending, |total, (slug, evidence)| {
                total
                    .saturating_add(std::mem::size_of::<String>())
                    .saturating_add(slug.capacity())
                    .saturating_add(std::mem::size_of::<PolymarketWsTerminalEvidence>())
                    .saturating_add(evidence.dynamic_owned_bytes())
            });
        self.source_authorities
            .iter()
            .fold(early_claims, |total, authority| {
                total.saturating_add(polymarket_authority_owned_bytes(authority))
            })
    }

    fn ensure_pending_bounds(&self) -> Result<()> {
        if self.pending.len() > POLYMARKET_PENDING_MAX_MARKETS {
            return Err(invalid_data(format!(
                "Polymarket pending market bound exceeded:count={}:limit={POLYMARKET_PENDING_MAX_MARKETS}",
                self.pending.len()
            ))
            .into());
        }
        if self.source_authorities.len() > POLYMARKET_PENDING_MAX_MARKETS.saturating_add(2) {
            return Err(invalid_data(format!(
                "Polymarket source authority bound exceeded:count={}:limit={}",
                self.source_authorities.len(),
                POLYMARKET_PENDING_MAX_MARKETS.saturating_add(2)
            ))
            .into());
        }
        let owned_bytes = self.pending_owned_bytes();
        if owned_bytes >= POLYMARKET_PENDING_STATE_MAX_BYTES {
            return Err(invalid_data(format!(
                "Polymarket pending state byte bound exceeded:bytes={owned_bytes}:limit={POLYMARKET_PENDING_STATE_MAX_BYTES}"
            ))
            .into());
        }
        Ok(())
    }

    fn validation_now_utc_ms(&self) -> i64 {
        self.actor_utc_now
            .as_ref()
            .map_or(self.actor_now_utc_ms, |now| now())
    }

    fn register_source_authority(
        &mut self,
        authority: PolymarketMetadataV3ReferenceRecord,
    ) -> Result<()> {
        if !authority.source_evidence_payload_present
            || !matches!(
                authority.metadata_row_kind.as_str(),
                "metadata_snapshot" | "market_state_transition"
            )
            || authority.source_evidence_origin.as_deref()
                != Some(SourceEvidenceOrigin::GammaMarketsDiscovery.as_str())
            || authority.source_evidence_received_at_utc.is_none()
            || authority
                .source_evidence_raw_sha256
                .as_deref()
                .is_none_or(str::is_empty)
        {
            return Err(invalid_data(format!(
                "Polymarket source authority is not a complete discovery evidence row:slug={}",
                authority.slug
            ))
            .into());
        }
        let same_identity = |candidate: &PolymarketMetadataV3ReferenceRecord| {
            polymarket_authority_same_fixed_identity(candidate, &authority)
        };
        let same_complete_tuple = |candidate: &PolymarketMetadataV3ReferenceRecord| {
            same_identity(candidate)
                && candidate.source_evidence_origin == authority.source_evidence_origin
                && candidate.source_evidence_received_at_utc
                    == authority.source_evidence_received_at_utc
                && candidate.source_evidence_raw_sha256 == authority.source_evidence_raw_sha256
        };
        let duplicate = self.source_authorities.iter().any(same_complete_tuple);
        let mut updated = self.source_authorities.clone();
        if !duplicate {
            updated.retain(|candidate| !same_identity(candidate));
        }
        updated.push(authority);
        if updated.len() > POLYMARKET_PENDING_MAX_MARKETS.saturating_add(2) {
            return Err(invalid_data(format!(
                "Polymarket source authority bound exceeded:count={}:limit={}",
                updated.len(),
                POLYMARKET_PENDING_MAX_MARKETS.saturating_add(2)
            ))
            .into());
        }
        self.source_authorities = updated;
        self.ensure_pending_bounds()
    }

    fn validate_local_transition_authority(
        &self,
        row: &PolymarketMarketMetadataV3Row,
    ) -> Result<()> {
        let mut records = self.source_authorities.clone();
        records.push(PolymarketMetadataV3ReferenceRecord::from(row));
        validate_polymarket_metadata_v3_local_references(&records).map_err(|error| {
            invalid_data(format!(
                "polymarket_metadata_source_reference_integrity:{error}"
            ))
            .into()
        })
    }
}

fn polymarket_authority_same_fixed_identity(
    left: &PolymarketMetadataV3ReferenceRecord,
    right: &PolymarketMetadataV3ReferenceRecord,
) -> bool {
    left.slug == right.slug
        && left.condition_id == right.condition_id
        && left.clob_market_id == right.clob_market_id
        && left.asset_ids == right.asset_ids
        && left.market_start_utc == right.market_start_utc
        && left.market_end_utc == right.market_end_utc
        && left.fixed_identity_verified_at_utc == right.fixed_identity_verified_at_utc
}

fn polymarket_authority_matches_discovered(
    authority: &PolymarketMetadataV3ReferenceRecord,
    market: &DiscoveredBtcUpdownMarket,
) -> bool {
    authority.slug == market.slug
        && authority.condition_id == market.condition_id
        && authority.clob_market_id == market.id
        && authority.asset_ids
            == serde_json::to_string(&[market.up_asset_id.as_str(), market.down_asset_id.as_str()])
                .unwrap_or_default()
        && authority.market_start_utc == market.start_ts_s.saturating_mul(1_000)
        && authority.market_end_utc == market.end_ts_s.saturating_mul(1_000)
        && authority.fixed_identity_verified_at_utc == market.fixed_identity_verified_at_utc_ms
}

fn polymarket_authority_matches_identity(
    authority: &PolymarketMetadataV3ReferenceRecord,
    identity: &PendingPolymarketIdentity,
) -> bool {
    authority.slug == identity.slug
        && authority.condition_id == identity.condition_id
        && authority.clob_market_id == identity.market_id
        && authority.asset_ids
            == serde_json::to_string(&[
                identity.up_asset_id.as_str(),
                identity.down_asset_id.as_str(),
            ])
            .unwrap_or_default()
        && authority.market_start_utc == identity.market_start_utc_ms
        && authority.market_end_utc == identity.market_end_utc_ms
        && authority.fixed_identity_verified_at_utc == identity.fixed_identity_verified_at_utc_ms
}

fn polymarket_authority_owned_bytes(authority: &PolymarketMetadataV3ReferenceRecord) -> usize {
    std::mem::size_of::<PolymarketMetadataV3ReferenceRecord>()
        .saturating_add(authority.metadata_row_kind.capacity())
        .saturating_add(authority.slug.capacity())
        .saturating_add(authority.condition_id.capacity())
        .saturating_add(authority.clob_market_id.capacity())
        .saturating_add(authority.asset_ids.capacity())
        .saturating_add(
            authority
                .source_evidence_origin
                .as_ref()
                .map_or(0, String::capacity),
        )
        .saturating_add(
            authority
                .source_evidence_raw_sha256
                .as_ref()
                .map_or(0, String::capacity),
        )
}

fn polymarket_drain_terminal_error(
    terminal: PolymarketDrainTerminal,
    sink: &SourceEventSink,
) -> Box<dyn Error + Send + Sync> {
    match terminal {
        PolymarketDrainTerminal::Sdk(error) => {
            if let SdkStreamError::Lagged(count) = &error {
                sink.source_queue_backpressure
                    .record_lag("polymarket_market", now_ms(), *count);
            }
            if !matches!(
                error,
                SdkStreamError::Connection(_)
                    | SdkStreamError::Subscription(_)
                    | SdkStreamError::TerminalDisconnected
                    | SdkStreamError::Timeout(_)
            ) {
                record_gap(&sink.gaps, format!("polymarket_sdk_stream_fatal:{error}"));
            }
            error.into()
        }
        PolymarketDrainTerminal::Capacity {
            reason,
            recv_time_utc_ms,
            error_kind,
        } => {
            if error_kind == io::ErrorKind::TimedOut {
                sink.source_queue_backpressure.record_timeout();
            }
            let reason = format!(
                "{reason}:decoded_messages_dropped=1:normalized_rows=unknown:recv_time_utc_ms={recv_time_utc_ms}"
            );
            record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
            io::Error::new(error_kind, reason).into()
        }
        PolymarketDrainTerminal::QueueClosed => {
            let reason = "polymarket_fast_drain_queue_closed".to_owned();
            record_gap(&sink.gaps, reason.clone());
            io::Error::new(io::ErrorKind::BrokenPipe, reason).into()
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn process_polymarket_budgeted_message(
    budgeted: BudgetedPolymarketMessage,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    _recovery: &mut SourceRecoverySupervisor,
) -> Result<()> {
    let BudgetedPolymarketMessage {
        message,
        recv_time_utc_ms,
        _global_reservation: message_global_reservation,
        _decoded_reservation: message_decoded_reservation,
    } = budgeted;
    let _message_global_reservation = message_global_reservation;
    let _message_decoded_reservation = message_decoded_reservation;
    if let WsMessage::MarketResolved(event) = &message {
        return process_polymarket_market_resolved(
            event,
            recv_time_utc_ms,
            context,
            sink,
            collector_identity,
            run_started,
        )
        .await;
    }
    let post_end_asset_to_slug = context
        .current
        .as_ref()
        .filter(|current| recv_time_utc_ms >= current.end_ts_s.saturating_mul(1_000))
        .map(|current| {
            let mut routes = context.active_asset_to_slug.clone();
            routes.remove(&current.up_asset_id);
            routes.remove(&current.down_asset_id);
            routes
        });
    let routed_asset_to_slug = post_end_asset_to_slug
        .as_ref()
        .unwrap_or(&context.active_asset_to_slug);
    let Some(discovery) = context.discovery_snapshot() else {
        return Ok(());
    };
    let (market_rows, metadata_rows) =
        polymarket_target_fanout_counts(&message, routed_asset_to_slug);
    let mut canonical_reservation = match sink
        .inflight_budget
        .acquire(
            0,
            POLYMARKET_PROCESSOR_STAGING_MAX_BYTES,
            BUFFER_ACQUIRE_TIMEOUT,
        )
        .await
    {
        Ok(reservation) => reservation,
        Err(error) => {
            sink.source_queue_backpressure.record_timeout();
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
            let reason = format!("polymarket_canonical_budget_failed:{error}");
            record_gap_at(&sink.gaps, recv_time_utc_ms, reason);
            return Err(error.into());
        }
    };
    let source_native_payload_json = match prepare_polymarket_message(&message) {
        Ok(payload) => payload,
        Err(error) => {
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
            record_gap_at(
                &sink.gaps,
                recv_time_utc_ms,
                format!("polymarket_message_prepare_failed:{error}"),
            );
            return Err(error);
        }
    };
    let Some(source_native_payload_json) = source_native_payload_json else {
        return Ok(());
    };
    let canonical_owned_bytes =
        std::mem::size_of::<String>().saturating_add(source_native_payload_json.capacity());
    if canonical_owned_bytes > MAX_TYPED_ROW_BYTES {
        let reason = format!(
            "operator_intervention_required:Polymarket canonical payload exceeds {MAX_TYPED_ROW_BYTES} owned bytes:bytes={canonical_owned_bytes}"
        );
        record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
        record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
        return Err(invalid_data(reason).into());
    }
    if let Err(error) = canonical_reservation.shrink_to(0, canonical_owned_bytes) {
        record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
        let reason = format!("polymarket_canonical_reservation_shrink_failed:{error}");
        record_gap_at(&sink.gaps, recv_time_utc_ms, reason);
        return Err(error.into());
    }
    let _canonical_reservation = canonical_reservation;
    let accepted = match polymarket_message_passes_dedupe(
        dedupe,
        &discovery,
        routed_asset_to_slug,
        &message,
        &source_native_payload_json,
        recv_time_utc_ms,
        Some(&sink.source_queue_backpressure),
    ) {
        Ok(accepted) => accepted,
        Err(error) => {
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
            record_gap_at(
                &sink.gaps,
                recv_time_utc_ms,
                format!("polymarket_message_dedupe_failed:{error}"),
            );
            return Err(error);
        }
    };
    if !accepted {
        return Ok(());
    }
    let dedupe_lifecycle =
        polymarket_message_lifecycle_slug(&message, &discovery, routed_asset_to_slug);
    let fanout_rows = market_rows.saturating_add(metadata_rows);
    let fanout_staging = if fanout_rows > 0 {
        match sink
            .inflight_budget
            .acquire(
                0,
                POLYMARKET_PROCESSOR_STAGING_MAX_BYTES,
                BUFFER_ACQUIRE_TIMEOUT,
            )
            .await
        {
            Ok(reservation) => Some(reservation),
            Err(error) => {
                sink.source_queue_backpressure.record_timeout();
                record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
                let reason = format!("polymarket_fanout_staging_budget_failed:{error}");
                record_gap_at(&sink.gaps, recv_time_utc_ms, reason);
                return Err(error.into());
            }
        }
    } else {
        None
    };
    let mut measured_bytes = Vec::with_capacity(fanout_rows);
    let measured_outcome = match visit_polymarket_events(
        &message,
        &discovery,
        routed_asset_to_slug,
        collector_identity,
        recv_time_utc_ms,
        &source_native_payload_json,
        |event| {
            let owned_bytes = owned_event_bytes(&event);
            if owned_bytes > MAX_TYPED_ROW_BYTES {
                return Err(invalid_data(format!(
                    "operator_intervention_required:max_typed_row_bytes_exceeded:{}:bytes={owned_bytes}:limit={MAX_TYPED_ROW_BYTES}",
                    event.source_kind
                ))
                .into());
            }
            measured_bytes.push(owned_bytes);
            Ok(())
        },
    ) {
        Ok(outcome) => outcome,
        Err(error) => {
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
            record_gap_at(&sink.gaps, recv_time_utc_ms, error.to_string());
            return Err(error);
        }
    };
    if measured_bytes.len() != fanout_rows {
        let reason = format!(
            "Polymarket fan-out count changed while measuring:expected={fanout_rows}:actual={}",
            measured_bytes.len()
        );
        record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
        record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
        return Err(invalid_data(reason).into());
    }
    let fanout_bytes = match measured_bytes.iter().try_fold(0_usize, |total, bytes| {
        total
            .checked_add(*bytes)
            .ok_or_else(|| invalid_data("Polymarket fan-out byte total overflow"))
    }) {
        Ok(bytes) => bytes,
        Err(error) => {
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
            record_gap_at(&sink.gaps, recv_time_utc_ms, error.to_string());
            return Err(error.into());
        }
    };
    let mut fanout_reservation = match sink
        .inflight_budget
        .acquire(fanout_rows, fanout_bytes, BUFFER_ACQUIRE_TIMEOUT)
        .await
    {
        Ok(reservation) => reservation,
        Err(error) => {
            sink.source_queue_backpressure.record_timeout();
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
            let reason = format!("polymarket_fanout_budget_failed:{error}");
            record_gap_at(&sink.gaps, recv_time_utc_ms, reason);
            return Err(error.into());
        }
    };
    let mut prepared = Vec::with_capacity(fanout_rows);
    let mut measured_bytes = measured_bytes.into_iter();
    let outcome = match visit_polymarket_events(
        &message,
        &discovery,
        routed_asset_to_slug,
        collector_identity,
        recv_time_utc_ms,
        &source_native_payload_json,
        |event| {
            let owned_bytes = owned_event_bytes(&event);
            let expected_bytes = measured_bytes.next().ok_or_else(|| {
                invalid_data("Polymarket fan-out second pass produced an extra row")
            })?;
            if owned_bytes != expected_bytes {
                return Err(invalid_data(format!(
                    "Polymarket fan-out owned size changed between passes:first={expected_bytes}:second={owned_bytes}"
                ))
                .into());
            }
            let reservation = fanout_reservation.split(1, owned_bytes)?;
            prepared.push(InflightRawEvent {
                event,
                control: None,
                admission_gaps: Vec::new(),
                raw_day_permit: None,
                _source_recv_monotonic_ms: monotonic_ms(run_started),
                _reservation: Some(reservation),
            });
            Ok(())
        },
    ) {
        Ok(outcome) => outcome,
        Err(error) => {
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
            record_gap_at(&sink.gaps, recv_time_utc_ms, error.to_string());
            return Err(error);
        }
    };
    if measured_bytes.next().is_some() || outcome.matched_assets != measured_outcome.matched_assets
    {
        let reason = "Polymarket fan-out changed between measurement and build".to_owned();
        record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
        record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
        return Err(invalid_data(reason).into());
    }
    drop(fanout_reservation);
    drop(fanout_staging);
    send_polymarket_events_atomically(sink, recv_time_utc_ms, prepared, || {
        commit_polymarket_message_dedupe(
            dedupe,
            dedupe_lifecycle.as_deref(),
            &source_native_payload_json,
        )
    })
    .await?;
    Ok(())
}

fn validate_polymarket_market_resolved_identity(
    identity: &PendingPolymarketIdentity,
    event: &MarketResolved,
) -> Result<()> {
    if event.id != identity.market_id {
        return Err(invalid_data(format!(
            "Polymarket market_resolved market id mismatch:slug={}",
            identity.slug
        ))
        .into());
    }
    if event.market.to_string() != identity.condition_id {
        return Err(invalid_data(format!(
            "Polymarket market_resolved condition id mismatch:slug={}",
            identity.slug
        ))
        .into());
    }
    if event
        .slug
        .as_deref()
        .is_some_and(|slug| slug != identity.slug)
    {
        return Err(invalid_data(format!(
            "Polymarket market_resolved slug mismatch:slug={}",
            identity.slug
        ))
        .into());
    }
    let observed_assets = event
        .asset_ids
        .iter()
        .map(ToString::to_string)
        .collect::<BTreeSet<_>>();
    let expected_assets =
        BTreeSet::from([identity.up_asset_id.clone(), identity.down_asset_id.clone()]);
    if event.asset_ids.len() != 2
        || observed_assets.len() != 2
        || observed_assets != expected_assets
    {
        return Err(invalid_data(format!(
            "Polymarket market_resolved asset mapping mismatch:slug={}",
            identity.slug
        ))
        .into());
    }
    if !event.outcomes.is_empty()
        && (event.outcomes.len() != 2
            || event
                .asset_ids
                .iter()
                .zip(&event.outcomes)
                .any(
                    |(asset, outcome)| match outcome.trim().to_ascii_lowercase().as_str() {
                        "up" => asset.to_string() != identity.up_asset_id,
                        "down" => asset.to_string() != identity.down_asset_id,
                        _ => true,
                    },
                ))
    {
        return Err(invalid_data(format!(
            "Polymarket market_resolved outcome mapping mismatch:slug={}",
            identity.slug
        ))
        .into());
    }
    let winning_asset_id = event.winning_asset_id.to_string();
    let expected_winning_outcome = if winning_asset_id == identity.up_asset_id {
        "up"
    } else if winning_asset_id == identity.down_asset_id {
        "down"
    } else {
        return Err(invalid_data(format!(
            "Polymarket market_resolved winner outside fixed assets:slug={}",
            identity.slug
        ))
        .into());
    };
    if !event
        .winning_outcome
        .trim()
        .eq_ignore_ascii_case(expected_winning_outcome)
    {
        return Err(invalid_data(format!(
            "Polymarket market_resolved winning outcome mismatch:slug={}",
            identity.slug
        ))
        .into());
    }
    Ok(())
}

async fn process_polymarket_market_resolved(
    event: &MarketResolved,
    recv_time_utc_ms: i64,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
) -> Result<()> {
    let source_payload_json =
        prepare_polymarket_message(&WsMessage::MarketResolved(event.clone()))?
            .ok_or_else(|| invalid_data("decoded market_resolved is missing source payload"))?;
    let matched_slug = context.matched_resolved_slug(event);
    let source_identifier = matched_slug
        .as_deref()
        .or(event.slug.as_deref())
        .unwrap_or(event.id.as_str());
    let raw = with_polymarket_row_context(
        polymarket_market_resolved_raw_json(event),
        matched_slug.as_deref(),
        &source_payload_json,
    );
    send_event(
        sink,
        run_started,
        raw_event_with_recv_time(
            "polymarket_market",
            "market_resolved",
            source_identifier,
            Some(event.timestamp.to_string()),
            recv_time_utc_ms,
            MARKET_WS_ENDPOINT,
            collector_identity,
            raw,
        ),
    )
    .await?;

    let Some(slug) = matched_slug else {
        return Ok(());
    };
    let identity = if let Some(pending) = context.pending.get(&slug) {
        pending.identity.clone()
    } else {
        let market = context
            .current
            .iter()
            .chain(context.next.iter())
            .find(|market| market.slug == slug)
            .ok_or_else(|| invalid_data("matched market_resolved identity disappeared"))?;
        PendingPolymarketIdentity::from_discovered(market)?
    };
    validate_polymarket_market_resolved_identity(&identity, event)?;

    let validation_completed_at_utc_ms = context.validation_now_utc_ms();
    if validation_completed_at_utc_ms < recv_time_utc_ms {
        return Err(invalid_data(format!(
            "Polymarket market_resolved validation clock regressed:received={recv_time_utc_ms}:validation_completed={validation_completed_at_utc_ms}"
        ))
        .into());
    }
    let evidence = PolymarketWsTerminalEvidence {
        source_received_at_utc_ms: recv_time_utc_ms,
        validation_completed_at_utc_ms,
        source_payload_sha256: Sha256::digest(source_payload_json.as_bytes())
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect(),
        source_payload_json,
        platform_timestamp_raw: event.timestamp.to_string(),
        platform_timestamp_utc_ms: event.timestamp,
        winning_asset_id: event.winning_asset_id.to_string(),
        winning_outcome: event.winning_outcome.clone(),
    };
    if let Some(pending) = context.pending.get_mut(&slug) {
        if !pending.observe_ws_payload(&evidence.source_payload_json) {
            return Ok(());
        }
        if pending.claim.is_none() {
            pending.claim = Some(PolymarketTerminalClaim::MarketResolvedWs(evidence));
        }
        context.ensure_pending_bounds()?;
        return Ok(());
    }
    if context.early_ws_claims.len() >= POLYMARKET_PENDING_MAX_MARKETS
        && !context.early_ws_claims.contains_key(&slug)
    {
        return Err(invalid_data("Polymarket early WS terminal claim bound exceeded").into());
    }
    context.early_ws_claims.entry(slug).or_insert(evidence);
    context.ensure_pending_bounds()?;
    Ok(())
}

fn polymarket_processing_sink_unusable(
    error: &(dyn Error + 'static),
    sink: &SourceEventSink,
) -> bool {
    if sink.tx.is_closed() {
        return true;
    }
    error.downcast_ref::<io::Error>().is_some_and(|error| {
        matches!(
            error.kind(),
            io::ErrorKind::BrokenPipe | io::ErrorKind::TimedOut
        )
    })
}

fn record_abandoned_polymarket_message(
    message: &BudgetedPolymarketMessage,
    context: &PolymarketProcessingContext,
    sink: &SourceEventSink,
) -> usize {
    let (market_rows, metadata_rows) =
        polymarket_target_fanout_counts(&message.message, &context.asset_to_slug);
    record_polymarket_fanout_drop(sink, message.recv_time_utc_ms, market_rows, metadata_rows);
    market_rows.saturating_add(metadata_rows)
}

#[allow(clippy::too_many_arguments)]
async fn stop_polymarket_after_processing_error(
    first_error: Box<dyn Error + Send + Sync>,
    market_runtime: &mut PolymarketDrainRuntime,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
) -> Result<()> {
    let mut primary_error = first_error;
    let mut can_process = !polymarket_processing_sink_unusable(primary_error.as_ref(), sink);
    let request = match market_runtime.request_fence(true).await {
        Ok(request) => Some(request),
        Err(error) => {
            record_gap(
                &sink.gaps,
                format!("polymarket_processing_error_stop_request_failed:{error}"),
            );
            market_runtime.abort_pump_and_wait().await;
            None
        }
    };
    let expected_stop_id = match request {
        Some(PolymarketFenceRequest::Queued(id)) => Some(id),
        Some(PolymarketFenceRequest::Paused { id, .. }) => Some(id),
        Some(PolymarketFenceRequest::PumpClosed) | None => None,
    };
    let mut abandoned_by_day = BTreeMap::<String, (usize, usize, i64, i64)>::new();
    loop {
        match market_runtime.recv(Duration::from_secs(1)).await {
            Ok(Some(PolymarketDrainEvent::Message(message))) => {
                if can_process {
                    let recv_time_utc_ms = message.recv_time_utc_ms;
                    if let Err(error) = process_polymarket_budgeted_message(
                        message,
                        context,
                        sink,
                        collector_identity,
                        run_started,
                        dedupe,
                        recovery,
                    )
                    .await
                    {
                        let sink_unusable =
                            polymarket_processing_sink_unusable(error.as_ref(), sink);
                        record_gap_at(
                            &sink.gaps,
                            recv_time_utc_ms,
                            format!("polymarket_processing_error_during_drain:{error}"),
                        );
                        if market_source_error_is_retryable(primary_error.as_ref())
                            && !market_source_error_is_retryable(error.as_ref())
                        {
                            primary_error = error;
                        }
                        if sink_unusable {
                            can_process = false;
                        }
                    }
                } else {
                    let recv_time_utc_ms = message.recv_time_utc_ms;
                    let rows = record_abandoned_polymarket_message(&message, context, sink);
                    let utc_day = utc_day_string_from_ms(recv_time_utc_ms)
                        .unwrap_or_else(|| "unknown".to_owned());
                    let entry = abandoned_by_day.entry(utc_day).or_insert((
                        0,
                        0,
                        recv_time_utc_ms,
                        recv_time_utc_ms,
                    ));
                    entry.0 = entry.0.saturating_add(1);
                    entry.1 = entry.1.saturating_add(rows);
                    entry.2 = entry.2.min(recv_time_utc_ms);
                    entry.3 = entry.3.max(recv_time_utc_ms);
                }
            }
            Ok(Some(PolymarketDrainEvent::Fence {
                id,
                stop_after_fence,
            })) => {
                if stop_after_fence && expected_stop_id.is_none_or(|expected| expected == id) {
                    break;
                }
            }
            Ok(None) => {
                if market_runtime.pump.is_none() {
                    break;
                }
            }
            Err(PolymarketDrainTerminal::QueueClosed) => break,
            Err(terminal) => {
                let cleanup_error = polymarket_drain_terminal_error(terminal, sink);
                if !market_source_error_is_retryable(cleanup_error.as_ref()) {
                    record_gap(
                        &sink.gaps,
                        format!(
                            "polymarket_processing_error_terminal_during_drain:{cleanup_error}"
                        ),
                    );
                }
                if market_source_error_is_retryable(primary_error.as_ref())
                    && !market_source_error_is_retryable(cleanup_error.as_ref())
                {
                    primary_error = cleanup_error;
                }
                break;
            }
        }
    }
    if let Err(error) = market_runtime.wait_pump_stopped().await {
        record_gap(
            &sink.gaps,
            format!("polymarket_processing_error_pump_join_failed:{error}"),
        );
        if market_source_error_is_retryable(primary_error.as_ref())
            && !market_source_error_is_retryable(error.as_ref())
        {
            primary_error = error;
        }
    }
    for (utc_day, (messages, rows, first_recv, last_recv)) in abandoned_by_day {
        record_gap_for_day(
            &sink.gaps,
            &utc_day,
            format!(
                "polymarket_accepted_decoded_messages_discarded:messages={messages}:rows={rows}:first_recv_time_utc_ms={first_recv}:last_recv_time_utc_ms={last_recv}",
            ),
        );
    }
    Err(primary_error)
}

#[allow(clippy::too_many_arguments)]
async fn drain_polymarket_fence(
    market_runtime: &mut PolymarketDrainRuntime,
    request: PolymarketFenceRequest,
    expected_stop: bool,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
) -> Result<Option<oneshot::Sender<()>>> {
    let (expected_id, resume) = match request {
        PolymarketFenceRequest::Queued(id) => (Some(id), None),
        PolymarketFenceRequest::Paused { id, resume } => (Some(id), Some(resume)),
        PolymarketFenceRequest::PumpClosed => (None, None),
    };
    loop {
        match market_runtime.recv(Duration::from_secs(1)).await {
            Ok(Some(PolymarketDrainEvent::Message(message))) => {
                if let Err(error) = process_polymarket_budgeted_message(
                    message,
                    context,
                    sink,
                    collector_identity,
                    run_started,
                    dedupe,
                    recovery,
                )
                .await
                {
                    drop(resume);
                    return stop_polymarket_after_processing_error(
                        error,
                        market_runtime,
                        context,
                        sink,
                        collector_identity,
                        run_started,
                        dedupe,
                        recovery,
                    )
                    .await
                    .map(|()| None);
                }
            }
            Ok(Some(PolymarketDrainEvent::Fence {
                id,
                stop_after_fence,
            })) => {
                if expected_id == Some(id) && stop_after_fence == expected_stop {
                    return Ok(resume);
                }
                return Err(invalid_data(format!(
                    "unexpected Polymarket fast-drain fence:id={id}:stop={stop_after_fence}"
                ))
                .into());
            }
            Ok(None) => {}
            Err(terminal) => return Err(polymarket_drain_terminal_error(terminal, sink)),
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn fence_polymarket_processor(
    market_runtime: &mut PolymarketDrainRuntime,
    stop_after_fence: bool,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
) -> Result<()> {
    let request = market_runtime.request_fence(stop_after_fence).await?;
    let resume = drain_polymarket_fence(
        market_runtime,
        request,
        stop_after_fence,
        context,
        sink,
        collector_identity,
        run_started,
        dedupe,
        recovery,
    )
    .await?;
    if resume.is_some() {
        return Err(invalid_data("ordinary Polymarket fence returned a pause handle").into());
    }
    if stop_after_fence {
        market_runtime.wait_pump_stopped().await?;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
async fn pause_polymarket_processor(
    market_runtime: &mut PolymarketDrainRuntime,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
) -> Result<oneshot::Sender<()>> {
    let request = market_runtime.request_paused_fence().await?;
    drain_polymarket_fence(
        market_runtime,
        request,
        false,
        context,
        sink,
        collector_identity,
        run_started,
        dedupe,
        recovery,
    )
    .await?
    .ok_or_else(|| invalid_data("Polymarket pump closed before paused fence").into())
}

#[allow(clippy::too_many_arguments)]
async fn handle_polymarket_source_control(
    control: PolymarketSourceControl,
    market_runtime: &mut PolymarketDrainRuntime,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
) -> Result<bool> {
    let PolymarketSourceControl::Fence {
        stop_after_fence,
        resume_after_barrier,
        reply,
    } = control;
    let result = fence_polymarket_processor(
        market_runtime,
        stop_after_fence,
        context,
        sink,
        collector_identity,
        run_started,
        dedupe,
        recovery,
    )
    .await;
    match result {
        Ok(()) => {
            let _ = reply.send(Ok(()));
        }
        Err(error) => {
            let message = error.to_string();
            let _ = reply.send(Err(message));
            return Err(error);
        }
    }
    if stop_after_fence {
        return Ok(true);
    }
    if let Some(resume) = resume_after_barrier {
        resume
            .await
            .map_err(|_| invalid_data("Polymarket day-barrier resume dropped"))?;
    }
    Ok(false)
}

enum PolymarketSubscriptionProgress {
    Applied,
    SdkError(SdkStreamError),
    ProcessingError(Box<dyn Error + Send + Sync>),
}

#[allow(clippy::too_many_arguments)]
async fn apply_polymarket_subscription_while_draining(
    market_runtime: &mut PolymarketDrainRuntime,
    target_assets: BTreeSet<U256>,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
) -> Result<()> {
    let progress = {
        let sdk = &mut market_runtime.sdk;
        let events = &mut market_runtime.events;
        let operation = sdk.replace_and_wait(target_assets, Duration::from_secs(20));
        tokio::pin!(operation);
        loop {
            tokio::select! {
                biased;
                result = &mut operation => {
                    break match result {
                        Ok(()) => PolymarketSubscriptionProgress::Applied,
                        Err(error) => PolymarketSubscriptionProgress::SdkError(error),
                    };
                }
                item = events.recv() => {
                    match item {
                        Some(PolymarketPumpItem::Message(message)) => {
                            if let Err(error) = process_polymarket_budgeted_message(
                                message,
                                context,
                                sink,
                                collector_identity,
                                run_started,
                                dedupe,
                                recovery,
                            ).await {
                                break PolymarketSubscriptionProgress::ProcessingError(error);
                            }
                        }
                        Some(PolymarketPumpItem::Terminal(terminal)) => {
                            break PolymarketSubscriptionProgress::ProcessingError(
                                polymarket_drain_terminal_error(terminal, sink),
                            );
                        }
                        Some(PolymarketPumpItem::Fence { id, stop_after_fence }) => {
                            break PolymarketSubscriptionProgress::ProcessingError(
                                invalid_data(format!(
                                    "unexpected Polymarket fence during subscription change:id={id}:stop={stop_after_fence}"
                                )).into(),
                            );
                        }
                        None => {
                            break PolymarketSubscriptionProgress::ProcessingError(
                                polymarket_drain_terminal_error(
                                    PolymarketDrainTerminal::QueueClosed,
                                    sink,
                                ),
                            );
                        }
                    }
                }
            }
        }
    };
    match progress {
        PolymarketSubscriptionProgress::Applied => Ok(()),
        PolymarketSubscriptionProgress::ProcessingError(error) => {
            stop_polymarket_after_processing_error(
                error,
                market_runtime,
                context,
                sink,
                collector_identity,
                run_started,
                dedupe,
                recovery,
            )
            .await
        }
        PolymarketSubscriptionProgress::SdkError(error) => {
            stop_polymarket_after_processing_error(
                error.into(),
                market_runtime,
                context,
                sink,
                collector_identity,
                run_started,
                dedupe,
                recovery,
            )
            .await
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn install_polymarket_context(
    discovery: BtcUpdownDiscovery,
    emit_current_metadata: bool,
    market_runtime: &mut PolymarketDrainRuntime,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
) -> Result<()> {
    dedupe
        .replace_lifecycles(expected_lifecycle_slugs(&discovery))
        .map_err(operator_dedupe_error)?;
    context.replace_discovery(discovery);
    let target_assets = context.desired_assets()?;
    apply_polymarket_subscription_while_draining(
        market_runtime,
        target_assets,
        context,
        sink,
        collector_identity,
        run_started,
        dedupe,
        recovery,
    )
    .await?;
    if emit_current_metadata {
        let current = context
            .current
            .as_ref()
            .ok_or_else(|| invalid_data("installed Polymarket context is missing current"))?;
        let authority = send_polymarket_metadata_event(
            sink,
            run_started,
            current,
            "current",
            collector_identity,
        )
        .await?;
        context.register_source_authority(authority)?;
    }
    if let Some(next) = &context.next {
        let authority =
            send_polymarket_metadata_event(sink, run_started, next, "next", collector_identity)
                .await?;
        context.register_source_authority(authority)?;
    }
    recovery.record_business_recovery();
    sink.source_queue_backpressure
        .set_recovery_active("polymarket_market", false);
    Ok(())
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PolymarketContextInstallOutcome {
    Applied { applied_at_utc_ms: i64 },
    Expired,
}

#[allow(clippy::too_many_arguments)]
async fn install_polymarket_context_if_current(
    discovery: BtcUpdownDiscovery,
    evaluation_ms: i64,
    emit_current_metadata: bool,
    market_runtime: &mut PolymarketDrainRuntime,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
) -> Result<PolymarketContextInstallOutcome> {
    if !gamma_discovery_is_current(&discovery, evaluation_ms) {
        return Ok(PolymarketContextInstallOutcome::Expired);
    }
    install_polymarket_context(
        discovery,
        emit_current_metadata,
        market_runtime,
        context,
        sink,
        collector_identity,
        run_started,
        dedupe,
        recovery,
    )
    .await?;
    Ok(PolymarketContextInstallOutcome::Applied {
        applied_at_utc_ms: evaluation_ms,
    })
}

fn validate_polymarket_context_switch(
    current: &BtcUpdownDiscovery,
    replacement: &BtcUpdownDiscovery,
) -> Result<()> {
    if current.current.slug == replacement.current.slug {
        return Ok(());
    }
    let Some(prefetched) = current
        .next
        .as_ref()
        .filter(|market| market.slug == replacement.current.slug)
    else {
        return Ok(());
    };
    if prefetched.id != replacement.current.id
        || prefetched.condition_id != replacement.current.condition_id
        || prefetched.up_asset_id != replacement.current.up_asset_id
        || prefetched.down_asset_id != replacement.current.down_asset_id
    {
        return Err(invalid_data(format!(
            "Polymarket prefetched market identity changed before promotion:slug={}",
            prefetched.slug
        ))
        .into());
    }
    Ok(())
}

fn validate_polymarket_discovery_identity_continuity(
    previous: &BtcUpdownDiscovery,
    current: &BtcUpdownDiscovery,
) -> Result<()> {
    for previous_market in std::iter::once(&previous.current).chain(previous.next.as_ref()) {
        let Some(current_market) = std::iter::once(&current.current)
            .chain(current.next.as_ref())
            .find(|market| market.slug == previous_market.slug)
        else {
            continue;
        };
        if previous_market.id != current_market.id
            || previous_market.condition_id != current_market.condition_id
            || previous_market.up_asset_id != current_market.up_asset_id
            || previous_market.down_asset_id != current_market.down_asset_id
        {
            return Err(invalid_data(format!(
                "Polymarket market identity changed across transport recovery:slug={}",
                previous_market.slug
            ))
            .into());
        }
    }
    Ok(())
}

fn preserve_polymarket_fixed_identity_authority(
    previous: &BtcUpdownDiscovery,
    replacement: &mut BtcUpdownDiscovery,
) -> Result<()> {
    validate_polymarket_discovery_identity_continuity(previous, replacement)?;
    for replacement_market in
        std::iter::once(&mut replacement.current).chain(replacement.next.as_mut())
    {
        let Some(previous_market) = std::iter::once(&previous.current)
            .chain(previous.next.as_ref())
            .find(|market| market.slug == replacement_market.slug)
        else {
            continue;
        };
        replacement_market.fixed_identity_verified_at_utc_ms =
            previous_market.fixed_identity_verified_at_utc_ms;
    }
    Ok(())
}

fn stamp_polymarket_discovery_validation(
    market: &mut DiscoveredBtcUpdownMarket,
    validation_completed_at_utc_ms: i64,
) -> Result<()> {
    if market
        .metadata_received_utc_ms
        .is_some_and(|received| received > validation_completed_at_utc_ms)
    {
        return Err(invalid_data(format!(
            "Polymarket discovery validation clock preceded source receive:slug={}:received={}:validation_completed={validation_completed_at_utc_ms}",
            market.slug,
            market.metadata_received_utc_ms.unwrap_or_default()
        ))
        .into());
    }
    market.fixed_identity_verified_at_utc_ms = validation_completed_at_utc_ms;
    market.metadata_validation_completed_at_utc_ms = validation_completed_at_utc_ms;
    Ok(())
}

#[allow(clippy::too_many_arguments)]
async fn switch_polymarket_context<N>(
    mut discovery: BtcUpdownDiscovery,
    timeline_now: &N,
    emit_current_metadata: bool,
    market_runtime: &mut PolymarketDrainRuntime,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
) -> Result<PolymarketContextInstallOutcome>
where
    N: Fn() -> PolymarketTimelineNow + Send + Sync,
{
    if let Some(current) = context.discovery_snapshot()
        && let Err(error) = validate_polymarket_context_switch(&current, &discovery)
            .and_then(|()| preserve_polymarket_fixed_identity_authority(&current, &mut discovery))
    {
        record_gap(
            &sink.gaps,
            format!("polymarket_rollover_identity_integrity:{error}"),
        );
        return Err(error);
    }
    fence_polymarket_processor(
        market_runtime,
        false,
        context,
        sink,
        collector_identity,
        run_started,
        dedupe,
        recovery,
    )
    .await?;
    install_polymarket_context_if_current(
        discovery,
        timeline_now().utc_ms,
        emit_current_metadata,
        market_runtime,
        context,
        sink,
        collector_identity,
        run_started,
        dedupe,
        recovery,
    )
    .await
}

fn schedule_polymarket_discovery_retry<N>(
    recovery: &mut SourceRecoverySupervisor,
    sink: &SourceEventSink,
    timeline_now: &N,
) -> TokioInstant
where
    N: Fn() -> PolymarketTimelineNow + Send + Sync,
{
    let wait = recovery.next_wait();
    sink.source_queue_backpressure
        .record_reconnect("polymarket_market", timeline_now().utc_ms);
    sink.source_queue_backpressure
        .set_recovery_active("polymarket_market", true);
    timeline_now().monotonic + wait.delay
}

fn expected_active_polymarket_lifecycles(
    context: &PolymarketProcessingContext,
) -> BTreeSet<String> {
    let Some(current) = &context.current else {
        return BTreeSet::new();
    };
    let next_slug = context.next.as_ref().map_or_else(
        || discovery_windows(current.start_ts_s * 1000).next.slug,
        |next| next.slug.clone(),
    );
    BTreeSet::from([current.slug.clone(), next_slug])
}

async fn advance_polymarket_boundaries(
    now_utc_ms: i64,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
) -> Result<bool> {
    let Some(current) = context.current.as_ref() else {
        return Ok(false);
    };
    if now_utc_ms < current.end_ts_s.saturating_mul(1_000) {
        return Ok(false);
    }

    let pending_identity = PendingPolymarketIdentity::from_discovered(current)?;
    if context.pending.contains_key(&pending_identity.slug) {
        return Err(invalid_data(format!(
            "duplicate Polymarket pending owner:slug={}",
            pending_identity.slug
        ))
        .into());
    }
    let pending_row = polymarket_market_state_transition_v3_row(
        &pending_identity,
        MarketRuntimeRoleTransition::CurrentToResolutionPending,
        now_utc_ms,
        collector_identity,
    )?;
    let promoted = context
        .next
        .as_ref()
        .filter(|next| {
            let start = next.start_ts_s.saturating_mul(1_000);
            let end = next.end_ts_s.saturating_mul(1_000);
            start <= now_utc_ms && now_utc_ms < end
        })
        .cloned();
    let promotion_row = promoted
        .as_ref()
        .map(|market| {
            let identity = PendingPolymarketIdentity::from_discovered(market)?;
            polymarket_market_state_transition_v3_row(
                &identity,
                MarketRuntimeRoleTransition::NextToCurrent,
                now_utc_ms,
                collector_identity,
            )
        })
        .transpose()?;
    context.validate_local_transition_authority(&pending_row)?;
    if let Some(row) = &promotion_row {
        context.validate_local_transition_authority(row)?;
    }

    let expired_current = context
        .current
        .take()
        .ok_or_else(|| invalid_data("Polymarket current disappeared at boundary"))?;
    debug_assert_eq!(expired_current.slug, pending_identity.slug);
    let early_claim = context.early_ws_claims.remove(&pending_identity.slug);
    context.pending.insert(
        pending_identity.slug.clone(),
        PendingPolymarketResolution::new(pending_identity, early_claim),
    );
    context.next.take();
    context.current = promoted;
    context.rebuild_asset_to_slug();
    context.ensure_pending_bounds()?;
    dedupe
        .replace_lifecycles(expected_active_polymarket_lifecycles(context))
        .map_err(operator_dedupe_error)?;

    send_polymarket_metadata_v3_row(sink, run_started, pending_row).await?;
    if let Some(row) = promotion_row {
        send_polymarket_metadata_v3_row(sink, run_started, row).await?;
    }
    Ok(true)
}

async fn record_gamma_resolution_completion<N>(
    completion: GammaResolutionPollCompletion,
    validation_now_utc_ms: &N,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
) -> Result<()>
where
    N: Fn() -> i64 + Send + Sync,
{
    if completion.fetch_start_utc_ms < completion.scheduled_at_utc_ms
        || completion.completed_at_utc_ms < completion.fetch_start_utc_ms
    {
        return Err(invalid_data(format!(
            "Gamma resolution request clock regressed without decoded evidence:slug={}:ordinal={}:scheduled={}:fetch_start={}:completed={}",
            completion.slug,
            completion.ordinal,
            completion.scheduled_at_utc_ms,
            completion.fetch_start_utc_ms,
            completion.completed_at_utc_ms
        ))
        .into());
    }
    let pending = context.pending.get(&completion.slug).ok_or_else(|| {
        invalid_data(format!(
            "Gamma completion has no pending owner:slug={}:ordinal={}",
            completion.slug, completion.ordinal
        ))
    })?;
    let ws_claimed = matches!(
        pending.claim,
        Some(PolymarketTerminalClaim::MarketResolvedWs(_))
    );
    let row = polymarket_resolution_attempt_v3_row(
        pending,
        &completion,
        validation_now_utc_ms,
        ws_claimed,
        collector_identity,
    )?;
    let result = row
        .resolution_poll_result
        .ok_or_else(|| invalid_data("Gamma completion row is missing result"))?;

    let mut emit_now = None;
    let mut fail_after_emit = false;
    {
        let pending = context
            .pending
            .get_mut(&completion.slug)
            .ok_or_else(|| invalid_data("Gamma pending owner disappeared during completion"))?;
        pending.in_flight_ordinal = None;
        pending.poll_abort_handle = None;
        pending.attempts_recorded = pending.attempts_recorded.saturating_add(1);
        pending.next_attempt_ordinal = completion.ordinal.saturating_add(1);
        match result {
            ResolutionPollResult::Terminal => {
                if pending.claim.is_none() {
                    pending.claim = Some(PolymarketTerminalClaim::GammaBySlug(Box::new(row)));
                } else {
                    return Err(invalid_data(format!(
                        "Gamma terminal attempted a second claim:slug={}",
                        completion.slug
                    ))
                    .into());
                }
            }
            ResolutionPollResult::ValidNonterminal => {
                pending.valid_response_count = pending.valid_response_count.saturating_add(1);
                pending.last_valid_metadata_received_at_utc_ms = Some(
                    pending
                        .last_valid_metadata_received_at_utc_ms
                        .map_or(completion.completed_at_utc_ms, |previous| {
                            previous.max(completion.completed_at_utc_ms)
                        }),
                );
                emit_now = Some(row);
            }
            ResolutionPollResult::TransportUnavailable => {
                pending.transport_unavailable_count =
                    pending.transport_unavailable_count.saturating_add(1);
                if ws_claimed {
                    pending.buffered_attempt_rows.push(row);
                } else {
                    emit_now = Some(row);
                }
            }
            ResolutionPollResult::PostTerminalClaimObservation => {
                pending.buffered_attempt_rows.push(row);
            }
            ResolutionPollResult::IntegrityError => {
                pending.fatal_integrity_error = true;
                if ws_claimed {
                    pending.buffered_attempt_rows.push(row);
                } else {
                    emit_now = Some(row);
                    fail_after_emit = true;
                }
            }
            ResolutionPollResult::MissedDueToDowntime => {
                return Err(
                    invalid_data("live Gamma completion cannot be missed_due_to_downtime").into(),
                );
            }
        }
        if completion.ordinal == POLYMARKET_RESOLUTION_ATTEMPT_COUNT
            && pending.claim.is_none()
            && !pending.fatal_integrity_error
        {
            pending.exhaustion_requested = true;
        }
    }
    context.ensure_pending_bounds()?;
    if let Some(row) = emit_now {
        send_polymarket_metadata_v3_row(sink, run_started, row).await?;
    }
    if fail_after_emit {
        return Err(invalid_data(format!(
            "Gamma resolution integrity failure:slug={}:ordinal={}",
            completion.slug, completion.ordinal
        ))
        .into());
    }
    Ok(())
}

fn record_cancelled_gamma_resolution_poll(
    task_id: tokio::task::Id,
    context: &mut PolymarketProcessingContext,
) -> Result<()> {
    let pending = context
        .pending
        .values_mut()
        .find(|pending| {
            pending
                .poll_abort_handle
                .as_ref()
                .is_some_and(|handle| handle.id() == task_id)
        })
        .ok_or_else(|| {
            invalid_data(format!(
                "cancelled Gamma resolution poll has no pending owner:task_id={task_id}"
            ))
        })?;
    if !matches!(
        pending.claim,
        Some(PolymarketTerminalClaim::MarketResolvedWs(_))
    ) {
        return Err(invalid_data(format!(
            "Gamma resolution poll was cancelled without a WS terminal claim:task_id={task_id}"
        ))
        .into());
    }
    pending.in_flight_ordinal = None;
    pending.poll_abort_handle = None;
    Ok(())
}

#[allow(clippy::too_many_arguments)]
async fn finalize_polymarket_pending_after_fence<N>(
    timeline_now: &N,
    market_runtime: &mut PolymarketDrainRuntime,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
) -> Result<()>
where
    N: Fn() -> PolymarketTimelineNow + Send + Sync,
{
    let ready_slugs = context
        .pending
        .iter()
        .filter(|(_, pending)| pending.requires_fence())
        .map(|(slug, _)| slug.clone())
        .collect::<Vec<_>>();
    if ready_slugs.is_empty() {
        return Ok(());
    }

    let resume = pause_polymarket_processor(
        market_runtime,
        context,
        sink,
        collector_identity,
        run_started,
        dedupe,
        recovery,
    )
    .await?;

    let mut fatal_integrity = None;
    let mut latest_exhausted_applied_at_utc_ms = None;
    for slug in ready_slugs {
        let applied_at_utc_ms = timeline_now().utc_ms;
        context.actor_now_utc_ms = applied_at_utc_ms;
        let Some(mut pending) = context.pending.remove(&slug) else {
            continue;
        };
        if let Some(claim) = pending.claim.take() {
            let terminal_row = match claim {
                PolymarketTerminalClaim::MarketResolvedWs(evidence) => {
                    if applied_at_utc_ms < evidence.validation_completed_at_utc_ms {
                        return Err(invalid_data(format!(
                            "Polymarket WS terminal applied clock regressed:slug={slug}:validation_completed={}:applied={applied_at_utc_ms}",
                            evidence.validation_completed_at_utc_ms
                        ))
                        .into());
                    }
                    polymarket_resolution_terminal_ws_v3_row(
                        &pending,
                        &evidence,
                        applied_at_utc_ms,
                        collector_identity,
                    )?
                }
                PolymarketTerminalClaim::GammaBySlug(mut row) => {
                    let validation_completed = row
                        .row_evidence_validation_completed_at_utc
                        .unwrap_or(applied_at_utc_ms);
                    if applied_at_utc_ms < validation_completed {
                        return Err(invalid_data(format!(
                            "Polymarket Gamma terminal applied clock regressed:slug={slug}:validation_completed={validation_completed}:applied={applied_at_utc_ms}"
                        ))
                        .into());
                    }
                    complete_polymarket_terminal_transition(&mut row, applied_at_utc_ms);
                    *row
                }
            };
            let mut terminal_bundle =
                Vec::with_capacity(pending.buffered_attempt_rows.len().saturating_add(1));
            terminal_bundle.push(terminal_row);
            terminal_bundle.append(&mut pending.buffered_attempt_rows);
            send_polymarket_metadata_v3_rows_atomically(sink, run_started, terminal_bundle).await?;
            if pending.fatal_integrity_error {
                fatal_integrity = Some(format!(
                    "Gamma resolution integrity failure after WS terminal:slug={slug}"
                ));
            }
        } else if pending.exhaustion_requested {
            if applied_at_utc_ms < pending.budget_horizon_utc_ms() {
                return Err(invalid_data(format!(
                    "Polymarket exhausted role-exit preceded budget horizon:slug={slug}:horizon={}:applied={applied_at_utc_ms}",
                    pending.budget_horizon_utc_ms()
                ))
                .into());
            }
            let summary = polymarket_resolution_followup_summary_v3_row(
                &pending,
                applied_at_utc_ms,
                collector_identity,
            )?;
            send_polymarket_metadata_v3_row(sink, run_started, summary).await?;
            latest_exhausted_applied_at_utc_ms = Some(
                latest_exhausted_applied_at_utc_ms.map_or(applied_at_utc_ms, |latest: i64| {
                    latest.max(applied_at_utc_ms)
                }),
            );
        } else {
            context.pending.insert(slug, pending);
        }
    }
    context.rebuild_asset_to_slug();
    context.ensure_pending_bounds()?;
    if let Some(latest_exhausted_applied_at_utc_ms) = latest_exhausted_applied_at_utc_ms {
        let resumed_at_utc_ms = timeout(BUFFER_ACQUIRE_TIMEOUT, async {
            loop {
                let resumed_at_utc_ms = timeline_now().utc_ms;
                if resumed_at_utc_ms > latest_exhausted_applied_at_utc_ms {
                    return resumed_at_utc_ms;
                }
                sleep(Duration::from_millis(1)).await;
            }
        })
        .await
        .map_err(|_| {
            invalid_data(format!(
                "Polymarket exhausted role-exit clock barrier timeout:applied={latest_exhausted_applied_at_utc_ms}"
            ))
        })?;
        context.actor_now_utc_ms = resumed_at_utc_ms;
    }
    resume
        .send(())
        .map_err(|_| invalid_data("Polymarket paused fence resume receiver dropped"))?;
    apply_polymarket_subscription_while_draining(
        market_runtime,
        context.desired_assets()?,
        context,
        sink,
        collector_identity,
        run_started,
        dedupe,
        recovery,
    )
    .await?;
    if let Some(reason) = fatal_integrity {
        return Err(invalid_data(reason).into());
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
async fn collect_polymarket_single_receiver<N>(
    discovery: BtcUpdownDiscovery,
    context: &mut PolymarketProcessingContext,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    deadline_ms: Option<i64>,
    run_started: Instant,
    market_runtime: &mut PolymarketDrainRuntime,
    gamma: &GammaClient,
    dedupe: &mut LifecycleFingerprintSets,
    recovery: &mut SourceRecoverySupervisor,
    control_rx: &mut mpsc::Receiver<PolymarketSourceControl>,
    discovery_wait: Duration,
    discovery_retry_delay: Duration,
    timeline_now: N,
) -> Result<()>
where
    N: Fn() -> PolymarketTimelineNow + Send + Sync + 'static,
{
    let timeline_now = Arc::new(timeline_now);
    let validation_timeline = Arc::clone(&timeline_now);
    context.actor_utc_now = Some(Arc::new(move || validation_timeline().utc_ms));
    let initial_now = timeline_now();
    context.actor_now_utc_ms = initial_now.utc_ms;
    let installed = install_polymarket_context_if_current(
        discovery,
        initial_now.utc_ms,
        true,
        market_runtime,
        context,
        sink,
        collector_identity,
        run_started,
        dedupe,
        recovery,
    )
    .await?;
    if installed == PolymarketContextInstallOutcome::Expired {
        return Err(PolymarketDiscoveryError::Unavailable(
            "Gamma discovery expired before initial context installation".to_owned(),
        )
        .into());
    }
    let installed_now = timeline_now();
    let mut next_discovery_at = if context.next.is_none() {
        installed_now.monotonic
    } else {
        installed_now.monotonic + Duration::from_secs(MARKET_NEXT_DISCOVERY_INTERVAL_SECS)
    };
    let mut next_discovery_tasks = JoinSet::new();
    let mut rollover_discovery_tasks = JoinSet::new();
    let mut resolution_poll_tasks = JoinSet::<GammaResolutionPollCompletion>::new();
    let mut rollover_retry_at = None::<TokioInstant>;
    loop {
        let loop_now = timeline_now();
        context.actor_now_utc_ms = loop_now.utc_ms;

        let boundary_now = if context
            .current
            .as_ref()
            .is_some_and(|current| loop_now.utc_ms >= current.end_ts_s.saturating_mul(1_000))
        {
            fence_polymarket_processor(
                market_runtime,
                false,
                context,
                sink,
                collector_identity,
                run_started,
                dedupe,
                recovery,
            )
            .await?;
            let boundary_now = timeline_now();
            context.actor_now_utc_ms = boundary_now.utc_ms;
            boundary_now
        } else {
            loop_now
        };
        let boundary_advanced = advance_polymarket_boundaries(
            boundary_now.utc_ms,
            context,
            sink,
            collector_identity,
            run_started,
            dedupe,
        )
        .await?;
        if boundary_advanced {
            next_discovery_tasks.abort_all();
            next_discovery_at = boundary_now.monotonic;
            if context.current.is_none() {
                rollover_retry_at = Some(boundary_now.monotonic);
            }
        }

        while let Some(result) = resolution_poll_tasks.try_join_next() {
            match result {
                Ok(completion) => {
                    record_gamma_resolution_completion(
                        completion,
                        &|| timeline_now().utc_ms,
                        context,
                        sink,
                        collector_identity,
                        run_started,
                    )
                    .await?;
                }
                Err(error) if error.is_cancelled() => {
                    record_cancelled_gamma_resolution_poll(error.id(), context)?;
                }
                Err(error) => {
                    return Err(
                        invalid_data(format!("Gamma resolution poll task failed:{error}")).into(),
                    );
                }
            }
        }

        for pending in context.pending.values_mut() {
            if matches!(
                pending.claim,
                Some(PolymarketTerminalClaim::MarketResolvedWs(_))
            ) && let Some(abort) = pending.poll_abort_handle.as_ref()
            {
                abort.abort();
            }
        }
        if context.pending_requires_fence() {
            finalize_polymarket_pending_after_fence(
                &*timeline_now,
                market_runtime,
                context,
                sink,
                collector_identity,
                run_started,
                dedupe,
                recovery,
            )
            .await?;
            continue;
        }

        if deadline_ms.is_some_and(|deadline_ms| timeline_now().utc_ms >= deadline_ms) {
            fence_polymarket_processor(
                market_runtime,
                true,
                context,
                sink,
                collector_identity,
                run_started,
                dedupe,
                recovery,
            )
            .await?;
            return Ok(());
        }

        match control_rx.try_recv() {
            Ok(control) => {
                if handle_polymarket_source_control(
                    control,
                    market_runtime,
                    context,
                    sink,
                    collector_identity,
                    run_started,
                    dedupe,
                    recovery,
                )
                .await?
                {
                    return Ok(());
                }
            }
            Err(mpsc::error::TryRecvError::Empty) => {}
            Err(mpsc::error::TryRecvError::Disconnected) => {
                fence_polymarket_processor(
                    market_runtime,
                    true,
                    context,
                    sink,
                    collector_identity,
                    run_started,
                    dedupe,
                    recovery,
                )
                .await?;
                return Ok(());
            }
        }

        let now = timeline_now();
        let due_polls = context
            .pending
            .iter()
            .filter(|(_, pending)| {
                let ordinal = pending.next_attempt_ordinal;
                pending.claim.is_none()
                    && !pending.fatal_integrity_error
                    && pending.in_flight_ordinal.is_none()
                    && ordinal <= POLYMARKET_RESOLUTION_ATTEMPT_COUNT
                    && now.utc_ms >= pending.slot_utc_ms(ordinal)
            })
            .map(|(slug, pending)| {
                let ordinal = pending.next_attempt_ordinal;
                (slug.clone(), ordinal, pending.slot_utc_ms(ordinal))
            })
            .collect::<Vec<_>>();
        for (slug, ordinal, scheduled_at_utc_ms) in due_polls {
            let gamma = gamma.clone();
            let task_timeline = Arc::clone(&timeline_now);
            let task_slug = slug.clone();
            let handle = resolution_poll_tasks.spawn(async move {
                let fetch_start_utc_ms = task_timeline().utc_ms;
                let request = MarketBySlugRequest::builder()
                    .slug(task_slug.clone())
                    .build();
                let result = match timeout(
                    Duration::from_secs(GAMMA_REQUEST_TIMEOUT_SECS),
                    gamma.market_by_slug(&request),
                )
                .await
                {
                    Ok(Ok(market)) => Ok(market),
                    Ok(Err(error)) => match classify_gamma_market_by_slug_transport_error(&error) {
                        Some(transport) => Err(GammaResolutionPollFailure::Transport {
                            class: transport.class,
                            http_status: transport.http_status,
                        }),
                        None => Err(GammaResolutionPollFailure::SdkDecodeOrSchema),
                    },
                    Err(_) => Err(GammaResolutionPollFailure::Transport {
                        class: ResolutionTransportErrorClass::Timeout,
                        http_status: None,
                    }),
                };
                GammaResolutionPollCompletion {
                    slug: task_slug,
                    ordinal,
                    scheduled_at_utc_ms,
                    fetch_start_utc_ms,
                    completed_at_utc_ms: task_timeline().utc_ms,
                    result,
                }
            });
            let pending = context.pending.get_mut(&slug).ok_or_else(|| {
                invalid_data("Polymarket pending owner disappeared before poll spawn")
            })?;
            pending.in_flight_ordinal = Some(ordinal);
            pending.poll_abort_handle = Some(handle);
        }

        if let Some(current) = context.current.clone()
            && context.next.is_none()
            && next_discovery_tasks.is_empty()
            && now.monotonic >= next_discovery_at
            && now.utc_ms < current.end_ts_s * 1000
        {
            next_discovery_at =
                now.monotonic + Duration::from_secs(MARKET_NEXT_DISCOVERY_INTERVAL_SECS);
            let next_slug = discovery_windows(current.start_ts_s * 1000).next.slug;
            let gamma = gamma.clone();
            let discovery_timeline = Arc::clone(&timeline_now);
            next_discovery_tasks.spawn(async move {
                fetch_exact_slug_candidates_with_clock(&gamma, &next_slug, || {
                    discovery_timeline().utc_ms
                })
                .await
            });
        }

        if let Some(result) = next_discovery_tasks.try_join_next() {
            match result {
                Ok(Ok(batch)) if gamma_batch_is_current_next(&batch, timeline_now().utc_ms) => {
                    let Some(mut updated) = context.discovery_snapshot() else {
                        continue;
                    };
                    let selection_started_at_utc_ms = timeline_now().utc_ms;
                    match updated.attach_next(&batch.candidates, selection_started_at_utc_ms) {
                        Ok(true) => {
                            let validation_completed_at_utc_ms = timeline_now().utc_ms;
                            let next = updated.next.as_mut().ok_or_else(|| {
                                invalid_data(
                                    "Polymarket next discovery attached without a selected market",
                                )
                            })?;
                            stamp_polymarket_discovery_validation(
                                next,
                                validation_completed_at_utc_ms,
                            )?;
                            let installed = switch_polymarket_context(
                                updated,
                                &*timeline_now,
                                false,
                                market_runtime,
                                context,
                                sink,
                                collector_identity,
                                run_started,
                                dedupe,
                                recovery,
                            )
                            .await?;
                            if installed == PolymarketContextInstallOutcome::Expired {
                                next_discovery_at = timeline_now().monotonic;
                            }
                        }
                        Ok(false) => {}
                        Err(error) => match classify_discovery_selection_error(error) {
                            PolymarketDiscoveryError::Unavailable(_) => {}
                            PolymarketDiscoveryError::Integrity(error) => {
                                record_gap(
                                    &sink.gaps,
                                    format!("polymarket_next_discovery_integrity:{error}"),
                                );
                                return Err(invalid_data(error).into());
                            }
                        },
                    }
                }
                Ok(Ok(_)) | Ok(Err(PolymarketDiscoveryError::Unavailable(_))) => {}
                Ok(Err(PolymarketDiscoveryError::Integrity(error))) => {
                    record_gap(
                        &sink.gaps,
                        format!("polymarket_next_discovery_integrity:{error}"),
                    );
                    return Err(invalid_data(error).into());
                }
                Err(error) if error.is_cancelled() => {}
                Err(error) => {
                    let reason = format!("polymarket_next_discovery_task_failed:{error}");
                    record_gap(&sink.gaps, reason.clone());
                    return Err(invalid_data(reason).into());
                }
            }
        }

        if context.current.is_none()
            && rollover_discovery_tasks.is_empty()
            && rollover_retry_at.is_some_and(|retry_at| timeline_now().monotonic >= retry_at)
        {
            rollover_retry_at = None;
            let gamma = gamma.clone();
            let discovery_timeline = Arc::clone(&timeline_now);
            rollover_discovery_tasks.spawn(async move {
                discover_markets_with_wait_clock(
                    &gamma,
                    discovery_wait,
                    discovery_retry_delay,
                    || discovery_timeline().utc_ms,
                )
                .await
            });
        }
        if let Some(result) = rollover_discovery_tasks.try_join_next() {
            match result {
                Ok(Ok(discovery))
                    if gamma_discovery_is_current(&discovery, timeline_now().utc_ms) =>
                {
                    let late_current = discovery.current.clone();
                    let installed = switch_polymarket_context(
                        discovery,
                        &*timeline_now,
                        false,
                        market_runtime,
                        context,
                        sink,
                        collector_identity,
                        run_started,
                        dedupe,
                        recovery,
                    )
                    .await?;
                    let applied_at_utc_ms = match installed {
                        PolymarketContextInstallOutcome::Applied { applied_at_utc_ms } => {
                            applied_at_utc_ms
                        }
                        PolymarketContextInstallOutcome::Expired => {
                            rollover_retry_at = Some(timeline_now().monotonic);
                            continue;
                        }
                    };
                    let installed_now = timeline_now();
                    let activation_row = polymarket_candidate_to_active_v3_row(
                        &late_current,
                        applied_at_utc_ms,
                        collector_identity,
                    )?;
                    let authority = send_polymarket_metadata_v3_source_authority_row(
                        sink,
                        run_started,
                        activation_row,
                    )
                    .await?;
                    context.register_source_authority(authority)?;
                    next_discovery_at = if context.next.is_none() {
                        installed_now.monotonic
                    } else {
                        installed_now.monotonic
                            + Duration::from_secs(MARKET_NEXT_DISCOVERY_INTERVAL_SECS)
                    };
                    rollover_retry_at = None;
                }
                Ok(Ok(_)) => {
                    rollover_retry_at = Some(timeline_now().monotonic);
                }
                Ok(Err(PolymarketDiscoveryError::Unavailable(_))) => {
                    rollover_retry_at = Some(schedule_polymarket_discovery_retry(
                        recovery,
                        sink,
                        &*timeline_now,
                    ));
                }
                Ok(Err(PolymarketDiscoveryError::Integrity(error))) => {
                    record_gap(
                        &sink.gaps,
                        format!("polymarket_rollover_discovery_integrity:{error}"),
                    );
                    return Err(invalid_data(error).into());
                }
                Err(error) => {
                    let reason = format!("polymarket_rollover_discovery_task_failed:{error}");
                    record_gap(&sink.gaps, reason.clone());
                    return Err(invalid_data(reason).into());
                }
            }
        }

        match market_runtime.recv(Duration::from_millis(250)).await {
            Ok(Some(PolymarketDrainEvent::Message(message))) => {
                context.actor_now_utc_ms = timeline_now().utc_ms;
                if let Err(error) = process_polymarket_budgeted_message(
                    message,
                    context,
                    sink,
                    collector_identity,
                    run_started,
                    dedupe,
                    recovery,
                )
                .await
                {
                    return stop_polymarket_after_processing_error(
                        error,
                        market_runtime,
                        context,
                        sink,
                        collector_identity,
                        run_started,
                        dedupe,
                        recovery,
                    )
                    .await;
                }
            }
            Ok(None) => {}
            Ok(Some(PolymarketDrainEvent::Fence {
                id,
                stop_after_fence,
            })) => {
                return Err(invalid_data(format!(
                    "unexpected unclaimed Polymarket fence:id={id}:stop={stop_after_fence}"
                ))
                .into());
            }
            Err(terminal) => return Err(polymarket_drain_terminal_error(terminal, sink)),
        }
    }
}

#[derive(Default)]
struct PolymarketDispatchOutcome {
    matched_assets: BTreeSet<String>,
}

fn polymarket_target_fanout_counts(
    message: &WsMessage,
    asset_to_slug: &BTreeMap<String, String>,
) -> (usize, usize) {
    let target = |asset: &U256| asset_to_slug.contains_key(&asset.to_string());
    match message {
        WsMessage::BestBidAsk(event) => (usize::from(target(&event.asset_id)), 0),
        WsMessage::Book(event) => (usize::from(target(&event.asset_id)), 0),
        WsMessage::PriceChange(event) => (
            event
                .price_changes
                .iter()
                .filter(|change| target(&change.asset_id))
                .count(),
            0,
        ),
        WsMessage::LastTradePrice(event) => (usize::from(target(&event.asset_id)), 0),
        WsMessage::TickSizeChange(event) => (usize::from(target(&event.asset_id)), 0),
        WsMessage::NewMarket(event) => {
            let matches = event.asset_ids.iter().any(target);
            (usize::from(matches), 0)
        }
        WsMessage::MarketResolved(event) => {
            let matches = event.asset_ids.iter().any(target);
            (usize::from(matches), usize::from(matches))
        }
        _ => (0, 0),
    }
}

fn record_polymarket_fanout_drop(
    sink: &SourceEventSink,
    recv_time_utc_ms: i64,
    market_rows: usize,
    metadata_rows: usize,
) {
    let total = market_rows.saturating_add(metadata_rows) as u64;
    sink.source_queue_backpressure.record_drop(total);
    if market_rows > 0 {
        sink.source_queue_backpressure.record_operational_drop(
            "polymarket_market",
            recv_time_utc_ms,
            market_rows as u64,
        );
    }
    if metadata_rows > 0 {
        sink.source_queue_backpressure.record_operational_drop(
            "polymarket_market_metadata",
            recv_time_utc_ms,
            metadata_rows as u64,
        );
    }
}

async fn send_polymarket_events_atomically<F>(
    sink: &SourceEventSink,
    recv_time_utc_ms: i64,
    mut events: Vec<InflightRawEvent>,
    commit: F,
) -> Result<()>
where
    F: FnOnce() -> Result<()>,
{
    if events.is_empty() {
        if let Err(error) = commit() {
            record_gap_at(
                &sink.gaps,
                recv_time_utc_ms,
                format!("polymarket_atomic_fanout_commit_failed:{error}"),
            );
            return Err(error);
        }
        return Ok(());
    }
    let market_rows = events
        .iter()
        .filter(|event| event.event.source_kind == "polymarket_market")
        .count();
    let metadata_rows = events.len().saturating_sub(market_rows);
    let batch_utc_day = utc_day_string_from_ms(recv_time_utc_ms)
        .ok_or_else(|| invalid_data("Polymarket atomic batch UTC day is unavailable"))?;
    if events.iter().any(|event| {
        utc_day_string_from_ms(event.event.recv_time_utc_ms).as_deref()
            != Some(batch_utc_day.as_str())
    }) {
        let reason = "Polymarket atomic batch spans UTC days".to_owned();
        record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
        record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
        return Err(invalid_data(reason).into());
    }
    let gate = sink
        .source_queue_backpressure
        .raw_day_gate()
        .ok_or_else(|| {
            invalid_data("raw-day gate missing from production Polymarket enqueue path")
        })?;
    let Some(raw_enqueue) = gate
        .begin_unadmitted_event_enqueue("polymarket", recv_time_utc_ms)
        .await?
    else {
        return Ok(());
    };
    let raw_day_permit = match &raw_enqueue {
        RawDayEnqueueDecision::Permit(enqueue) => Some(enqueue.permit.clone()),
        RawDayEnqueueDecision::Defer(_) => None,
    };
    for event in &mut events {
        event.raw_day_permit = raw_day_permit.clone();
    }
    let count = events.len();
    if count > sink.tx.max_capacity() {
        record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
        let reason = format!(
            "operator_intervention_required:Polymarket fan-out exceeds ingress capacity:rows={count}:capacity={}",
            sink.tx.max_capacity()
        );
        record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
        return Err(invalid_data(reason).into());
    }
    if let RawDayEnqueueDecision::Defer(epoch) = &raw_enqueue {
        if let Err(error) = commit() {
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
            record_gap_at(
                &sink.gaps,
                recv_time_utc_ms,
                format!("polymarket_atomic_fanout_commit_failed:{error}"),
            );
            return Err(error);
        }
        sink.source_queue_backpressure
            .defer_raw_batch("polymarket", epoch.clone(), events)?;
        return Ok(());
    }
    let _enqueue_guard = sink.enqueue_lock.lock().await;
    let permits = match sink.tx.try_reserve_many(count) {
        Ok(permits) => permits,
        Err(mpsc::error::TrySendError::Full(())) => {
            sink.source_queue_backpressure.record_wait();
            match timeout(BUFFER_ACQUIRE_TIMEOUT, sink.tx.reserve_many(count)).await {
                Ok(Ok(permits)) => permits,
                Ok(Err(_)) => {
                    record_polymarket_fanout_drop(
                        sink,
                        recv_time_utc_ms,
                        market_rows,
                        metadata_rows,
                    );
                    let reason = "bounded_queue_send_closed:polymarket_atomic_fanout".to_owned();
                    record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
                    return Err(io::Error::new(io::ErrorKind::BrokenPipe, reason).into());
                }
                Err(_) => {
                    sink.source_queue_backpressure.record_timeout();
                    record_polymarket_fanout_drop(
                        sink,
                        recv_time_utc_ms,
                        market_rows,
                        metadata_rows,
                    );
                    let reason =
                        "bounded_queue_backpressure_timeout:polymarket_atomic_fanout".to_owned();
                    record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
                    return Err(io::Error::new(io::ErrorKind::TimedOut, reason).into());
                }
            }
        }
        Err(mpsc::error::TrySendError::Closed(())) => {
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
            let reason = "bounded_queue_send_closed:polymarket_atomic_fanout".to_owned();
            record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
            return Err(io::Error::new(io::ErrorKind::BrokenPipe, reason).into());
        }
    };
    if let Err(error) = stamp_source_admissions_atomically(&mut events, sink) {
        record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
        return Err(error);
    }
    if let Err(error) = commit() {
        record_polymarket_fanout_drop(sink, recv_time_utc_ms, market_rows, metadata_rows);
        record_gap_at(
            &sink.gaps,
            recv_time_utc_ms,
            format!("polymarket_atomic_fanout_commit_failed:{error}"),
        );
        return Err(error);
    }
    for (permit, event) in permits.zip(events) {
        permit.send(event);
    }
    Ok(())
}

fn polymarket_event_message_json(
    message: &polymarket_client_sdk_v2::clob::ws::EventMessage,
) -> Value {
    json!({
        "id": message.id,
        "ticker": message.ticker,
        "slug": message.slug,
        "title": message.title,
        "description": message.description,
    })
}

fn polymarket_source_native_payload_json(message: &WsMessage) -> Result<Option<String>> {
    let value = match message {
        WsMessage::Book(event) => json!({
            "source": "polymarket_market",
            "event_type": "book",
            "market": event.market.to_string(),
            "asset_id": event.asset_id.to_string(),
            "timestamp": event.timestamp,
            "bids": event.bids.iter().map(|level| {
                json!([level.price.to_string(), level.size.to_string()])
            }).collect::<Vec<_>>(),
            "asks": event.asks.iter().map(|level| {
                json!([level.price.to_string(), level.size.to_string()])
            }).collect::<Vec<_>>(),
            "hash": event.hash,
        }),
        WsMessage::PriceChange(event) => json!({
            "source": "polymarket_market",
            "event_type": "price_change",
            "market": event.market.to_string(),
            "timestamp": event.timestamp,
            "price_changes": event.price_changes.iter().map(|change| json!({
                "asset_id": change.asset_id.to_string(),
                "price": change.price.to_string(),
                "size": change.size.as_ref().map(ToString::to_string),
                "side": change.side.to_string(),
                "hash": change.hash,
                "best_bid": change.best_bid.as_ref().map(ToString::to_string),
                "best_ask": change.best_ask.as_ref().map(ToString::to_string),
            })).collect::<Vec<_>>(),
        }),
        WsMessage::TickSizeChange(event) => json!({
            "source": "polymarket_market",
            "event_type": "tick_size_change",
            "market": event.market.to_string(),
            "asset_id": event.asset_id.to_string(),
            "old_tick_size": event.old_tick_size.to_string(),
            "new_tick_size": event.new_tick_size.to_string(),
            "timestamp": event.timestamp,
        }),
        WsMessage::LastTradePrice(event) => json!({
            "source": "polymarket_market",
            "event_type": "last_trade_price",
            "market": event.market.to_string(),
            "asset_id": event.asset_id.to_string(),
            "price": event.price.to_string(),
            "side": event.side.as_ref().map(ToString::to_string),
            "size": event.size.as_ref().map(ToString::to_string),
            "fee_rate_bps": event.fee_rate_bps.as_ref().map(ToString::to_string),
            "timestamp": event.timestamp,
        }),
        WsMessage::BestBidAsk(event) => json!({
            "source": "polymarket_market",
            "event_type": "best_bid_ask",
            "market": event.market.to_string(),
            "asset_id": event.asset_id.to_string(),
            "best_bid": event.best_bid.to_string(),
            "best_ask": event.best_ask.to_string(),
            "spread": event.spread.to_string(),
            "timestamp": event.timestamp,
        }),
        WsMessage::NewMarket(event) => json!({
            "source": "polymarket_market",
            "event_type": "new_market",
            "id": event.id,
            "question": event.question,
            "market": event.market.to_string(),
            "slug": event.slug,
            "description": event.description,
            "asset_ids": event.asset_ids.iter().map(ToString::to_string).collect::<Vec<_>>(),
            "outcomes": event.outcomes,
            "event_message": event.event_message.as_ref().map(polymarket_event_message_json),
            "timestamp": event.timestamp,
        }),
        WsMessage::MarketResolved(event) => json!({
            "source": "polymarket_market",
            "event_type": "market_resolved",
            "id": event.id,
            "question": event.question,
            "market": event.market.to_string(),
            "slug": event.slug,
            "description": event.description,
            "asset_ids": event.asset_ids.iter().map(ToString::to_string).collect::<Vec<_>>(),
            "outcomes": event.outcomes,
            "winning_asset_id": event.winning_asset_id.to_string(),
            "winning_outcome": event.winning_outcome,
            "event_message": event.event_message.as_ref().map(polymarket_event_message_json),
            "timestamp": event.timestamp,
        }),
        WsMessage::Trade(_) | WsMessage::Order(_) => return Ok(None),
        _ => return Ok(None),
    };
    Ok(Some(serde_json::to_string(&value)?))
}

fn expected_lifecycle_slugs(discovery: &BtcUpdownDiscovery) -> BTreeSet<String> {
    let next_slug = discovery.next.as_ref().map_or_else(
        || {
            discovery_windows(discovery.current.start_ts_s * 1000)
                .next
                .slug
        },
        |next| next.slug.clone(),
    );
    BTreeSet::from([discovery.current.slug.clone(), next_slug])
}

fn polymarket_message_lifecycle_slug(
    message: &WsMessage,
    discovery: &BtcUpdownDiscovery,
    asset_to_slug: &BTreeMap<String, String>,
) -> Option<String> {
    let (market, asset_ids) = match message {
        WsMessage::Book(event) => (event.market.to_string(), vec![event.asset_id.to_string()]),
        WsMessage::PriceChange(event) => (
            event.market.to_string(),
            event
                .price_changes
                .iter()
                .map(|change| change.asset_id.to_string())
                .collect(),
        ),
        WsMessage::TickSizeChange(event) => {
            (event.market.to_string(), vec![event.asset_id.to_string()])
        }
        WsMessage::LastTradePrice(event) => {
            (event.market.to_string(), vec![event.asset_id.to_string()])
        }
        WsMessage::BestBidAsk(event) => {
            (event.market.to_string(), vec![event.asset_id.to_string()])
        }
        WsMessage::NewMarket(event) => (
            event.market.to_string(),
            event.asset_ids.iter().map(ToString::to_string).collect(),
        ),
        WsMessage::MarketResolved(event) => (
            event.market.to_string(),
            event.asset_ids.iter().map(ToString::to_string).collect(),
        ),
        _ => return None,
    };
    if market == discovery.current.condition_id {
        return Some(discovery.current.slug.clone());
    }
    if let Some(next) = &discovery.next
        && market == next.condition_id
    {
        return Some(next.slug.clone());
    }
    asset_ids
        .iter()
        .find_map(|asset_id| asset_to_slug.get(asset_id).cloned())
}

fn prepare_polymarket_message(message: &WsMessage) -> Result<Option<String>> {
    let Some(source_native_payload_json) = polymarket_source_native_payload_json(message)? else {
        return Ok(None);
    };
    if source_native_payload_json.len() > MAX_TYPED_ROW_BYTES {
        return Err(io::Error::other(format!(
            "operator_intervention_required:Polymarket source-native payload exceeds {MAX_TYPED_ROW_BYTES} bytes"
        ))
        .into());
    }
    Ok(Some(source_native_payload_json))
}

#[allow(clippy::too_many_arguments)]
fn polymarket_message_passes_dedupe(
    dedupe: &mut LifecycleFingerprintSets,
    discovery: &BtcUpdownDiscovery,
    asset_to_slug: &BTreeMap<String, String>,
    message: &WsMessage,
    source_native_payload_json: &str,
    recv_time_utc_ms: i64,
    operational_stats: Option<&SourceQueueBackpressureStats>,
) -> Result<bool> {
    let Some(lifecycle) = polymarket_message_lifecycle_slug(message, discovery, asset_to_slug)
    else {
        return Ok(true);
    };
    match dedupe
        .check(&lifecycle, source_native_payload_json.as_bytes())
        .map_err(operator_dedupe_error)?
    {
        FingerprintDecision::Unique => Ok(true),
        FingerprintDecision::Duplicate => {
            if let Some(stats) = operational_stats {
                stats.record_structural_dedupe("polymarket_market", recv_time_utc_ms, 1);
            }
            Ok(false)
        }
    }
}

fn commit_polymarket_message_dedupe(
    dedupe: &mut LifecycleFingerprintSets,
    lifecycle: Option<&str>,
    source_native_payload_json: &str,
) -> Result<()> {
    let Some(lifecycle) = lifecycle else {
        return Ok(());
    };
    match dedupe
        .observe(lifecycle, source_native_payload_json.as_bytes())
        .map_err(operator_dedupe_error)?
    {
        FingerprintDecision::Unique => Ok(()),
        FingerprintDecision::Duplicate => Err(invalid_data(
            "Polymarket fingerprint changed from unique to duplicate before commit",
        )
        .into()),
    }
}

#[cfg(test)]
fn restore_polymarket_dedupe(
    dataset_root: &Path,
    dedupe: &mut LifecycleFingerprintSets,
) -> Result<()> {
    let cancel = AtomicBool::new(false);
    if !restore_polymarket_dedupe_until_cancelled(dataset_root, dedupe, &cancel)? {
        return Err(invalid_data("Polymarket restore cancelled without a stop request").into());
    }
    Ok(())
}

fn restore_polymarket_dedupe_until_cancelled(
    dataset_root: &Path,
    dedupe: &mut LifecycleFingerprintSets,
    cancel: &AtomicBool,
) -> Result<bool> {
    let mut parquet_paths = Vec::new();
    let now = now_ms();
    let days = BTreeSet::from([
        utc_day_string_from_ms(now.saturating_sub(86_400_000))
            .ok_or_else(|| io::Error::other("previous UTC day is out of range"))?,
        utc_day_string_from_ms(now)
            .ok_or_else(|| io::Error::other("current UTC day is out of range"))?,
    ]);
    for day in days {
        if cancel.load(Ordering::Relaxed) {
            return Ok(false);
        }
        let source_dir = dataset_root
            .join("training")
            .join("typed_raw")
            .join(format!("utc_day={day}"))
            .join("source_kind=polymarket_market");
        let entries = match fs::read_dir(&source_dir) {
            Ok(entries) => entries,
            Err(error) if error.kind() == io::ErrorKind::NotFound => continue,
            Err(error) => return Err(error.into()),
        };
        for entry in entries {
            if cancel.load(Ordering::Relaxed) {
                return Ok(false);
            }
            let entry = entry?;
            if !entry.file_type()?.is_file() {
                continue;
            }
            let file_name = entry.file_name();
            let file_name = file_name.to_string_lossy();
            if file_name.ends_with(".parquet")
                && !file_name.ends_with("-running.parquet")
                && !file_name.ends_with("-digesting.parquet")
            {
                parquet_paths.push(entry.path());
            }
        }
    }
    parquet_paths.sort_by_key(|path| finalized_parquet_order_key(path));

    for path in parquet_paths {
        if cancel.load(Ordering::Relaxed) {
            return Ok(false);
        }
        let builder = ParquetRecordBatchReaderBuilder::try_new(File::open(&path)?)?;
        if builder.schema().index_of("slug").is_err()
            || builder
                .schema()
                .index_of("source_native_payload_json")
                .is_err()
        {
            continue;
        }
        if builder.metadata().file_metadata().num_rows() == 0 {
            continue;
        }
        let projection = ProjectionMask::columns(
            builder.parquet_schema(),
            ["slug", "source_native_payload_json"],
        );
        let mut reader = builder
            .with_projection(projection)
            .with_batch_size(16)
            .build()?;
        for batch in &mut reader {
            if cancel.load(Ordering::Relaxed) {
                return Ok(false);
            }
            let batch = batch?;
            let slug_index = batch.schema().index_of("slug")?;
            let payload_index = batch.schema().index_of("source_native_payload_json")?;
            let slugs = batch
                .column(slug_index)
                .as_any()
                .downcast_ref::<StringArray>()
                .ok_or_else(|| io::Error::other("Polymarket restore slug is not UTF8"))?;
            let payloads = batch
                .column(payload_index)
                .as_any()
                .downcast_ref::<StringArray>()
                .ok_or_else(|| {
                    io::Error::other("Polymarket restore source-native payload is not UTF8")
                })?;
            for row in 0..batch.num_rows() {
                if slugs.is_null(row) {
                    continue;
                }
                let slug = slugs.value(row);
                if !dedupe.contains_lifecycle(slug) {
                    continue;
                }
                if payloads.is_null(row) {
                    return Err(io::Error::other(format!(
                        "Polymarket restore payload missing in {}",
                        path.display()
                    ))
                    .into());
                }
                let payload = payloads.value(row);
                if payload.len() > MAX_TYPED_ROW_BYTES {
                    return Err(io::Error::other(format!(
                        "operator_intervention_required:Polymarket restore payload exceeds {MAX_TYPED_ROW_BYTES} bytes in {}",
                        path.display()
                    ))
                    .into());
                }
                let _ = dedupe
                    .observe(slug, payload.as_bytes())
                    .map_err(operator_dedupe_error)?;
            }
        }
    }
    Ok(true)
}

fn visit_polymarket_events<F>(
    message: &WsMessage,
    discovery: &BtcUpdownDiscovery,
    asset_to_slug: &BTreeMap<String, String>,
    collector_identity: &CollectorIdentity,
    recv_time_utc_ms: i64,
    source_native_payload_json: &str,
    mut emit: F,
) -> Result<PolymarketDispatchOutcome>
where
    F: FnMut(RawEvent) -> Result<()>,
{
    let mut outcome = PolymarketDispatchOutcome::default();
    match message {
        WsMessage::BestBidAsk(event) => {
            let asset_id = event.asset_id.to_string();
            let Some(slug) = verify_polymarket_business_asset(
                discovery,
                asset_to_slug,
                &event.market.to_string(),
                &asset_id,
            )?
            else {
                return Ok(outcome);
            };
            outcome.matched_assets.insert(asset_id.clone());
            emit(raw_event_with_recv_time(
                "polymarket_market",
                "best_bid_ask",
                &format!("{slug}:{}", event.asset_id),
                Some(event.timestamp.to_string()),
                recv_time_utc_ms,
                MARKET_WS_ENDPOINT,
                collector_identity,
                with_source_native_payload_json(
                    json!({
                        "event_type": "best_bid_ask",
                        "market": event.market.to_string(),
                        "asset_id": asset_id,
                        "slug": slug,
                        "best_bid": event.best_bid.to_string(),
                        "best_ask": event.best_ask.to_string(),
                        "spread": event.spread.to_string(),
                        "timestamp": event.timestamp
                    }),
                    source_native_payload_json,
                ),
            ))?;
        }
        WsMessage::Book(event) => {
            let asset_id = event.asset_id.to_string();
            let Some(slug) = verify_polymarket_business_asset(
                discovery,
                asset_to_slug,
                &event.market.to_string(),
                &asset_id,
            )?
            else {
                return Ok(outcome);
            };
            outcome.matched_assets.insert(asset_id.clone());
            emit(raw_event_with_recv_time(
                "polymarket_market",
                "book",
                &format!("{slug}:{}", event.asset_id),
                Some(event.timestamp.to_string()),
                recv_time_utc_ms,
                MARKET_WS_ENDPOINT,
                collector_identity,
                with_source_native_payload_json(
                    polymarket_book_raw_json(event, slug),
                    source_native_payload_json,
                ),
            ))?;
        }
        WsMessage::PriceChange(event) => {
            let condition_id = event.market.to_string();
            for change in &event.price_changes {
                let asset_id = change.asset_id.to_string();
                let Some(slug) = verify_polymarket_business_asset(
                    discovery,
                    asset_to_slug,
                    &condition_id,
                    &asset_id,
                )?
                else {
                    continue;
                };
                outcome.matched_assets.insert(asset_id.clone());
                let mut row_event = event.clone();
                row_event.price_changes = vec![change.clone()];
                emit(raw_event_with_recv_time(
                    "polymarket_market",
                    "price_change",
                    &format!("{slug}:{asset_id}"),
                    Some(row_event.timestamp.to_string()),
                    recv_time_utc_ms,
                    MARKET_WS_ENDPOINT,
                    collector_identity,
                    with_source_native_payload_json(
                        polymarket_price_change_raw_json(&row_event, asset_to_slug),
                        source_native_payload_json,
                    ),
                ))?;
            }
        }
        WsMessage::LastTradePrice(event) => {
            let asset_id = event.asset_id.to_string();
            let Some(slug) = verify_polymarket_business_asset(
                discovery,
                asset_to_slug,
                &event.market.to_string(),
                &asset_id,
            )?
            else {
                return Ok(outcome);
            };
            outcome.matched_assets.insert(asset_id.clone());
            emit(raw_event_with_recv_time(
                "polymarket_market",
                "last_trade_price",
                &format!("{slug}:{asset_id}"),
                Some(event.timestamp.to_string()),
                recv_time_utc_ms,
                MARKET_WS_ENDPOINT,
                collector_identity,
                with_source_native_payload_json(
                    polymarket_last_trade_raw_json(event, slug),
                    source_native_payload_json,
                ),
            ))?;
        }
        WsMessage::TickSizeChange(event) => {
            let asset_id = event.asset_id.to_string();
            let Some(slug) = verify_polymarket_business_asset(
                discovery,
                asset_to_slug,
                &event.market.to_string(),
                &asset_id,
            )?
            else {
                return Ok(outcome);
            };
            outcome.matched_assets.insert(asset_id.clone());
            emit(raw_event_with_recv_time(
                "polymarket_market",
                "tick_size_change",
                &format!("{slug}:{asset_id}"),
                Some(event.timestamp.to_string()),
                recv_time_utc_ms,
                MARKET_WS_ENDPOINT,
                collector_identity,
                with_source_native_payload_json(
                    polymarket_tick_size_change_raw_json(event, slug),
                    source_native_payload_json,
                ),
            ))?;
        }
        WsMessage::NewMarket(event) => {
            let Some((_verified_market, matched_assets)) = verify_target_market_identity(
                discovery,
                &event.id,
                &event.market.to_string(),
                Some(event.slug.as_str()),
                &event.asset_ids,
                Some(&event.outcomes),
                None,
                None,
            )?
            else {
                return Ok(outcome);
            };
            outcome.matched_assets = matched_assets;
            let market_raw_json = with_source_native_payload_json(
                polymarket_new_market_raw_json(event),
                source_native_payload_json,
            );
            emit(raw_event_with_recv_time(
                "polymarket_market",
                "new_market",
                &event.slug,
                Some(event.timestamp.to_string()),
                recv_time_utc_ms,
                MARKET_WS_ENDPOINT,
                collector_identity,
                market_raw_json,
            ))?;
        }
        WsMessage::MarketResolved(_) => {
            return Err(
                invalid_data("market_resolved must use the raw-first terminal handler").into(),
            );
        }
        _ => return Ok(outcome),
    }
    Ok(outcome)
}

fn verify_polymarket_business_asset<'a>(
    discovery: &'a BtcUpdownDiscovery,
    asset_to_slug: &BTreeMap<String, String>,
    condition_id: &str,
    asset_id: &str,
) -> Result<Option<&'a str>> {
    let Some(market) = std::iter::once(&discovery.current)
        .chain(discovery.next.as_ref())
        .find(|market| market.up_asset_id == asset_id || market.down_asset_id == asset_id)
    else {
        return Ok(None);
    };
    if market.condition_id != condition_id {
        return Err(invalid_data(format!(
            "Polymarket target asset {asset_id} carried contradictory condition_id {condition_id}"
        ))
        .into());
    }
    if asset_to_slug.get(asset_id).map(String::as_str) != Some(market.slug.as_str()) {
        return Ok(None);
    }
    Ok(Some(market.slug.as_str()))
}

#[cfg(test)]
fn build_polymarket_events(
    message: WsMessage,
    discovery: &BtcUpdownDiscovery,
    asset_to_slug: &BTreeMap<String, String>,
    collector_identity: &CollectorIdentity,
    recv_time_utc_ms: i64,
    source_native_payload_json: &str,
) -> Result<(PolymarketDispatchOutcome, Vec<RawEvent>)> {
    let mut events = Vec::new();
    let outcome = visit_polymarket_events(
        &message,
        discovery,
        asset_to_slug,
        collector_identity,
        recv_time_utc_ms,
        source_native_payload_json,
        |event| {
            events.push(event);
            Ok(())
        },
    )?;
    Ok((outcome, events))
}

#[cfg(test)]
fn retain_target_price_changes(
    event: &mut PriceChange,
    asset_to_slug: &BTreeMap<String, String>,
) -> BTreeSet<String> {
    event
        .price_changes
        .retain(|change| asset_to_slug.contains_key(&change.asset_id.to_string()));
    event
        .price_changes
        .iter()
        .map(|change| change.asset_id.to_string())
        .collect()
}

#[allow(clippy::too_many_arguments)]
fn verify_target_market_identity<'a>(
    discovery: &'a BtcUpdownDiscovery,
    market_id: &str,
    condition_id: &str,
    slug: Option<&str>,
    asset_ids: &[U256],
    outcomes: Option<&[String]>,
    winning_asset_id: Option<&U256>,
    winning_outcome: Option<&str>,
) -> Result<
    Option<(
        &'a crate::market_discovery::DiscoveredBtcUpdownMarket,
        BTreeSet<String>,
    )>,
> {
    let observed_assets = asset_ids
        .iter()
        .map(ToString::to_string)
        .collect::<BTreeSet<_>>();
    let target_assets = discovery.asset_ids();
    let observed_target_assets = observed_assets
        .intersection(&target_assets)
        .cloned()
        .collect::<BTreeSet<_>>();
    let winning_asset = winning_asset_id.map(ToString::to_string);
    let winning_target_asset = winning_asset
        .as_ref()
        .filter(|asset| target_assets.contains(*asset));
    let markets = std::iter::once(&discovery.current).chain(discovery.next.as_ref());
    let id_match = markets.clone().find(|market| market.id == market_id);
    let condition_match = markets
        .clone()
        .find(|market| market.condition_id == condition_id);
    let slug_match = slug.and_then(|slug| markets.clone().find(|market| market.slug == slug));
    if id_match.is_none()
        && condition_match.is_none()
        && slug_match.is_none()
        && observed_target_assets.is_empty()
        && winning_target_asset.is_none()
    {
        return Ok(None);
    }

    let asset_match = markets.clone().find(|market| {
        observed_target_assets.contains(&market.up_asset_id)
            || observed_target_assets.contains(&market.down_asset_id)
            || winning_target_asset
                .is_some_and(|asset| asset == &market.up_asset_id || asset == &market.down_asset_id)
    });
    let expected = condition_match
        .or(slug_match)
        .or(id_match)
        .or(asset_match)
        .ok_or_else(|| {
            invalid_data(format!(
                "Polymarket target identity could not be mapped to condition_id {condition_id}"
            ))
        })?;
    if market_id != expected.id {
        return Err(invalid_data(format!(
            "Polymarket target identity carried unexpected market id {market_id}"
        ))
        .into());
    }
    if condition_id != expected.condition_id {
        return Err(invalid_data(format!(
            "Polymarket target identity carried unexpected condition_id {condition_id}"
        ))
        .into());
    }
    if slug.is_some_and(|slug| slug != expected.slug.as_str()) {
        return Err(invalid_data(format!(
            "Polymarket condition {} carried unexpected slug {:?}",
            expected.condition_id, slug
        ))
        .into());
    }
    let expected_assets =
        BTreeSet::from([expected.up_asset_id.clone(), expected.down_asset_id.clone()]);
    let assets_valid = asset_ids.len() == expected_assets.len()
        && observed_assets.len() == expected_assets.len()
        && observed_assets == expected_assets;
    if !assets_valid {
        return Err(invalid_data(format!(
            "Polymarket condition {} carried contradictory asset mapping",
            expected.condition_id
        ))
        .into());
    }
    if let Some(outcomes) = outcomes
        && (outcomes.len() != 2
            || asset_ids.iter().zip(outcomes).any(|(asset, outcome)| {
                let expected_asset = match outcome.trim().to_ascii_lowercase().as_str() {
                    "up" => &expected.up_asset_id,
                    "down" => &expected.down_asset_id,
                    _ => return true,
                };
                asset.to_string() != *expected_asset
            }))
    {
        return Err(invalid_data(format!(
            "Polymarket condition {} carried contradictory outcome mapping",
            expected.condition_id
        ))
        .into());
    }
    if winning_asset
        .as_ref()
        .is_some_and(|asset| !expected_assets.contains(asset))
    {
        return Err(invalid_data(format!(
            "Polymarket condition {} carried a winning asset outside its subscribed asset set",
            expected.condition_id
        ))
        .into());
    }
    if let (Some(winning_asset), Some(winning_outcome)) = (&winning_asset, winning_outcome) {
        let expected_winning_outcome = if winning_asset == &expected.up_asset_id {
            "up"
        } else {
            "down"
        };
        if !winning_outcome
            .trim()
            .eq_ignore_ascii_case(expected_winning_outcome)
        {
            return Err(invalid_data(format!(
                "Polymarket condition {} carried contradictory winning outcome",
                expected.condition_id
            ))
            .into());
        }
    }
    Ok(Some((expected, expected_assets)))
}

async fn send_polymarket_metadata_event(
    sink: &SourceEventSink,
    run_started: Instant,
    market: &crate::market_discovery::DiscoveredBtcUpdownMarket,
    discovery_slot: &str,
    collector_identity: &CollectorIdentity,
) -> Result<PolymarketMetadataV3ReferenceRecord> {
    let role = match discovery_slot {
        "current" => MarketRuntimeRole::Current,
        "next" => MarketRuntimeRole::Next,
        other => {
            return Err(
                invalid_data(format!("unsupported Polymarket v3 discovery slot:{other}")).into(),
            );
        }
    };
    let row = polymarket_metadata_snapshot_v3_row(market, role, collector_identity)?;
    send_polymarket_metadata_v3_source_authority_row(sink, run_started, row).await
}

fn polymarket_v3_base_row(
    identity: &PendingPolymarketIdentity,
    row_kind: PolymarketMetadataRowKind,
    origin: PolymarketMetadataOrigin,
    timestamp_received: i64,
    lifecycle: MarketLifecycleState,
    runtime_role: MarketRuntimeRole,
    collector_identity: &CollectorIdentity,
) -> Result<PolymarketMarketMetadataV3Row> {
    Ok(PolymarketMarketMetadataV3Row {
        metadata_row_kind: row_kind,
        timestamp_received,
        collector_admission_sequence: 0,
        collector_admission_time_utc_ms: 0,
        metadata_origin: origin,
        collector_host_id: collector_identity.host_id.clone(),
        collector_region: collector_identity.region.clone(),
        schema_version: POLYMARKET_MARKET_METADATA_V3_SCHEMA_VERSION.to_owned(),
        slug: identity.slug.clone(),
        condition_id: identity.condition_id.clone(),
        clob_market_id: identity.market_id.clone(),
        asset_ids: serde_json::to_string(&[
            identity.up_asset_id.as_str(),
            identity.down_asset_id.as_str(),
        ])?,
        market_start_utc: identity.market_start_utc_ms,
        market_end_utc: identity.market_end_utc_ms,
        fixed_identity_verified_at_utc: identity.fixed_identity_verified_at_utc_ms,
        market_lifecycle_state: lifecycle,
        market_runtime_role: runtime_role,
        source_endpoint: None,
        source_endpoint_unavailable_reason: Some(
            SourceEndpointUnavailableReason::NotApplicableNoSourceEvidence,
        ),
        source_evidence_origin: None,
        source_evidence_event_type: None,
        source_evidence_channel: None,
        source_evidence_received_at_utc: None,
        row_evidence_validation_completed_at_utc: None,
        source_evidence_payload_json: None,
        source_evidence_raw_sha256: None,
        market_lifecycle_transition: None,
        lifecycle_scheduled_at_utc: None,
        lifecycle_applied_at_utc: None,
        market_runtime_role_transition: None,
        runtime_role_scheduled_at_utc: None,
        runtime_role_applied_at_utc: None,
        metadata_fetch_start_utc: None,
        closed: None,
        closed_time_raw: None,
        closed_time_utc: None,
        closed_time_check_passed: None,
        closed_time_check_failure_reason: None,
        automatically_resolved: None,
        uma_resolution_status: None,
        outcomes_raw: None,
        outcome_prices_raw: None,
        active: None,
        active_unavailable_reason: Some(ActiveUnavailableReason::NotApplicableForRowKind),
        accepting_orders: None,
        ws_platform_timestamp_raw: None,
        ws_platform_timestamp_utc: None,
        winning_asset_id: None,
        winning_outcome: None,
        resolution_evidence_source: None,
        resolution_evidence_raw_sha256: None,
        terminal_claim_owner: None,
        resolution_poll_attempt_ordinal: None,
        resolution_poll_scheduled_utc: None,
        resolution_poll_result: None,
        resolution_transport_error_class: None,
        resolution_transport_http_status: None,
        resolution_integrity_error_class: None,
        resolution_budget_horizon_utc: None,
        resolution_followup_status: None,
        resolution_poll_attempts_recorded: None,
        resolution_valid_response_count: None,
        resolution_transport_unavailable_count: None,
        resolution_missed_slot_count: None,
        last_valid_metadata_received_utc: None,
        terminal_predicate_passed: None,
        terminal_predicate_failure_reason: None,
        response_fields_unavailable_reason: Some(
            ResponseFieldsUnavailableReason::NotApplicableForRowKind,
        ),
    })
}

fn polymarket_metadata_snapshot_v3_row(
    market: &DiscoveredBtcUpdownMarket,
    role: MarketRuntimeRole,
    collector_identity: &CollectorIdentity,
) -> Result<PolymarketMarketMetadataV3Row> {
    let identity = PendingPolymarketIdentity::from_discovered(market)?;
    let received = market
        .metadata_received_utc_ms
        .ok_or_else(|| invalid_data("Polymarket metadata snapshot is missing receive time"))?;
    let payload = market
        .raw_json
        .as_deref()
        .filter(|payload| !payload.trim().is_empty())
        .ok_or_else(|| invalid_data("Polymarket metadata snapshot is missing source payload"))?;
    let digest = Sha256::digest(payload.as_bytes())
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    if digest != identity.discovery_source_raw_sha256 {
        return Err(invalid_data(format!(
            "Polymarket metadata snapshot digest mismatch:slug={}",
            identity.slug
        ))
        .into());
    }
    let sdk_market = serde_json::from_str::<SdkGammaMarket>(payload).map_err(|error| {
        invalid_data(format!(
            "Polymarket metadata snapshot SDK payload decode failed:slug={}:error={error}",
            identity.slug
        ))
    })?;
    let lifecycle = match role {
        MarketRuntimeRole::Current => MarketLifecycleState::Active,
        MarketRuntimeRole::Next => MarketLifecycleState::Prefetched,
        _ => {
            return Err(invalid_data("metadata snapshot role must be current or next").into());
        }
    };
    let mut row = polymarket_v3_base_row(
        &identity,
        PolymarketMetadataRowKind::MetadataSnapshot,
        PolymarketMetadataOrigin::GammaMarketsDiscovery,
        received,
        lifecycle,
        role,
        collector_identity,
    )?;
    row.source_endpoint = Some(GAMMA_MARKETS_ENDPOINT.to_owned());
    row.source_endpoint_unavailable_reason = None;
    row.source_evidence_origin = Some(SourceEvidenceOrigin::GammaMarketsDiscovery);
    row.source_evidence_event_type = Some(SourceEvidenceEventType::GammaMarketsDiscoveryResponse);
    row.source_evidence_received_at_utc = Some(received);
    row.row_evidence_validation_completed_at_utc =
        Some(market.metadata_validation_completed_at_utc_ms);
    row.source_evidence_payload_json = Some(payload.to_owned());
    row.source_evidence_raw_sha256 = Some(digest);
    row.metadata_fetch_start_utc = market.metadata_fetch_start_utc_ms;
    row.closed = sdk_market.closed;
    row.closed_time_raw = sdk_market.closed_time.clone();
    row.automatically_resolved = sdk_market.automatically_resolved;
    row.uma_resolution_status = sdk_market.uma_resolution_status.clone();
    row.outcomes_raw = sdk_market
        .outcomes
        .as_ref()
        .map(serde_json::to_string)
        .transpose()?;
    row.outcome_prices_raw = sdk_market
        .outcome_prices
        .as_ref()
        .map(serde_json::to_string)
        .transpose()?;
    row.active = sdk_market.active;
    row.active_unavailable_reason = sdk_market
        .active
        .is_none()
        .then_some(ActiveUnavailableReason::SourceFieldAbsent);
    row.accepting_orders = sdk_market.accepting_orders;
    row.response_fields_unavailable_reason = None;
    Ok(row)
}

fn polymarket_market_state_transition_v3_row(
    identity: &PendingPolymarketIdentity,
    transition: MarketRuntimeRoleTransition,
    applied_at_utc_ms: i64,
    collector_identity: &CollectorIdentity,
) -> Result<PolymarketMarketMetadataV3Row> {
    let (lifecycle_transition, scheduled_at, lifecycle, role, horizon, status) = match transition {
        MarketRuntimeRoleTransition::NextToCurrent => (
            Some(MarketLifecycleTransition::PrefetchedToActive),
            identity.market_start_utc_ms,
            MarketLifecycleState::Active,
            MarketRuntimeRole::Current,
            None,
            None,
        ),
        MarketRuntimeRoleTransition::CurrentToResolutionPending => (
            None,
            identity.market_end_utc_ms,
            MarketLifecycleState::Active,
            MarketRuntimeRole::ResolutionPending,
            Some(identity.market_end_utc_ms.saturating_add(8 * 60_000)),
            Some(ResolutionFollowupStatus::Pending),
        ),
        _ => {
            return Err(invalid_data(format!(
                "unsupported timer-owned Polymarket state transition:{}",
                transition.as_str()
            ))
            .into());
        }
    };
    let mut row = polymarket_v3_base_row(
        identity,
        PolymarketMetadataRowKind::MarketStateTransition,
        PolymarketMetadataOrigin::LocalMarketStateTimer,
        applied_at_utc_ms,
        lifecycle,
        role,
        collector_identity,
    )?;
    row.source_endpoint = Some(GAMMA_MARKETS_ENDPOINT.to_owned());
    row.source_endpoint_unavailable_reason = None;
    row.source_evidence_origin = Some(SourceEvidenceOrigin::GammaMarketsDiscovery);
    row.source_evidence_event_type = Some(SourceEvidenceEventType::GammaMarketsDiscoveryResponse);
    row.source_evidence_received_at_utc = Some(identity.discovery_source_received_at_utc_ms);
    row.source_evidence_raw_sha256 = Some(identity.discovery_source_raw_sha256.clone());
    row.market_lifecycle_transition = lifecycle_transition;
    row.lifecycle_scheduled_at_utc = lifecycle_transition.map(|_| scheduled_at);
    row.lifecycle_applied_at_utc = lifecycle_transition.map(|_| applied_at_utc_ms);
    row.market_runtime_role_transition = Some(transition);
    row.runtime_role_scheduled_at_utc = Some(scheduled_at);
    row.runtime_role_applied_at_utc = Some(applied_at_utc_ms);
    row.resolution_budget_horizon_utc = horizon;
    row.resolution_followup_status = status;
    Ok(row)
}

fn polymarket_candidate_to_active_v3_row(
    market: &DiscoveredBtcUpdownMarket,
    applied_at_utc_ms: i64,
    collector_identity: &CollectorIdentity,
) -> Result<PolymarketMarketMetadataV3Row> {
    let mut row = polymarket_metadata_snapshot_v3_row(
        market,
        MarketRuntimeRole::Current,
        collector_identity,
    )?;
    if applied_at_utc_ms < row.market_start_utc || applied_at_utc_ms >= row.market_end_utc {
        return Err(invalid_data(format!(
            "late Polymarket identity applied outside active window:slug={}:applied={applied_at_utc_ms}",
            row.slug
        ))
        .into());
    }
    row.metadata_row_kind = PolymarketMetadataRowKind::MarketStateTransition;
    row.metadata_origin = PolymarketMetadataOrigin::LocalMarketStateTimer;
    row.timestamp_received = applied_at_utc_ms;
    row.market_lifecycle_transition = Some(MarketLifecycleTransition::CandidateToActive);
    row.lifecycle_scheduled_at_utc = Some(row.market_start_utc);
    row.lifecycle_applied_at_utc = Some(applied_at_utc_ms);
    row.market_runtime_role_transition = Some(MarketRuntimeRoleTransition::NoneToCurrent);
    row.runtime_role_scheduled_at_utc = Some(row.market_start_utc);
    row.runtime_role_applied_at_utc = Some(applied_at_utc_ms);
    Ok(row)
}

fn gamma_by_slug_endpoint(slug: &str) -> String {
    GAMMA_MARKET_BY_SLUG_ENDPOINT.replace("{slug}", slug)
}

fn polymarket_resolution_attempt_v3_row<N>(
    pending: &PendingPolymarketResolution,
    completion: &GammaResolutionPollCompletion,
    validation_now_utc_ms: &N,
    ws_claimed: bool,
    collector_identity: &CollectorIdentity,
) -> Result<PolymarketMarketMetadataV3Row>
where
    N: Fn() -> i64 + Send + Sync,
{
    let mut row = polymarket_v3_base_row(
        &pending.identity,
        PolymarketMetadataRowKind::ResolutionPollAttempt,
        PolymarketMetadataOrigin::GammaBySlug,
        completion.completed_at_utc_ms,
        MarketLifecycleState::Active,
        MarketRuntimeRole::ResolutionPending,
        collector_identity,
    )?;
    row.source_endpoint = Some(gamma_by_slug_endpoint(&pending.identity.slug));
    row.source_endpoint_unavailable_reason = None;
    row.metadata_fetch_start_utc = Some(completion.fetch_start_utc_ms);
    row.resolution_poll_attempt_ordinal = Some(completion.ordinal);
    row.resolution_poll_scheduled_utc = Some(pending.slot_utc_ms(completion.ordinal));
    row.resolution_budget_horizon_utc = Some(pending.budget_horizon_utc_ms());
    row.resolution_followup_status = Some(ResolutionFollowupStatus::Pending);

    match &completion.result {
        Err(GammaResolutionPollFailure::Transport { class, http_status }) => {
            row.resolution_poll_result = Some(ResolutionPollResult::TransportUnavailable);
            row.resolution_transport_error_class = Some(*class);
            row.resolution_transport_http_status = *http_status;
            row.active_unavailable_reason = Some(ActiveUnavailableReason::SourceFieldAbsent);
            row.response_fields_unavailable_reason =
                Some(ResponseFieldsUnavailableReason::TransportUnavailable);
        }
        Err(GammaResolutionPollFailure::SdkDecodeOrSchema) => {
            row.resolution_poll_result = Some(ResolutionPollResult::IntegrityError);
            row.resolution_integrity_error_class =
                Some(ResolutionIntegrityErrorClass::SdkDecodeOrSchema);
            row.active_unavailable_reason = Some(ActiveUnavailableReason::SourceFieldAbsent);
            row.response_fields_unavailable_reason =
                Some(ResponseFieldsUnavailableReason::SdkDecodeOrSchemaError);
        }
        Ok(market) => {
            let payload = serde_json::to_string(market)?;
            let payload_sha256 = Sha256::digest(payload.as_bytes())
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect::<String>();
            let evaluation = evaluate_gamma_terminal_response(
                &pending.identity.gamma_terminal_identity(),
                GammaTerminalAttemptContext {
                    scheduled_at_utc_ms: pending.slot_utc_ms(completion.ordinal),
                    fetch_start_utc_ms: completion.fetch_start_utc_ms,
                    received_at_utc_ms: completion.completed_at_utc_ms,
                    response_bound_to_attempt: pending.in_flight_ordinal
                        == Some(completion.ordinal)
                        && pending.slot_utc_ms(completion.ordinal)
                            == completion.scheduled_at_utc_ms,
                },
                GammaTerminalResponse::Decoded(market),
            );
            let validation_completed_at_utc_ms = validation_now_utc_ms();
            if validation_completed_at_utc_ms < completion.completed_at_utc_ms {
                return Err(invalid_data(format!(
                    "Gamma resolution validation clock regressed:slug={}:ordinal={}:received={}:validation_completed={validation_completed_at_utc_ms}",
                    completion.slug, completion.ordinal, completion.completed_at_utc_ms
                ))
                .into());
            }
            let integrity_clean = matches!(
                evaluation.resolution_poll_result,
                ResolutionPollResult::Terminal | ResolutionPollResult::ValidNonterminal
            );
            let result = if ws_claimed && integrity_clean {
                ResolutionPollResult::PostTerminalClaimObservation
            } else {
                evaluation.resolution_poll_result
            };

            row.source_evidence_origin = Some(SourceEvidenceOrigin::GammaBySlug);
            row.source_evidence_event_type =
                Some(SourceEvidenceEventType::GammaMarketBySlugResponse);
            row.source_evidence_received_at_utc = Some(completion.completed_at_utc_ms);
            row.row_evidence_validation_completed_at_utc = Some(validation_completed_at_utc_ms);
            row.source_evidence_payload_json = Some(payload);
            row.source_evidence_raw_sha256 = Some(payload_sha256.clone());
            row.closed = market.closed;
            row.closed_time_raw = evaluation.closed_time_raw.clone();
            row.closed_time_utc = evaluation.closed_time_utc_ms;
            match evaluation.terminal_predicate_failure_reason {
                Some(TerminalPredicateFailureReason::ClosedTimeMissing) => {
                    row.closed_time_check_passed = Some(false);
                    row.closed_time_check_failure_reason =
                        Some(ClosedTimeCheckFailureReason::Missing);
                }
                Some(TerminalPredicateFailureReason::ClosedTimeParseError) => {
                    row.closed_time_check_passed = Some(false);
                    row.closed_time_check_failure_reason =
                        Some(ClosedTimeCheckFailureReason::ParseError);
                }
                Some(TerminalPredicateFailureReason::ClosedTimeBeforeMarketEnd) => {
                    row.closed_time_check_passed = Some(false);
                    row.closed_time_check_failure_reason =
                        Some(ClosedTimeCheckFailureReason::BeforeMarketEnd);
                }
                _ if evaluation.closed_time_utc_ms.is_some() => {
                    row.closed_time_check_passed = Some(true);
                }
                _ => {}
            }
            row.automatically_resolved = market.automatically_resolved;
            row.uma_resolution_status = market.uma_resolution_status.clone();
            row.outcomes_raw = market
                .outcomes
                .as_ref()
                .map(serde_json::to_string)
                .transpose()?;
            row.outcome_prices_raw = market
                .outcome_prices
                .as_ref()
                .map(serde_json::to_string)
                .transpose()?;
            row.active = evaluation.observed_active;
            row.active_unavailable_reason = evaluation
                .observed_active
                .is_none()
                .then_some(ActiveUnavailableReason::SourceFieldAbsent);
            row.accepting_orders = market.accepting_orders;
            row.resolution_poll_result = Some(result);
            row.resolution_integrity_error_class = evaluation.resolution_integrity_error_class;
            row.terminal_predicate_passed = evaluation.terminal_predicate_passed;
            row.terminal_predicate_failure_reason = evaluation.terminal_predicate_failure_reason;
            row.response_fields_unavailable_reason = None;

            if result == ResolutionPollResult::Terminal {
                let winner = evaluation.winner.ok_or_else(|| {
                    invalid_data("Gamma terminal predicate passed without a derived winner")
                })?;
                row.winning_asset_id = Some(winner.winning_asset_id);
                row.winning_outcome = Some(winner.winning_outcome);
                row.resolution_evidence_source = Some(ResolutionEvidenceSource::GammaBySlug);
                row.resolution_evidence_raw_sha256 = Some(payload_sha256);
                row.terminal_claim_owner = Some(TerminalClaimOwner::GammaBySlug);
                row.resolution_followup_status =
                    Some(ResolutionFollowupStatus::TerminalGammaFallback);
            } else if result == ResolutionPollResult::PostTerminalClaimObservation {
                row.terminal_claim_owner = Some(TerminalClaimOwner::MarketResolvedWs);
            }
        }
    }
    Ok(row)
}

fn complete_polymarket_terminal_transition(
    row: &mut PolymarketMarketMetadataV3Row,
    applied_at_utc_ms: i64,
) {
    row.market_lifecycle_state = MarketLifecycleState::Retired;
    row.market_runtime_role = MarketRuntimeRole::None;
    row.market_lifecycle_transition = Some(MarketLifecycleTransition::ActiveToRetired);
    row.lifecycle_applied_at_utc = Some(applied_at_utc_ms);
    row.market_runtime_role_transition = Some(MarketRuntimeRoleTransition::ResolutionPendingToNone);
    row.runtime_role_applied_at_utc = Some(applied_at_utc_ms);
}

fn polymarket_resolution_terminal_ws_v3_row(
    pending: &PendingPolymarketResolution,
    evidence: &PolymarketWsTerminalEvidence,
    applied_at_utc_ms: i64,
    collector_identity: &CollectorIdentity,
) -> Result<PolymarketMarketMetadataV3Row> {
    let mut row = polymarket_v3_base_row(
        &pending.identity,
        PolymarketMetadataRowKind::ResolutionTerminalWs,
        PolymarketMetadataOrigin::MarketResolvedWs,
        evidence.source_received_at_utc_ms,
        MarketLifecycleState::Retired,
        MarketRuntimeRole::None,
        collector_identity,
    )?;
    row.source_endpoint = Some(MARKET_WS_ENDPOINT.to_owned());
    row.source_endpoint_unavailable_reason = None;
    row.source_evidence_origin = Some(SourceEvidenceOrigin::MarketResolvedWs);
    row.source_evidence_event_type = Some(SourceEvidenceEventType::MarketResolved);
    row.source_evidence_channel = Some(SourceEvidenceChannel::Market);
    row.source_evidence_received_at_utc = Some(evidence.source_received_at_utc_ms);
    row.row_evidence_validation_completed_at_utc = Some(evidence.validation_completed_at_utc_ms);
    row.source_evidence_payload_json = Some(evidence.source_payload_json.clone());
    row.source_evidence_raw_sha256 = Some(evidence.source_payload_sha256.clone());
    row.ws_platform_timestamp_raw = Some(evidence.platform_timestamp_raw.clone());
    row.ws_platform_timestamp_utc = Some(evidence.platform_timestamp_utc_ms);
    row.winning_asset_id = Some(evidence.winning_asset_id.clone());
    row.winning_outcome = Some(evidence.winning_outcome.clone());
    row.resolution_evidence_source = Some(ResolutionEvidenceSource::MarketResolvedWs);
    row.resolution_evidence_raw_sha256 = Some(evidence.source_payload_sha256.clone());
    row.terminal_claim_owner = Some(TerminalClaimOwner::MarketResolvedWs);
    row.resolution_budget_horizon_utc = Some(pending.budget_horizon_utc_ms());
    row.resolution_followup_status = Some(ResolutionFollowupStatus::TerminalWs);
    row.terminal_predicate_passed = Some(true);
    row.response_fields_unavailable_reason = None;
    complete_polymarket_terminal_transition(&mut row, applied_at_utc_ms);
    Ok(row)
}

fn polymarket_resolution_followup_summary_v3_row(
    pending: &PendingPolymarketResolution,
    applied_at_utc_ms: i64,
    collector_identity: &CollectorIdentity,
) -> Result<PolymarketMarketMetadataV3Row> {
    let mut row = polymarket_v3_base_row(
        &pending.identity,
        PolymarketMetadataRowKind::ResolutionFollowupSummary,
        PolymarketMetadataOrigin::LocalFollowupScheduler,
        applied_at_utc_ms,
        MarketLifecycleState::Active,
        MarketRuntimeRole::None,
        collector_identity,
    )?;
    row.market_runtime_role_transition = Some(MarketRuntimeRoleTransition::ResolutionPendingToNone);
    row.runtime_role_applied_at_utc = Some(applied_at_utc_ms);
    row.resolution_budget_horizon_utc = Some(pending.budget_horizon_utc_ms());
    row.resolution_followup_status = Some(if pending.valid_response_count > 0 {
        ResolutionFollowupStatus::BudgetExhaustedAfterValidNonterminal
    } else {
        ResolutionFollowupStatus::BudgetExhaustedWithoutValidResponse
    });
    row.resolution_poll_attempts_recorded = Some(pending.attempts_recorded);
    row.resolution_valid_response_count = Some(pending.valid_response_count);
    row.resolution_transport_unavailable_count = Some(pending.transport_unavailable_count);
    row.resolution_missed_slot_count = Some(pending.missed_slot_count);
    row.last_valid_metadata_received_utc = pending.last_valid_metadata_received_at_utc_ms;
    Ok(row)
}

async fn send_polymarket_metadata_v3_row(
    sink: &SourceEventSink,
    run_started: Instant,
    row: PolymarketMarketMetadataV3Row,
) -> Result<()> {
    let event = polymarket_metadata_v3_raw_event(row)?;
    send_event(sink, run_started, event).await
}

async fn send_polymarket_metadata_v3_source_authority_row(
    sink: &SourceEventSink,
    run_started: Instant,
    row: PolymarketMarketMetadataV3Row,
) -> Result<PolymarketMetadataV3ReferenceRecord> {
    let authority = PolymarketMetadataV3ReferenceRecord::from(&row);
    let event = polymarket_metadata_v3_raw_event(row)?;
    match send_event_with_admission_outcome(sink, run_started, event).await? {
        EventAdmissionOutcome::Admitted => Ok(authority),
        EventAdmissionOutcome::Deferred => Err(invalid_data(
            "polymarket_metadata_source_authority_not_admitted:utc_deferred",
        )
        .into()),
        EventAdmissionOutcome::Cutoff => Err(invalid_data(
            "polymarket_metadata_source_authority_not_admitted:controlled_runtime_cutoff",
        )
        .into()),
    }
}

fn polymarket_metadata_v3_raw_event(row: PolymarketMarketMetadataV3Row) -> Result<RawEvent> {
    let event_type = row.metadata_row_kind.as_str();
    let endpoint = row.source_endpoint.as_deref().unwrap_or_default();
    Ok(raw_event_with_recv_time(
        "polymarket_market_metadata",
        event_type,
        &row.slug,
        None,
        row.timestamp_received,
        endpoint,
        &CollectorIdentity {
            host_id: row.collector_host_id.clone(),
            region: row.collector_region.clone(),
        },
        serde_json::from_str(&row.to_draft_json()?)?,
    ))
}

async fn send_polymarket_metadata_v3_rows_atomically(
    sink: &SourceEventSink,
    run_started: Instant,
    rows: Vec<PolymarketMarketMetadataV3Row>,
) -> Result<()> {
    if rows.len() <= 1 {
        if let Some(row) = rows.into_iter().next() {
            send_polymarket_metadata_v3_row(sink, run_started, row).await?;
        }
        return Ok(());
    }

    let events = rows
        .into_iter()
        .map(polymarket_metadata_v3_raw_event)
        .collect::<Result<Vec<_>>>()?;
    let recv_time_utc_ms = events[0].recv_time_utc_ms;
    let partition = utc_hour_string_from_ms(recv_time_utc_ms)
        .ok_or_else(|| invalid_data("Polymarket terminal bundle UTC partition is unavailable"))?;
    if events.iter().any(|event| {
        utc_hour_string_from_ms(event.recv_time_utc_ms).as_deref() != Some(partition.as_str())
    }) {
        let reason = "Polymarket terminal bundle spans UTC partitions".to_owned();
        record_polymarket_fanout_drop(sink, recv_time_utc_ms, 0, events.len());
        record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
        return Err(invalid_data(reason).into());
    }

    let mut total_bytes = 0_usize;
    let mut measured_bytes = Vec::with_capacity(events.len());
    for event in &events {
        let bytes = owned_event_bytes(event);
        if bytes > MAX_TYPED_ROW_BYTES {
            let reason = format!(
                "operator_intervention_required:max_typed_row_bytes_exceeded:polymarket_market_metadata:bytes={bytes}:limit={MAX_TYPED_ROW_BYTES}"
            );
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, 0, events.len());
            record_gap_at(&sink.gaps, recv_time_utc_ms, reason.clone());
            return Err(invalid_data(reason).into());
        }
        total_bytes = total_bytes
            .checked_add(bytes)
            .ok_or_else(|| invalid_data("Polymarket terminal bundle byte count overflow"))?;
        measured_bytes.push(bytes);
    }
    let mut reservation = match sink
        .inflight_budget
        .acquire(events.len(), total_bytes, BUFFER_ACQUIRE_TIMEOUT)
        .await
    {
        Ok(reservation) => reservation,
        Err(error) => {
            sink.source_queue_backpressure.record_timeout();
            record_polymarket_fanout_drop(sink, recv_time_utc_ms, 0, events.len());
            record_gap_at(
                &sink.gaps,
                recv_time_utc_ms,
                format!("polymarket_terminal_bundle_budget_failed:{error}"),
            );
            return Err(error.into());
        }
    };
    let mut prepared = Vec::with_capacity(events.len());
    for (event, bytes) in events.into_iter().zip(measured_bytes) {
        let row_reservation = reservation.split(1, bytes)?;
        prepared.push(InflightRawEvent {
            event,
            control: None,
            admission_gaps: Vec::new(),
            raw_day_permit: None,
            _source_recv_monotonic_ms: monotonic_ms(run_started),
            _reservation: Some(row_reservation),
        });
    }
    drop(reservation);
    send_polymarket_events_atomically(sink, recv_time_utc_ms, prepared, || Ok(())).await
}

#[cfg(test)]
fn polymarket_metadata_snapshot_raw_json(
    market: &crate::market_discovery::DiscoveredBtcUpdownMarket,
    discovery_slot: &str,
) -> Value {
    json!({
        "event_type": "active_scan",
        "metadata_source": "active_scan",
        "discovery_slot": discovery_slot,
        "slug": market.slug,
        "condition_id": market.condition_id,
        "clob_market_id": market.id,
        "asset_ids": [market.up_asset_id, market.down_asset_id],
        "metadata_fetch_start_utc": market.metadata_fetch_start_utc_ms,
        "market_start_utc": market.start_ts_s * 1000,
        "market_end_utc": market.end_ts_s * 1000,
        "active": market.active,
        "accepting_orders": market.accepting_orders,
        "market_lifecycle_state": if discovery_slot == "next" {
            "prefetched"
        } else if market.active {
            "active"
        } else {
            "candidate"
        },
        "tick_size": market.tick_size,
        "min_size": market.min_size,
        "fee_schedule_raw": market.fee_schedule_raw,
        "reward_eligibility_raw": market.reward_eligibility_raw,
        "metadata_unavailable_reason": missing_metadata_reason(market),
        "same_condition_market_verified": true,
        "raw_json_sha256": market.raw_json_sha256,
        "gamma_market_raw_json": market.raw_json,
    })
}

#[cfg(test)]
fn polymarket_window_end_observation_raw_json_from_discovery(
    market: &crate::market_discovery::DiscoveredBtcUpdownMarket,
) -> Value {
    let mut value = polymarket_metadata_snapshot_raw_json(market, "current_window_end_unresolved");
    let reason = "market_resolved_not_observed_before_window_end";
    if let Some(object) = value.as_object_mut() {
        object.insert(
            "market_lifecycle_state".to_owned(),
            json!("unresolved_window_end_observation"),
        );
        object.insert("window_end_observation_reason".to_owned(), json!(reason));
        let mut reasons = missing_metadata_reason(market)
            .into_iter()
            .collect::<Vec<_>>();
        reasons.push(reason.to_owned());
        object.insert("metadata_unavailable_reason".to_owned(), json!(reasons));
    }
    value
}

#[cfg(test)]
fn missing_metadata_reason(
    market: &crate::market_discovery::DiscoveredBtcUpdownMarket,
) -> Option<String> {
    let missing = [
        ("tick_size", market.tick_size.is_none()),
        ("min_size", market.min_size.is_none()),
        ("fee_schedule_raw", market.fee_schedule_raw.is_none()),
        (
            "reward_eligibility_raw",
            market.reward_eligibility_raw.is_none(),
        ),
    ]
    .into_iter()
    .filter_map(|(field, missing)| missing.then_some(field))
    .collect::<Vec<_>>();
    (!missing.is_empty()).then(|| format!("gamma_market_fields_unavailable:{}", missing.join(",")))
}

fn rtds_source_native_payload_json(
    message: &polymarket_client_sdk_v2::rtds::RtdsMessage,
) -> Result<String> {
    let canonical = serde_json::to_string(&json!({
        "source": "polymarket_rtds_chainlink_btc_usd",
        "topic": message.topic,
        "type": message.msg_type,
        "timestamp": message.timestamp,
        "payload": message.payload,
    }))?;
    if canonical.len() > MAX_TYPED_ROW_BYTES {
        return Err(io::Error::other(format!(
            "operator_intervention_required:RTDS source-native payload exceeds {MAX_TYPED_ROW_BYTES} bytes"
        ))
        .into());
    }
    Ok(canonical)
}

fn restore_rtds_dedupe(
    dataset_root: &Path,
    restore_time_ms: i64,
) -> Result<TimedFingerprintWindow> {
    let mut window =
        TimedFingerprintWindow::with_limits(RTDS_DEDUPE_WINDOW_MS, RTDS_DEDUPE_MAX_KEYS);
    let mut paths = Vec::new();
    let days = BTreeSet::from([
        utc_day_string_from_ms(restore_time_ms.saturating_sub(RTDS_DEDUPE_WINDOW_MS))
            .ok_or_else(|| io::Error::other("RTDS previous UTC day is out of range"))?,
        utc_day_string_from_ms(restore_time_ms)
            .ok_or_else(|| io::Error::other("RTDS current UTC day is out of range"))?,
    ]);
    for day in days {
        paths.extend(finalized_parquet_files(
            &dataset_root
                .join("training")
                .join("typed_raw")
                .join(format!("utc_day={day}"))
                .join("source_kind=polymarket_rtds_chainlink_btc_usd"),
        )?);
    }
    paths.sort_by_key(|path| finalized_parquet_order_key(path));
    let window_start_ms = restore_time_ms.saturating_sub(RTDS_DEDUPE_WINDOW_MS);
    for path in paths {
        let builder = ParquetRecordBatchReaderBuilder::try_new(File::open(&path)?)?;
        if builder.schema().index_of("timestamp_received").is_err()
            || builder
                .schema()
                .index_of("source_native_payload_json")
                .is_err()
        {
            continue;
        }
        if builder.metadata().file_metadata().num_rows() == 0 {
            continue;
        }
        let projection = ProjectionMask::columns(
            builder.parquet_schema(),
            ["timestamp_received", "source_native_payload_json"],
        );
        let mut reader = builder
            .with_projection(projection)
            .with_batch_size(16)
            .build()?;
        for batch in &mut reader {
            let batch = batch?;
            let received_index = batch.schema().index_of("timestamp_received")?;
            let payload_index = batch.schema().index_of("source_native_payload_json")?;
            let received = batch
                .column(received_index)
                .as_any()
                .downcast_ref::<TimestampMillisecondArray>()
                .ok_or_else(|| io::Error::other("RTDS restore receive time is not timestamp-ms"))?;
            let payloads = batch
                .column(payload_index)
                .as_any()
                .downcast_ref::<StringArray>()
                .ok_or_else(|| io::Error::other("RTDS restore payload is not UTF8"))?;
            for row in 0..batch.num_rows() {
                if received.is_null(row) || payloads.is_null(row) {
                    return Err(io::Error::other(format!(
                        "RTDS restore key missing in {}",
                        path.display()
                    ))
                    .into());
                }
                let received_ms = received.value(row);
                if received_ms < window_start_ms {
                    continue;
                }
                let payload = payloads.value(row);
                if payload.len() > MAX_TYPED_ROW_BYTES {
                    return Err(io::Error::other(format!(
                        "operator_intervention_required:RTDS restore payload exceeds {MAX_TYPED_ROW_BYTES} bytes in {}",
                        path.display()
                    ))
                    .into());
                }
                let _ = window
                    .observe(payload.as_bytes(), received_ms)
                    .map_err(operator_dedupe_error)?;
            }
        }
    }
    Ok(window)
}

async fn run_rtds_source_with_spec(
    spec: RtdsSourceSpec,
    dataset_root: PathBuf,
    sink: SourceEventSink,
    collector_identity: CollectorIdentity,
    deadline: Option<Instant>,
    run_started: Instant,
) -> Result<()> {
    let restore_time_ms = now_ms();
    let mut dedupe =
        tokio::task::spawn_blocking(move || restore_rtds_dedupe(&dataset_root, restore_time_ms))
            .await
            .map_err(|error| {
                invalid_data(format!(
                    "operator_intervention_required:RTDS dedupe restore join failed:{error}"
                ))
            })?
            .map_err(|error| {
                invalid_data(format!(
                    "operator_intervention_required:RTDS dedupe restore failed:{error}"
                ))
            })?;
    let subscription = Subscription::chainlink_prices(Some("btc/usd".to_owned()));
    let mut runtime = RtdsSdkRuntime::new(spec.endpoint.clone(), spec.ws_config.clone())?;
    runtime.replace_subscription(subscription)?;
    let mut recorded_generation = runtime.connection_generation();

    loop {
        match runtime.recv_event_until(deadline).await {
            Ok(Some(RtdsRuntimeEvent::Applied(applied))) => {
                record_rtds_generation_advance(
                    &mut recorded_generation,
                    applied.generation,
                    &sink,
                )?;
            }
            Ok(Some(RtdsRuntimeEvent::Message(message))) => {
                let observed_generation = message
                    .freshness_generation
                    .unwrap_or_else(|| runtime.connection_generation());
                record_rtds_generation_advance(
                    &mut recorded_generation,
                    observed_generation,
                    &sink,
                )?;
                emit_rtds_message(
                    &sink,
                    &collector_identity,
                    run_started,
                    &mut dedupe,
                    message.message,
                )
                .await?;
            }
            Ok(None) => break,
            Err(error) => {
                if let SdkStreamError::Lagged(count) = &error {
                    sink.source_queue_backpressure.record_lag(
                        "polymarket_rtds_chainlink_btc_usd",
                        now_ms(),
                        *count,
                    );
                }
                record_gap(&sink.gaps, format!("rtds_sdk_stream_fatal:{error}"));
                return Err(error.into());
            }
        }
    }
    Ok(())
}

fn record_rtds_generation_advance(
    recorded_generation: &mut u64,
    generation: u64,
    sink: &SourceEventSink,
) -> Result<()> {
    let newly_observed = generation
        .checked_sub(*recorded_generation)
        .ok_or_else(|| invalid_data("RTDS recorded connection generation regressed"))?;
    if newly_observed == 0 {
        return Ok(());
    }
    for _ in 0..newly_observed {
        sink.source_queue_backpressure
            .record_reconnect("polymarket_rtds_chainlink_btc_usd", now_ms());
    }
    *recorded_generation = generation;
    Ok(())
}

async fn emit_rtds_message(
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    run_started: Instant,
    dedupe: &mut TimedFingerprintWindow,
    message: polymarket_client_sdk_v2::rtds::RtdsMessage,
) -> Result<bool> {
    let recv_time_utc_ms = now_ms();
    let classified = match classify_rtds_message(&message, recv_time_utc_ms) {
        Ok(Some(classified)) => classified,
        Ok(None) => return Ok(false),
        Err(error) => {
            record_gap(
                &sink.gaps,
                format!("rtds_unparseable_chainlink_payload:{error}"),
            );
            return Err(error);
        }
    };
    let source_native_payload_json = rtds_source_native_payload_json(&message)?;
    if dedupe
        .observe(source_native_payload_json.as_bytes(), recv_time_utc_ms)
        .map_err(operator_dedupe_error)?
        == FingerprintDecision::Duplicate
    {
        sink.source_queue_backpressure.record_structural_dedupe(
            "polymarket_rtds_chainlink_btc_usd",
            recv_time_utc_ms,
            1,
        );
        return Ok(false);
    }
    let source_ts = classified.payload.timestamp;
    let source_identifier = classified.payload.symbol.clone();
    let value = classified.payload.value.to_string();
    let is_fresh = classified.freshness_status == "fresh";
    send_event(
        sink,
        run_started,
        RawEvent {
            source_kind: "polymarket_rtds_chainlink_btc_usd".to_owned(),
            source_event_type: message.msg_type.clone(),
            source_identifier,
            source_ts: Some(source_ts.to_string()),
            recv_time_utc_ms,
            collector_host_id: collector_identity.host_id.clone(),
            collector_region: collector_identity.region.clone(),
            source_endpoint: RTDS_WS_ENDPOINT.to_owned(),
            raw_json: json!({
                "topic": message.topic,
                "type": message.msg_type,
                "message_timestamp": message.timestamp,
                "payload_timestamp": classified.payload.timestamp,
                "symbol": classified.payload.symbol,
                "value": value,
                "age_ms": classified.age_ms,
                "freshness_status": classified.freshness_status,
                "subscription_raw_json": rtds_subscription_evidence_json(),
                "payload": message.payload,
                "source_native_payload_json": source_native_payload_json,
            })
            .to_string(),
            collector_admission: None,
            parquet_raw_layout_version: 1,
            parquet_raw_source_kind: "polymarket_rtds_chainlink_btc_usd".to_owned(),
        },
    )
    .await?;
    Ok(is_fresh)
}

#[cfg(test)]
async fn run_binance_depth_source_with_spec(
    spec: BinanceDepthSpec,
    sink: SourceEventSink,
    collector_identity: CollectorIdentity,
    deadline: Option<Instant>,
    run_started: Instant,
) -> Result<()> {
    run_binance_depth_source_with_spec_and_control(
        spec,
        sink,
        collector_identity,
        deadline,
        run_started,
        None,
    )
    .await
}

async fn run_binance_depth_source_with_spec_and_control(
    spec: BinanceDepthSpec,
    sink: SourceEventSink,
    collector_identity: CollectorIdentity,
    deadline: Option<Instant>,
    run_started: Instant,
    mut control_rx: Option<mpsc::Receiver<DepthSourceControl>>,
) -> Result<()> {
    let http_client = reqwest::Client::builder()
        .connect_timeout(Duration::from_secs(BINANCE_HTTP_CONNECT_TIMEOUT_SECS))
        .timeout(Duration::from_secs(BINANCE_HTTP_TOTAL_TIMEOUT_SECS))
        .build()?;
    let source_sequence_epoch_id = depth_source_sequence_epoch_id(&collector_identity)?;
    let ingress_sequence = DepthIngressSequenceAllocator::default();
    let snapshot_not_before = DepthSnapshotNotBefore::default();
    let mut connection_generation = 0_u64;
    let mut snapshot_trigger_reason = "bootstrap".to_owned();
    let mut recovery = SourceRecoverySupervisor::new(
        "binance_depth_update",
        u64::try_from(now_ms()).unwrap_or_default(),
    );
    #[cfg(test)]
    recovery.set_wait_override(spec.recovery_wait_override);
    'connections: while !deadline_reached(deadline) {
        if let Some(receiver) = control_rx.as_mut() {
            loop {
                match receiver.try_recv() {
                    Ok(control) => {
                        if handle_depth_source_control(control).await? {
                            break 'connections;
                        }
                    }
                    Err(mpsc::error::TryRecvError::Empty) => break,
                    Err(mpsc::error::TryRecvError::Disconnected) => {
                        return Err(invalid_data("depth source control channel closed").into());
                    }
                }
            }
        }
        let (depth_stream, _) = match timeout(
            Duration::from_secs(WS_CONNECT_TIMEOUT_SECS),
            connect_async(&spec.websocket_endpoint),
        )
        .await
        {
            Ok(Ok(connected)) => connected,
            Ok(Err(err)) => {
                let reason = if snapshot_trigger_reason == "bootstrap" {
                    format!("connect_error:{err}")
                } else {
                    format!("reconnect_error:{err}")
                };
                if !handle_binance_depth_ws_connect_failure(
                    &sink,
                    &mut recovery,
                    &mut snapshot_trigger_reason,
                    reason,
                    deadline,
                )
                .await
                {
                    break;
                }
                continue;
            }
            Err(_) => {
                let reason = if snapshot_trigger_reason == "bootstrap" {
                    "connect_timeout".to_owned()
                } else {
                    "reconnect_timeout".to_owned()
                };
                if !handle_binance_depth_ws_connect_failure(
                    &sink,
                    &mut recovery,
                    &mut snapshot_trigger_reason,
                    reason,
                    deadline,
                )
                .await
                {
                    break;
                }
                continue;
            }
        };
        connection_generation = connection_generation
            .checked_add(1)
            .ok_or_else(|| invalid_data("Binance depth connection generation overflow"))?;
        let update_exit = run_binance_depth_update_ws_source_with_control(
            depth_stream,
            BinanceDepthUpdateContext {
                http_client: http_client.clone(),
                sink: sink.clone(),
                collector_identity: collector_identity.clone(),
                deadline,
                run_started,
                spec: spec.clone(),
                source_sequence_epoch_id: source_sequence_epoch_id.clone(),
                connection_generation,
                ingress_sequence: ingress_sequence.clone(),
                snapshot_not_before: snapshot_not_before.clone(),
                initial_snapshot_trigger_reason: snapshot_trigger_reason.clone(),
                #[cfg(test)]
                pending_limits: None,
            },
            control_rx.as_mut(),
        )
        .await?;
        match update_exit {
            BinanceDepthUpdateExit::DeadlineReached => break,
            BinanceDepthUpdateExit::Stopped => break,
            BinanceDepthUpdateExit::StreamEnded {
                reason,
                saw_transport,
            } => {
                if saw_transport {
                    recovery.record_business_recovery();
                    sink.source_queue_backpressure
                        .set_recovery_active("binance_depth_update", false);
                }
                if !prepare_binance_depth_reconnect(
                    &sink,
                    &mut recovery,
                    &mut snapshot_trigger_reason,
                    reason,
                    deadline,
                )
                .await
                {
                    break;
                }
            }
        }
    }
    Ok(())
}

async fn handle_binance_depth_ws_connect_failure(
    sink: &SourceEventSink,
    recovery: &mut SourceRecoverySupervisor,
    snapshot_trigger_reason: &mut String,
    reason: String,
    deadline: Option<Instant>,
) -> bool {
    prepare_binance_depth_reconnect(sink, recovery, snapshot_trigger_reason, reason, deadline).await
}

async fn prepare_binance_depth_reconnect(
    sink: &SourceEventSink,
    recovery: &mut SourceRecoverySupervisor,
    snapshot_trigger_reason: &mut String,
    reason: String,
    deadline: Option<Instant>,
) -> bool {
    *snapshot_trigger_reason = format!("reconnect:{reason}");
    wait_for_source_recovery(recovery, sink, deadline).await
}

#[allow(clippy::too_many_arguments)]
async fn fetch_binance_depth_snapshot_cycle(
    http_client: reqwest::Client,
    collector_identity: CollectorIdentity,
    snapshot_endpoint: String,
    trigger_reason: String,
    source_sequence_epoch_id: String,
    connection_generation: u64,
    ingress_sequence: DepthIngressSequenceAllocator,
    snapshot_not_before: DepthSnapshotNotBefore,
) -> Result<DepthSnapshotCycleOutcome> {
    let mut last_unavailable_reason = "snapshot_attempts_exhausted".to_owned();
    let snapshot_jitter_seed =
        depth_snapshot_jitter_seed(&source_sequence_epoch_id, connection_generation);
    for attempt in 1..=BINANCE_DEPTH_SNAPSHOT_MAX_ATTEMPTS {
        snapshot_not_before.wait().await;
        let snapshot_fetch_start_utc = now_ms();
        let fetched = async {
            let mut response = http_client
                .get(&snapshot_endpoint)
                .send()
                .await
                .map_err(|error| format!("request:{error}"))?;
            let status = response.status();
            let retry_after = binance_snapshot_retry_after(response.headers(), status);
            if let Some(delay) = retry_after {
                snapshot_not_before.defer_for(delay);
            }
            if !status.is_success() {
                let _ = ingress_sequence.allocate()?;
                if matches!(status.as_u16(), 408 | 418 | 429) || status.is_server_error() {
                    return Ok::<_, String>(DepthSnapshotAttempt::Unavailable {
                        reason: format!("http_status:{status}"),
                        retry_after,
                    });
                }
                return Err(format!("http_status_terminal:{status}"));
            }
            let body_limit = u64::try_from(MAX_TYPED_ROW_BYTES)
                .map_err(|_| "snapshot_body_limit_conversion".to_owned())?;
            if response
                .content_length()
                .is_some_and(|length| length > body_limit)
            {
                return Err(format!(
                    "schema:response_body_too_large:limit={MAX_TYPED_ROW_BYTES}"
                ));
            }
            let mut body = Vec::with_capacity(
                response
                    .content_length()
                    .and_then(|length| usize::try_from(length).ok())
                    .unwrap_or_default()
                    .min(MAX_TYPED_ROW_BYTES),
            );
            while let Some(chunk) = response
                .chunk()
                .await
                .map_err(|error| format!("body:{error}"))?
            {
                let next_length = body
                    .len()
                    .checked_add(chunk.len())
                    .ok_or_else(|| "schema:response_body_length_overflow".to_owned())?;
                if next_length > MAX_TYPED_ROW_BYTES {
                    return Err(format!(
                        "schema:response_body_too_large:limit={MAX_TYPED_ROW_BYTES}"
                    ));
                }
                body.extend_from_slice(&chunk);
            }
            let timestamp_received = now_ms();
            let depth_ingress_sequence = ingress_sequence.allocate()?;
            if body.is_empty() {
                return Err("empty_body".to_owned());
            }
            let mut snapshot_value =
                serde_json::from_slice::<Value>(&body).map_err(|error| format!("json:{error}"))?;
            let snapshot_last_update_id = snapshot_value
                .get("lastUpdateId")
                .and_then(Value::as_u64)
                .filter(|id| *id > 0)
                .ok_or_else(|| "last_update_id_missing".to_owned())?;
            let object = snapshot_value
                .as_object_mut()
                .ok_or_else(|| "snapshot_not_object".to_owned())?;
            object.insert("snapshot_trigger_reason".to_owned(), json!(trigger_reason));
            object.insert(
                "snapshot_fetch_start_utc".to_owned(),
                json!(snapshot_fetch_start_utc),
            );
            object.insert(
                "source_sequence_epoch_id".to_owned(),
                json!(source_sequence_epoch_id),
            );
            object.insert(
                "connection_generation".to_owned(),
                json!(connection_generation),
            );
            object.insert(
                "depth_ingress_sequence".to_owned(),
                json!(depth_ingress_sequence),
            );
            let mut event = raw_event(
                "binance_depth_snapshot",
                "depth_snapshot",
                "BTCUSDT",
                None,
                &snapshot_endpoint,
                &collector_identity,
                snapshot_value,
            );
            event.recv_time_utc_ms = timestamp_received;
            let parsed = parse_depth_snapshot_raw(
                event_envelope(&event, SourceKind::BinanceDepthSnapshot),
                &event.raw_json,
                snapshot_fetch_start_utc,
                timestamp_received,
                snapshot_endpoint.clone(),
            )
            .map_err(|error| format!("schema:{error}"))?;
            let validation = parsed.validate_contract();
            if validation.verdict != crate::ValidationVerdict::Complete {
                return Err(format!(
                    "schema:invalid_snapshot_contract:{}",
                    validation.missing_fields.join(",")
                ));
            }
            let event_bytes = owned_event_bytes(&event);
            if event_bytes > MAX_TYPED_ROW_BYTES {
                return Err(format!(
                    "schema:enriched_snapshot_row_too_large:bytes={event_bytes}:limit={MAX_TYPED_ROW_BYTES}"
                ));
            }
            Ok(DepthSnapshotAttempt::Available(Box::new(
                DepthSnapshotRecord {
                    snapshot_last_update_id,
                    snapshot_utc_day: utc_day_string_from_ms(timestamp_received)
                        .unwrap_or_else(|| "unknown".to_owned()),
                    event,
                },
            )))
        }
        .await;
        let mut server_retry_after = None;
        match fetched {
            Ok(DepthSnapshotAttempt::Available(record)) => {
                return Ok(DepthSnapshotCycleOutcome::Available(record));
            }
            Ok(DepthSnapshotAttempt::Unavailable {
                reason,
                retry_after,
            }) => {
                last_unavailable_reason = reason;
                server_retry_after = retry_after;
            }
            Err(error) if error.starts_with("request:") || error.starts_with("body:") => {
                last_unavailable_reason = error;
            }
            Err(error) if depth_snapshot_schema_error(&error) => {
                return Err(io::Error::other(format!(
                    "binance_depth_snapshot_schema_fatal:{error}"
                ))
                .into());
            }
            Err(error) => {
                return Err(io::Error::other(format!(
                    "binance_depth_snapshot_integrity_fatal:{error}"
                ))
                .into());
            }
        }
        if attempt == BINANCE_DEPTH_SNAPSHOT_MAX_ATTEMPTS {
            return Ok(DepthSnapshotCycleOutcome::Unavailable {
                reason: last_unavailable_reason,
                retry_after: server_retry_after,
            });
        }
        let base_retry = Some(retry_delay(
            "binance_depth_snapshot",
            attempt,
            250,
            BINANCE_WS_RECONNECT_MAX_MS,
            snapshot_jitter_seed,
        ));
        if let Some(delay) = server_retry_after.into_iter().chain(base_retry).max() {
            sleep(delay).await;
        }
    }
    Ok(DepthSnapshotCycleOutcome::Unavailable {
        reason: last_unavailable_reason,
        retry_after: None,
    })
}

fn binance_snapshot_retry_after(
    headers: &reqwest::header::HeaderMap,
    status: reqwest::StatusCode,
) -> Option<Duration> {
    if !matches!(status.as_u16(), 418 | 429) {
        return None;
    }
    headers
        .get(reqwest::header::RETRY_AFTER)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse::<u64>().ok())
        .map(|seconds| Duration::from_secs(seconds.min(BINANCE_RETRY_AFTER_MAX_SECS)))
}

fn start_binance_depth_snapshot_cycle(
    context: &BinanceDepthUpdateContext,
    trigger_reason: impl Into<String>,
) -> DepthSnapshotFuture {
    Box::pin(fetch_binance_depth_snapshot_cycle(
        context.http_client.clone(),
        context.collector_identity.clone(),
        context.spec.snapshot_endpoint.clone(),
        trigger_reason.into(),
        context.source_sequence_epoch_id.clone(),
        context.connection_generation,
        context.ingress_sequence.clone(),
        context.snapshot_not_before.clone(),
    ))
}

#[cfg(test)]
async fn fetch_binance_depth_snapshot(
    context: &BinanceDepthUpdateContext,
    trigger_reason: &str,
) -> Result<DepthSnapshotCycleOutcome> {
    start_binance_depth_snapshot_cycle(context, trigger_reason).await
}

fn depth_snapshot_schema_error(error: &str) -> bool {
    error.starts_with("json:")
        || error.starts_with("schema:")
        || error == "empty_body"
        || error == "last_update_id_missing"
        || error == "snapshot_not_object"
}

fn utc_day_string_from_ms(utc_ms: i64) -> Option<String> {
    let dt = OffsetDateTime::from_unix_timestamp(utc_ms.div_euclid(1000)).ok()?;
    Some(format!(
        "{:04}-{:02}-{:02}",
        dt.year(),
        u8::from(dt.month()),
        dt.day()
    ))
}

fn utc_hour_string_from_ms(utc_ms: i64) -> Option<String> {
    let dt = OffsetDateTime::from_unix_timestamp(utc_ms.div_euclid(1000)).ok()?;
    Some(format!(
        "{:04}-{:02}-{:02}T{:02}",
        dt.year(),
        u8::from(dt.month()),
        dt.day(),
        dt.hour()
    ))
}

fn next_utc_hour_boundary_ms(utc_ms: i64) -> i64 {
    utc_ms
        .div_euclid(UTC_HOUR_MS)
        .saturating_mul(UTC_HOUR_MS)
        .saturating_add(UTC_HOUR_MS)
}

async fn run_binance_depth_update_ws_source_with_control(
    mut stream: WebSocketStream<MaybeTlsStream<TcpStream>>,
    context: BinanceDepthUpdateContext,
    mut control_rx: Option<&mut mpsc::Receiver<DepthSourceControl>>,
) -> Result<BinanceDepthUpdateExit> {
    let mut continuity = DepthContinuityState::AwaitingSnapshot;
    #[cfg(test)]
    let mut pending = context
        .pending_limits
        .map(|(max_rows, max_bytes)| DepthPendingBuffer::with_limits(max_rows, max_bytes))
        .unwrap_or_default();
    #[cfg(not(test))]
    let mut pending = DepthPendingBuffer::default();
    let mut snapshot_future = Some(start_binance_depth_snapshot_cycle(
        &context,
        context.initial_snapshot_trigger_reason.clone(),
    ));
    let mut snapshot_unavailable_cycles = 0_u32;
    let mut saw_business = false;
    let mut saw_transport = false;
    let mut frame_inactivity = Box::pin(sleep(depth_frame_inactivity_wait(
        context.deadline,
        context.spec.frame_inactivity_timeout,
    )));
    while !deadline_reached(context.deadline) {
        tokio::select! {
            biased;
            control = async {
                match control_rx.as_deref_mut() {
                    Some(receiver) => receiver.recv().await,
                    None => std::future::pending::<Option<DepthSourceControl>>().await,
                }
            } => {
                let Some(control) = control else {
                    return fail_depth_session_after_pending_release(
                        &context,
                        &mut pending,
                        &mut saw_business,
                        invalid_data("depth source control channel closed").into(),
                    )
                    .await;
                };
                if handle_active_depth_source_control(
                    control,
                    &context,
                    &mut snapshot_future,
                    &mut pending,
                    &mut continuity,
                    &mut saw_business,
                )
                .await?
                {
                    return Ok(BinanceDepthUpdateExit::Stopped);
                }
                reset_depth_frame_inactivity(
                    &mut frame_inactivity,
                    context.deadline,
                    context.spec.frame_inactivity_timeout,
                );
                if matches!(continuity, DepthContinuityState::AwaitingSnapshot)
                    && snapshot_future.is_none()
                {
                    snapshot_future = Some(start_binance_depth_snapshot_cycle(
                        &context,
                        "utc_day_boundary",
                    ));
                }
            }
            snapshot = async {
                match snapshot_future.as_mut() {
                    Some(future) => future.await,
                    None => std::future::pending::<Result<DepthSnapshotCycleOutcome>>().await,
                }
            } => {
                snapshot_future = None;
                let snapshot = match snapshot {
                    Ok(snapshot) => snapshot,
                    Err(error) => {
                        return fail_depth_session_after_pending_release(
                            &context,
                            &mut pending,
                            &mut saw_business,
                            error,
                        )
                        .await;
                    }
                };
                match snapshot {
                    DepthSnapshotCycleOutcome::Available(record) => {
                        snapshot_unavailable_cycles = 0;
                        let trigger = match admit_depth_snapshot_and_drain(
                            &context,
                            *record,
                            &mut pending,
                            &mut continuity,
                            &mut saw_business,
                        )
                        .await
                        {
                            Ok(trigger) => trigger,
                            Err(error) => {
                                return fail_depth_session_after_pending_release(
                                    &context,
                                    &mut pending,
                                    &mut saw_business,
                                    error,
                                )
                                .await;
                            }
                        };
                        if let Some(trigger) = trigger {
                            snapshot_future = Some(start_binance_depth_snapshot_cycle(
                                &context,
                                trigger,
                            ));
                        }
                    }
                    DepthSnapshotCycleOutcome::Unavailable {
                        reason,
                        retry_after,
                    } => {
                        neutral_release_depth_pending(
                            &context,
                            &mut pending,
                            &mut saw_business,
                        )
                        .await?;
                        continuity = DepthContinuityState::AwaitingSnapshot;
                        snapshot_unavailable_cycles = snapshot_unavailable_cycles.saturating_add(1);
                        let internal_delay = depth_snapshot_retry_delay(
                            snapshot_unavailable_cycles,
                            depth_snapshot_jitter_seed(
                                &context.source_sequence_epoch_id,
                                context.connection_generation,
                            ),
                        );
                        let delay = retry_after
                            .into_iter()
                            .chain(Some(internal_delay))
                            .max()
                            .unwrap_or(internal_delay);
                        snapshot_future = Some(start_binance_depth_snapshot_cycle_after(
                            &context,
                            format!("availability_retry:{reason}"),
                            delay,
                        ));
                    }
                }
            }
            _ = &mut frame_inactivity => {
                if deadline_reached(context.deadline) {
                    if depth_controlled_cutoff_is_active(&context) {
                        pending.discard_all();
                    } else {
                        neutral_release_depth_pending(
                            &context,
                            &mut pending,
                            &mut saw_business,
                        )
                        .await?;
                    }
                    return Ok(BinanceDepthUpdateExit::DeadlineReached);
                }
                neutral_release_depth_pending(&context, &mut pending, &mut saw_business).await?;
                return Ok(BinanceDepthUpdateExit::StreamEnded {
                    reason: "full_frame_inactivity".to_owned(),
                    saw_transport,
                });
            }
            message = stream.next() => match message {
            Some(Ok(Message::Text(text))) => {
                reset_depth_frame_inactivity(
                    &mut frame_inactivity,
                    context.deadline,
                    context.spec.frame_inactivity_timeout,
                );
                let raw_json = text.to_string();
                let recv_time_utc_ms = now_ms();
                let depth_ingress_sequence = match context.ingress_sequence.allocate() {
                    Ok(sequence) => sequence,
                    Err(error) => {
                        return fail_depth_session_after_pending_release(
                            &context,
                            &mut pending,
                            &mut saw_business,
                            invalid_data(format!("binance_depth_ingress_integrity:{error}")).into(),
                        )
                        .await;
                    }
                };
                let value = match serde_json::from_str::<Value>(&raw_json) {
                    Ok(value) => value,
                    Err(error) => {
                        return fail_depth_session_after_pending_release(
                            &context,
                            &mut pending,
                            &mut saw_business,
                            invalid_data(format!(
                                "binance_depth_update_parse_error:parse_depth_update_json:{error}"
                            ))
                            .into(),
                        )
                        .await;
                    }
                };
                let payload = binance_ws_payload(&value);
                let Some(event_type) = payload.get("e").and_then(Value::as_str) else {
                    return fail_depth_session_after_pending_release(
                        &context,
                        &mut pending,
                        &mut saw_business,
                        invalid_data("binance_depth_update_parse_error:missing_string_field:e")
                            .into(),
                    )
                    .await;
                };
                if event_type == "serverShutdown" {
                    neutral_release_depth_pending(
                        &context,
                        &mut pending,
                        &mut saw_business,
                    )
                    .await?;
                    return Ok(BinanceDepthUpdateExit::StreamEnded {
                        reason: "server_shutdown".to_owned(),
                        saw_transport,
                    });
                }
                if event_type != "depthUpdate" {
                    return fail_depth_session_after_pending_release(
                        &context,
                        &mut pending,
                        &mut saw_business,
                        invalid_data(format!(
                            "binance_depth_update_parse_error:unexpected_depth_event_type:{event_type}"
                        ))
                        .into(),
                    )
                    .await;
                }
                let base_event = RawEvent {
                    source_kind: "binance_depth_update".to_owned(),
                    source_event_type: "depth_update".to_owned(),
                    source_identifier: "BTCUSDT".to_owned(),
                    source_ts: payload
                        .get("E")
                        .and_then(Value::as_i64)
                        .map(|ts| ts.to_string()),
                    recv_time_utc_ms,
                    collector_host_id: context.collector_identity.host_id.clone(),
                    collector_region: context.collector_identity.region.clone(),
                    source_endpoint: context.spec.websocket_endpoint.clone(),
                    raw_json: raw_json.clone(),
                    collector_admission: None,
                    parquet_raw_layout_version: 1,
                    parquet_raw_source_kind: "binance_depth_update".to_owned(),
                };
                let parsed = match parse_depth_update_raw(
                    event_envelope(&base_event, SourceKind::BinanceDepthUpdate),
                    &raw_json,
                ) {
                    Ok(parsed) => parsed,
                    Err(error) => {
                        return fail_depth_session_after_pending_release(
                            &context,
                            &mut pending,
                            &mut saw_business,
                            invalid_data(format!("binance_depth_update_parse_error:{error}"))
                                .into(),
                        )
                        .await;
                    }
                };
                let validation = parsed.validate_contract();
                if validation.verdict != crate::ValidationVerdict::Complete {
                    return fail_depth_session_after_pending_release(
                        &context,
                        &mut pending,
                        &mut saw_business,
                        invalid_data(format!(
                            "binance_depth_update_contract_error:{}",
                            validation.missing_fields.join(",")
                        ))
                        .into(),
                    )
                    .await;
                }
                saw_transport = true;
                let recv_utc_day = utc_day_string_from_ms(recv_time_utc_ms)
                    .unwrap_or_else(|| "unknown".to_owned());
                if matches!(
                    &continuity,
                    DepthContinuityState::Ready { snapshot_utc_day, .. }
                        if snapshot_utc_day != &recv_utc_day
                ) {
                    continuity = DepthContinuityState::AwaitingSnapshot;
                    if snapshot_future.is_none() {
                        snapshot_future = Some(start_binance_depth_snapshot_cycle(
                            &context,
                            "utc_day_boundary",
                        ));
                    }
                }
                match continuity {
                    DepthContinuityState::AwaitingSnapshot => {
                        let owned_bytes = owned_event_bytes(&base_event);
                        let buffered = BufferedDepthUpdate {
                            event: base_event,
                            depth_ingress_sequence,
                            owned_bytes,
                        };
                        if pending.would_exceed(owned_bytes) {
                            neutral_release_depth_pending(
                                &context,
                                &mut pending,
                                &mut saw_business,
                            )
                            .await?;
                            neutral_release_one_depth_update(
                                &context,
                                buffered,
                                &mut saw_business,
                            )
                            .await?;
                            continuity = DepthContinuityState::AwaitingSnapshot;
                            if snapshot_future.is_none() {
                                snapshot_future = Some(start_binance_depth_snapshot_cycle_after(
                                    &context,
                                    "pending_buffer_capacity",
                                    depth_snapshot_retry_delay(
                                        1,
                                        depth_snapshot_jitter_seed(
                                            &context.source_sequence_epoch_id,
                                            context.connection_generation,
                                        ),
                                    ),
                                ));
                            }
                        } else {
                            pending.push(buffered)?;
                        }
                    }
                    DepthContinuityState::Ready { .. } => {
                        let assessment = admit_depth_update(
                            &context,
                            base_event,
                            depth_ingress_sequence,
                            depth_continuity_coordinates(&continuity)?,
                        )
                        .await?;
                        if let Some(assessment) = assessment {
                            saw_business = true;
                            if let Some(trigger) =
                                apply_depth_assessment(&mut continuity, &assessment)?
                            {
                                snapshot_future = Some(start_binance_depth_snapshot_cycle(
                                    &context,
                                    trigger,
                                ));
                            }
                        }
                    }
                }
            }
            Some(Ok(Message::Ping(payload))) => {
                reset_depth_frame_inactivity(
                    &mut frame_inactivity,
                    context.deadline,
                    context.spec.frame_inactivity_timeout,
                );
                if !matches!(timeout(
                    Duration::from_secs(WS_WRITE_TIMEOUT_SECS),
                    stream.send(Message::Pong(payload)),
                )
                .await, Ok(Ok(())))
                {
                    neutral_release_depth_pending(
                        &context,
                        &mut pending,
                        &mut saw_business,
                    )
                    .await?;
                    return Ok(BinanceDepthUpdateExit::StreamEnded {
                        reason: "pong_write_failed".to_owned(),
                        saw_transport,
                    });
                }
                saw_transport = true;
            }
            Some(Ok(Message::Close(frame))) => {
                reset_depth_frame_inactivity(
                    &mut frame_inactivity,
                    context.deadline,
                    context.spec.frame_inactivity_timeout,
                );
                neutral_release_depth_pending(&context, &mut pending, &mut saw_business).await?;
                return Ok(BinanceDepthUpdateExit::StreamEnded {
                    reason: format!("ws_closed:{frame:?}"),
                    saw_transport,
                });
            }
            Some(Ok(Message::Pong(_))) => {
                reset_depth_frame_inactivity(
                    &mut frame_inactivity,
                    context.deadline,
                    context.spec.frame_inactivity_timeout,
                );
                saw_transport = true;
            }
            Some(Ok(Message::Binary(_))) => {
                reset_depth_frame_inactivity(
                    &mut frame_inactivity,
                    context.deadline,
                    context.spec.frame_inactivity_timeout,
                );
                return fail_depth_session_after_pending_release(
                    &context,
                    &mut pending,
                    &mut saw_business,
                    invalid_data("binance_depth_update_binary_payload_integrity_fatal").into(),
                )
                .await;
            }
            Some(Ok(_)) => {
                reset_depth_frame_inactivity(
                    &mut frame_inactivity,
                    context.deadline,
                    context.spec.frame_inactivity_timeout,
                );
            }
            Some(Err(err)) => {
                neutral_release_depth_pending(&context, &mut pending, &mut saw_business).await?;
                return Ok(BinanceDepthUpdateExit::StreamEnded {
                    reason: format!("ws_error:{err}"),
                    saw_transport,
                });
            }
            None => {
                neutral_release_depth_pending(&context, &mut pending, &mut saw_business).await?;
                return Ok(BinanceDepthUpdateExit::StreamEnded {
                    reason: "ws_ended".to_owned(),
                    saw_transport,
                });
            }
        },
        }
    }
    if depth_controlled_cutoff_is_active(&context) {
        pending.discard_all();
    } else {
        neutral_release_depth_pending(&context, &mut pending, &mut saw_business).await?;
    }
    Ok(BinanceDepthUpdateExit::DeadlineReached)
}

fn depth_frame_inactivity_wait(deadline: Option<Instant>, frame_window: Duration) -> Duration {
    deadline_remaining(deadline)
        .map(|remaining| remaining.min(frame_window))
        .unwrap_or(frame_window)
}

fn reset_depth_frame_inactivity(
    timer: &mut Pin<Box<tokio::time::Sleep>>,
    deadline: Option<Instant>,
    frame_window: Duration,
) {
    timer
        .as_mut()
        .reset(tokio::time::Instant::now() + depth_frame_inactivity_wait(deadline, frame_window));
}

fn depth_snapshot_retry_delay(cycle: u32, jitter_seed: u64) -> Duration {
    retry_delay(
        "binance_depth_snapshot",
        cycle.min(32),
        BINANCE_WS_RECONNECT_BASE_MS,
        BINANCE_WS_RECONNECT_MAX_MS,
        jitter_seed,
    )
}

fn depth_snapshot_jitter_seed(source_sequence_epoch_id: &str, connection_generation: u64) -> u64 {
    let mut hasher = Sha256::new();
    hasher.update(b"binance_depth_snapshot_jitter_v1\0");
    hasher.update(source_sequence_epoch_id.as_bytes());
    hasher.update(connection_generation.to_le_bytes());
    let digest = hasher.finalize();
    let mut bytes = [0_u8; 8];
    bytes.copy_from_slice(&digest[..8]);
    u64::from_le_bytes(bytes)
}

fn start_binance_depth_snapshot_cycle_after(
    context: &BinanceDepthUpdateContext,
    trigger_reason: impl Into<String>,
    delay: Duration,
) -> DepthSnapshotFuture {
    let future = start_binance_depth_snapshot_cycle(context, trigger_reason);
    Box::pin(async move {
        if !delay.is_zero() {
            sleep(delay).await;
        }
        future.await
    })
}

fn depth_continuity_coordinates(
    continuity: &DepthContinuityState,
) -> Result<(Option<u64>, Option<u64>)> {
    match continuity {
        DepthContinuityState::AwaitingSnapshot => Ok((None, None)),
        DepthContinuityState::Ready {
            snapshot_last_update_id,
            local_u,
            ..
        } => Ok((Some(*snapshot_last_update_id), *local_u)),
    }
}

fn depth_verdict_label(verdict: DepthUpdateVerdict) -> &'static str {
    match verdict {
        DepthUpdateVerdict::Applied => BINANCE_DEPTH_VERDICT_APPLIED,
        DepthUpdateVerdict::NotAppliedStaleDuplicate => {
            BINANCE_DEPTH_VERDICT_NOT_APPLIED_STALE_DUPLICATE
        }
        DepthUpdateVerdict::NotAppliedConfirmedHole => {
            BINANCE_DEPTH_VERDICT_NOT_APPLIED_CONFIRMED_HOLE
        }
        DepthUpdateVerdict::NotAppliedSnapshotUnavailable => {
            BINANCE_DEPTH_VERDICT_NOT_APPLIED_SNAPSHOT_UNAVAILABLE
        }
    }
}

async fn admit_depth_update(
    context: &BinanceDepthUpdateContext,
    mut event: RawEvent,
    depth_ingress_sequence: u64,
    (snapshot_last_update_id, local_u_before): (Option<u64>, Option<u64>),
) -> Result<Option<DepthUpdateAssessment>> {
    let parsed = parse_depth_update_raw(
        event_envelope(&event, SourceKind::BinanceDepthUpdate),
        &event.raw_json,
    )
    .map_err(|error| invalid_data(format!("binance_depth_update_parse_error:{error}")))?;
    let assessment = assess_depth_update(snapshot_last_update_id, local_u_before, &parsed)
        .map_err(invalid_data)?;
    let mut enriched = serde_json::from_str::<Value>(&event.raw_json)?;
    let object = enriched
        .as_object_mut()
        .ok_or_else(|| invalid_data("Binance depth update payload is not an object"))?;
    object.insert(
        "source_sequence_epoch_id".to_owned(),
        json!(context.source_sequence_epoch_id),
    );
    object.insert(
        "connection_generation".to_owned(),
        json!(context.connection_generation),
    );
    object.insert(
        "depth_ingress_sequence".to_owned(),
        json!(depth_ingress_sequence),
    );
    object.insert(
        "snapshot_last_update_id".to_owned(),
        json!(assessment.snapshot_last_update_id),
    );
    object.insert(
        "local_u_before".to_owned(),
        json!(assessment.local_u_before),
    );
    object.insert(
        "stitch_verdict".to_owned(),
        json!(depth_verdict_label(assessment.verdict)),
    );
    object.insert(
        "stitch_evidence".to_owned(),
        json!(assessment.stitch_evidence),
    );
    object.insert("local_u_after".to_owned(), json!(assessment.local_u_after));
    object.insert("stitch_gap_reason".to_owned(), json!(assessment.gap_reason));
    event.raw_json = enriched.to_string();
    let admission_gaps = match assessment.verdict {
        DepthUpdateVerdict::NotAppliedConfirmedHole => vec![format!(
            "binance_depth_update_stitch_gap:{}",
            assessment
                .gap_reason
                .as_deref()
                .ok_or_else(|| invalid_data("confirmed depth hole omitted gap reason"))?
        )],
        _ => Vec::new(),
    };
    if !send_event_with_reservation_outcome(
        &context.sink,
        context.run_started,
        event,
        None,
        admission_gaps,
    )
    .await?
    {
        return Ok(None);
    }
    Ok(Some(assessment))
}

fn apply_depth_assessment(
    continuity: &mut DepthContinuityState,
    assessment: &DepthUpdateAssessment,
) -> Result<Option<String>> {
    match assessment.verdict {
        DepthUpdateVerdict::Applied => {
            let next_local_u = assessment
                .local_u_after
                .ok_or_else(|| invalid_data("applied depth update omitted local_u_after"))?;
            let DepthContinuityState::Ready { local_u, .. } = continuity else {
                return Err(invalid_data("applied depth update without ready snapshot").into());
            };
            *local_u = Some(next_local_u);
            Ok(None)
        }
        DepthUpdateVerdict::NotAppliedStaleDuplicate => Ok(None),
        DepthUpdateVerdict::NotAppliedConfirmedHole => {
            let reason = assessment
                .gap_reason
                .as_deref()
                .ok_or_else(|| invalid_data("confirmed depth hole omitted gap reason"))?;
            *continuity = DepthContinuityState::AwaitingSnapshot;
            Ok(Some(format!("stitch_gap:{reason}")))
        }
        DepthUpdateVerdict::NotAppliedSnapshotUnavailable => {
            *continuity = DepthContinuityState::AwaitingSnapshot;
            Ok(None)
        }
    }
}

async fn neutral_release_one_depth_update(
    context: &BinanceDepthUpdateContext,
    update: BufferedDepthUpdate,
    saw_business: &mut bool,
) -> Result<()> {
    let Some(assessment) = admit_depth_update(
        context,
        update.event,
        update.depth_ingress_sequence,
        (None, None),
    )
    .await?
    else {
        return Ok(());
    };
    if assessment.verdict != DepthUpdateVerdict::NotAppliedSnapshotUnavailable {
        return Err(invalid_data("neutral depth release produced a non-neutral verdict").into());
    }
    *saw_business = true;
    Ok(())
}

async fn neutral_release_depth_pending(
    context: &BinanceDepthUpdateContext,
    pending: &mut DepthPendingBuffer,
    saw_business: &mut bool,
) -> Result<()> {
    while let Some(update) = pending.pop_front()? {
        neutral_release_one_depth_update(context, update, saw_business).await?;
    }
    Ok(())
}

async fn fail_depth_session_after_pending_release(
    context: &BinanceDepthUpdateContext,
    pending: &mut DepthPendingBuffer,
    saw_business: &mut bool,
    terminal_error: Box<dyn Error + Send + Sync>,
) -> Result<BinanceDepthUpdateExit> {
    if let Err(release_error) = neutral_release_depth_pending(context, pending, saw_business).await
    {
        return Err(io::Error::other(format!(
            "binance_depth_terminal_pending_release_failed:terminal={terminal_error}:release={release_error}"
        ))
        .into());
    }
    Err(terminal_error)
}

async fn drain_depth_pending(
    context: &BinanceDepthUpdateContext,
    pending: &mut DepthPendingBuffer,
    continuity: &mut DepthContinuityState,
    saw_business: &mut bool,
) -> Result<Option<String>> {
    while matches!(continuity, DepthContinuityState::Ready { .. }) {
        let Some(update) = pending.pop_front()? else {
            break;
        };
        let Some(assessment) = admit_depth_update(
            context,
            update.event,
            update.depth_ingress_sequence,
            depth_continuity_coordinates(continuity)?,
        )
        .await?
        else {
            pending.discard_all();
            break;
        };
        *saw_business = true;
        if let Some(trigger) = apply_depth_assessment(continuity, &assessment)? {
            return Ok(Some(trigger));
        }
    }
    Ok(None)
}

async fn admit_depth_snapshot_and_drain(
    context: &BinanceDepthUpdateContext,
    record: DepthSnapshotRecord,
    pending: &mut DepthPendingBuffer,
    continuity: &mut DepthContinuityState,
    saw_business: &mut bool,
) -> Result<Option<String>> {
    if !send_event_with_outcome(&context.sink, context.run_started, record.event).await? {
        pending.discard_all();
        *continuity = DepthContinuityState::AwaitingSnapshot;
        return Ok(None);
    }
    *continuity = DepthContinuityState::Ready {
        snapshot_last_update_id: record.snapshot_last_update_id,
        local_u: None,
        snapshot_utc_day: record.snapshot_utc_day,
    };
    drain_depth_pending(context, pending, continuity, saw_business).await
}

async fn handle_active_depth_source_control(
    control: DepthSourceControl,
    context: &BinanceDepthUpdateContext,
    snapshot_future: &mut Option<DepthSnapshotFuture>,
    pending: &mut DepthPendingBuffer,
    continuity: &mut DepthContinuityState,
    saw_business: &mut bool,
) -> Result<bool> {
    let DepthSourceControl::Fence {
        kind,
        stop_after_fence,
        resume_after_barrier,
        reply,
    } = control;
    match kind {
        DepthFenceKind::HourFinalize => {
            if matches!(continuity, DepthContinuityState::Ready { .. }) && !pending.is_empty() {
                return Err(invalid_data(
                    "ready Binance depth continuity retained a pending update at hour fence",
                )
                .into());
            }
        }
        DepthFenceKind::ResetContinuity => {
            drop(snapshot_future.take());
            if depth_controlled_cutoff_is_active(context) {
                pending.discard_all();
            } else {
                neutral_release_depth_pending(context, pending, saw_business).await?;
            }
            *continuity = DepthContinuityState::AwaitingSnapshot;
        }
    }
    let _ = reply.send(Ok(()));
    if let Some(resume) = resume_after_barrier
        && resume.await.is_err()
    {
        drop(snapshot_future.take());
        neutral_release_depth_pending(context, pending, saw_business).await?;
        *continuity = DepthContinuityState::AwaitingSnapshot;
        return Err(invalid_data("depth barrier owner dropped source resume signal").into());
    }
    Ok(stop_after_fence)
}

fn depth_controlled_cutoff_is_active(context: &BinanceDepthUpdateContext) -> bool {
    context
        .sink
        .source_queue_backpressure
        .raw_day_gate()
        .is_some_and(|gate| gate.unadmitted_runtime_cutoff_is_active())
}

async fn handle_depth_source_control(control: DepthSourceControl) -> Result<bool> {
    let DepthSourceControl::Fence {
        kind: _,
        stop_after_fence,
        resume_after_barrier,
        reply,
    } = control;
    let _ = reply.send(Ok(()));
    if let Some(resume) = resume_after_barrier {
        resume
            .await
            .map_err(|_| invalid_data("depth barrier owner dropped source resume signal"))?;
    }
    Ok(stop_after_fence)
}

fn finalized_parquet_files(source_dir: &Path) -> Result<Vec<PathBuf>> {
    let entries = match fs::read_dir(source_dir) {
        Ok(entries) => entries,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(error) => return Err(error.into()),
    };
    let mut paths = Vec::new();
    for entry in entries {
        let entry = entry?;
        if !entry.file_type()?.is_file() {
            continue;
        }
        let file_name = entry.file_name();
        let file_name = file_name.to_string_lossy();
        if file_name.ends_with(".parquet")
            && !file_name.ends_with("-running.parquet")
            && !file_name.ends_with("-digesting.parquet")
        {
            paths.push(entry.path());
        }
    }
    paths.sort_by_key(|path| finalized_parquet_order_key(path));
    Ok(paths)
}

fn finalized_parquet_order_key(path: &Path) -> (String, u32) {
    let stem = path
        .file_stem()
        .and_then(|stem| stem.to_str())
        .unwrap_or_default();
    stem.rsplit_once("-part-").map_or_else(
        || (stem.to_owned(), 0),
        |(base, part)| (base.to_owned(), part.parse::<u32>().unwrap_or(u32::MAX)),
    )
}

fn all_finalized_source_parquet_paths(
    dataset_root: &Path,
    source_kind: &str,
) -> Result<Vec<PathBuf>> {
    let typed_raw = dataset_root.join("training").join("typed_raw");
    let entries = match fs::read_dir(&typed_raw) {
        Ok(entries) => entries,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(error) => return Err(error.into()),
    };
    let mut paths = Vec::new();
    for entry in entries {
        let entry = entry?;
        if !entry.file_type()?.is_dir()
            || !entry.file_name().to_string_lossy().starts_with("utc_day=")
        {
            continue;
        }
        paths.extend(finalized_parquet_files(
            &entry.path().join(format!("source_kind={source_kind}")),
        )?);
    }
    paths.sort_by_key(|path| {
        (
            path.parent()
                .map(|parent| parent.to_string_lossy().into_owned())
                .unwrap_or_default(),
            finalized_parquet_order_key(path),
        )
    });
    Ok(paths)
}

struct BinanceAggTradeRecovery {
    websocket_dedupe: BinanceRecentIdWindow,
}

struct StableStartupRecovery {
    utc_day: String,
    initial_next_boundary_ms: i64,
    binance_aggtrade: BinanceAggTradeRecovery,
    current_manifest: Value,
}

fn reconcile_stable_startup_recovery<F>(
    dataset_root: &Path,
    identity: &DailyManifestIdentity,
    mut clock_ms: F,
) -> Result<StableStartupRecovery>
where
    F: FnMut() -> i64,
{
    loop {
        let recovery_started_ms = clock_ms();
        let recovery_day = utc_day_string_from_ms(recovery_started_ms)
            .ok_or_else(|| invalid_data("current UTC day unavailable for Binance recovery"))?;
        let binance_aggtrade =
            restore_binance_aggtrade_recovery(dataset_root, &recovery_day, identity)?;
        let current_manifest = reconcile_open_day_manifest(
            &typed_raw_root(dataset_root).join(format!("utc_day={recovery_day}")),
            &recovery_day,
            identity,
        )?;
        let confirmed_ms = clock_ms();
        let confirmed_day = utc_day_string_from_ms(confirmed_ms)
            .ok_or_else(|| invalid_data("UTC day unavailable after startup recovery"))?;
        if confirmed_day < recovery_day {
            return Err(invalid_data(format!(
                "UTC day moved backward during startup recovery: started={recovery_day} confirmed={confirmed_day}"
            ))
            .into());
        }
        if confirmed_day == recovery_day {
            return Ok(StableStartupRecovery {
                utc_day: recovery_day,
                initial_next_boundary_ms: confirmed_ms
                    .div_euclid(UTC_DAY_MS)
                    .saturating_add(1)
                    .saturating_mul(UTC_DAY_MS),
                binance_aggtrade,
                current_manifest,
            });
        }
    }
}

fn restore_binance_aggtrade_recovery(
    dataset_root: &Path,
    current_day: &str,
    current_identity: &DailyManifestIdentity,
) -> Result<BinanceAggTradeRecovery> {
    let days = utc_day_directories(dataset_root)?;
    if let Some((future_day, _)) = days.iter().find(|(day, _)| day.as_str() > current_day) {
        return Err(invalid_data(format!(
            "future UTC day cannot participate in recovery: {future_day}"
        ))
        .into());
    }
    for (day, day_dir) in days.iter().filter(|(day, _)| day.as_str() < current_day) {
        let Some(mut manifest) = load_day_manifest(day_dir)? else {
            if day_has_finalized_parquet(day_dir)? {
                return Err(io::Error::other(format!(
                    "prior UTC day has Parquet but no daily manifest: {day}"
                ))
                .into());
            }
            continue;
        };
        validate_manifest_day(&manifest, day)?;
        let state = manifest_state(&manifest)?;
        validate_manifest_recovery_files(day_dir, &manifest, state == "open")?;
        if state == "open" {
            if manifest_collection_day_coverage(&manifest)?.is_some() {
                add_manifest_operational_counters(
                    day_dir,
                    &mut manifest,
                    &required_source_counter_defaults(),
                )?;
            }
            close_reconciled_day_manifest(day_dir, &mut manifest)?;
        }
    }

    if let Some((day, day_dir)) = days.iter().find(|(day, _)| day == current_day) {
        if let Some(manifest) = load_day_manifest(day_dir)? {
            validate_manifest_day(&manifest, day)?;
            if manifest_state(&manifest)? == "closed" {
                return Err(io::Error::other(format!(
                    "current UTC day manifest is already closed: {day}"
                ))
                .into());
            }
            validate_manifest_recovery_files(day_dir, &manifest, true)?;
        } else {
            validate_unmanifested_recovery_files(day_dir, current_identity)?;
        }
    }

    Ok(BinanceAggTradeRecovery {
        websocket_dedupe: restore_binance_transport_dedupe(dataset_root)?,
    })
}

fn binance_aggtrade_restore_row_is_trade(
    record_kinds: Option<&StringArray>,
    ids: &UInt64Array,
    row: usize,
    path: &Path,
) -> Result<bool> {
    let Some(record_kinds) = record_kinds else {
        if ids.is_null(row) {
            return Err(io::Error::other(format!(
                "legacy Binance aggTrade ID missing in {}",
                path.display()
            ))
            .into());
        }
        return Ok(true);
    };
    if record_kinds.is_null(row) {
        return Err(io::Error::other(format!(
            "Binance aggTrade v6 record kind missing in {}",
            path.display()
        ))
        .into());
    }
    match record_kinds.value(row) {
        "trade" => {
            if ids.is_null(row) {
                return Err(io::Error::other(format!(
                    "Binance aggTrade v6 trade ID missing in {}",
                    path.display()
                ))
                .into());
            }
            Ok(true)
        }
        "invalid_input" => {
            if !ids.is_null(row) {
                return Err(io::Error::other(format!(
                    "Binance aggTrade v6 invalid input has a trade ID in {}",
                    path.display()
                ))
                .into());
            }
            Ok(false)
        }
        kind => Err(io::Error::other(format!(
            "unknown Binance aggTrade v6 record kind {kind:?} in {}",
            path.display()
        ))
        .into()),
    }
}

fn restore_binance_transport_dedupe(dataset_root: &Path) -> Result<BinanceRecentIdWindow> {
    restore_binance_transport_dedupe_with_limit(dataset_root, BINANCE_AGGTRADE_RECOVERY_IDS)
}

fn restore_binance_transport_dedupe_with_limit(
    dataset_root: &Path,
    recovery_id_limit: usize,
) -> Result<BinanceRecentIdWindow> {
    if recovery_id_limit == 0 {
        return Err(invalid_data("Binance aggTrade recovery ID limit is zero").into());
    }
    let mut websocket = BinanceRecentIdWindow::with_limit(recovery_id_limit);
    let mut recovery_ids = BTreeSet::new();
    let mut paths = all_finalized_source_parquet_paths(dataset_root, "binance_aggtrade")?;
    paths.reverse();
    'files: for path in paths {
        let builder = ParquetRecordBatchReaderBuilder::try_new(File::open(&path)?)?;
        if builder.schema().index_of("aggregate_trade_id").is_err()
            || builder
                .schema()
                .index_of("source_native_payload_json")
                .is_err()
        {
            continue;
        }
        if builder.metadata().file_metadata().num_rows() == 0 {
            continue;
        }
        let has_record_kind = builder.schema().index_of("record_kind").is_ok();
        let projection_columns = if has_record_kind {
            vec![
                "aggregate_trade_id",
                "source_native_payload_json",
                "record_kind",
            ]
        } else {
            vec!["aggregate_trade_id", "source_native_payload_json"]
        };
        let projection = ProjectionMask::columns(builder.parquet_schema(), projection_columns);
        for row_group in (0..builder.metadata().num_row_groups()).rev() {
            let row_group_builder = ParquetRecordBatchReaderBuilder::try_new(File::open(&path)?)?;
            let mut reader = row_group_builder
                .with_projection(projection.clone())
                .with_row_groups(vec![row_group])
                .with_batch_size(16)
                .build()?;
            for batch in &mut reader {
                let batch = batch?;
                let id_index = batch.schema().index_of("aggregate_trade_id")?;
                let payload_index = batch.schema().index_of("source_native_payload_json")?;
                let ids = batch
                    .column(id_index)
                    .as_any()
                    .downcast_ref::<UInt64Array>()
                    .ok_or_else(|| io::Error::other("Binance restore ID is not UInt64"))?;
                let payloads = batch
                    .column(payload_index)
                    .as_any()
                    .downcast_ref::<StringArray>()
                    .ok_or_else(|| io::Error::other("Binance restore payload is not UTF8"))?;
                let record_kinds = if has_record_kind {
                    Some(
                        batch
                            .column(batch.schema().index_of("record_kind")?)
                            .as_any()
                            .downcast_ref::<StringArray>()
                            .ok_or_else(|| {
                                io::Error::other("Binance restore record kind is not UTF8")
                            })?,
                    )
                } else {
                    None
                };
                for row in 0..batch.num_rows() {
                    if payloads.is_null(row) {
                        return Err(io::Error::other(format!(
                            "Binance restore payload missing in {}",
                            path.display()
                        ))
                        .into());
                    }
                    if !binance_aggtrade_restore_row_is_trade(record_kinds, ids, row, &path)? {
                        continue;
                    }
                    let persisted_sources = payloads.value(row);
                    if persisted_sources.len() > MAX_TYPED_ROW_BYTES {
                        return Err(io::Error::other(format!(
                            "operator_intervention_required:Binance restore payload exceeds {MAX_TYPED_ROW_BYTES} bytes in {}",
                            path.display()
                        ))
                        .into());
                    }
                    let parsed = serde_json::from_str::<Value>(persisted_sources)?;
                    let websocket_payload = match parsed.get("websocket") {
                        Some(Value::String(payload)) => payload.as_str(),
                        Some(Value::Null) => continue,
                        Some(_) => {
                            return Err(io::Error::other(format!(
                                "Binance restore websocket payload is not UTF8 in {}",
                                path.display()
                            ))
                            .into());
                        }
                        None => persisted_sources,
                    };
                    let native_id = ids.value(row);
                    recovery_ids.insert(native_id);
                    while recovery_ids.len() > recovery_id_limit {
                        let Some(evicted) = recovery_ids.pop_first() else {
                            break;
                        };
                        websocket.remove(evicted);
                    }
                    if !recovery_ids.contains(&native_id) {
                        continue;
                    }
                    let _ = websocket.observe(native_id, websocket_payload.as_bytes());
                }
            }
            if recovery_ids.len() == recovery_id_limit {
                break 'files;
            }
        }
    }
    Ok(websocket)
}

async fn run_binance_ws_source(
    recovery: BinanceAggTradeRecovery,
    spec: BinanceWsSpec,
    sink: SourceEventSink,
    collector_identity: CollectorIdentity,
    deadline: Option<Instant>,
    run_started: Instant,
    mut control_rx: mpsc::Receiver<AggTradeSourceControl>,
) -> Result<()> {
    let source_sequence_epoch_id = aggtrade_source_sequence_epoch_id(&collector_identity)?;
    let ingress_sequences = BinanceAggTradeIngressSequenceAllocator::default();
    let mut websocket_dedupe = recovery.websocket_dedupe;
    let mut connection_generation = 0_u64;
    let mut recovery = SourceRecoverySupervisor::new(
        "binance_aggtrade",
        u64::try_from(now_ms()).unwrap_or_default(),
    );
    #[cfg(test)]
    recovery.set_wait_override(spec.recovery_wait_override);

    'connections: while !deadline_reached(deadline) {
        while let Ok(control) = control_rx.try_recv() {
            if handle_aggtrade_source_control(control).await? {
                return Ok(());
            }
        }

        let connect_timeout = deadline_remaining(deadline)
            .map(|remaining| remaining.min(Duration::from_secs(WS_CONNECT_TIMEOUT_SECS)))
            .unwrap_or_else(|| Duration::from_secs(WS_CONNECT_TIMEOUT_SECS));
        if connect_timeout.is_zero() {
            break;
        }
        let websocket_config = WebSocketConfig::default()
            .max_message_size(Some(BINANCE_AGGTRADE_INVALID_INPUT_MAX_BYTES))
            .max_frame_size(Some(BINANCE_AGGTRADE_INVALID_INPUT_MAX_BYTES));
        let (mut stream, _) = match timeout(
            connect_timeout,
            connect_async_with_config(&spec.url, Some(websocket_config), false),
        )
        .await
        {
            Ok(Ok(connected)) => connected,
            Ok(Err(_)) => {
                if !wait_for_source_recovery(&mut recovery, &sink, deadline).await {
                    break;
                }
                continue;
            }
            Err(_) => {
                if deadline_reached(deadline)
                    || !wait_for_source_recovery(&mut recovery, &sink, deadline).await
                {
                    break;
                }
                continue;
            }
        };
        connection_generation = connection_generation.checked_add(1).ok_or_else(|| {
            sink.source_queue_backpressure
                .record_operational_drop(&spec.source_kind, now_ms(), 1);
            record_gap(
                &sink.gaps,
                "binance_aggtrade_connection_generation_terminal:overflow".to_owned(),
            );
            invalid_data("binance aggTrade connection generation overflow")
        })?;
        let current_connection_generation = connection_generation;

        let frame_inactivity_window = Duration::from_secs(spec.frame_inactivity_timeout_secs);
        let mut frame_inactivity_deadline = Instant::now() + frame_inactivity_window;
        let _reconnect_reason = loop {
            if deadline_reached(deadline) {
                break 'connections;
            }
            let frame_inactivity_remaining =
                frame_inactivity_deadline.saturating_duration_since(Instant::now());
            if frame_inactivity_remaining.is_zero() {
                break "frame_inactivity_timeout".to_owned();
            }
            let read_timeout = deadline_remaining(deadline)
                .map(|remaining| remaining.min(frame_inactivity_remaining))
                .unwrap_or(frame_inactivity_remaining);
            let input = tokio::select! {
                biased;
                control = control_rx.recv() => {
                    match control {
                        Some(control) => {
                            if handle_aggtrade_source_control(control).await? {
                                return Ok(());
                            }
                            frame_inactivity_deadline = Instant::now() + frame_inactivity_window;
                            continue;
                        }
                        None => {
                            return Err(invalid_data(
                                "aggTrade source control channel closed",
                            ).into());
                        }
                    }
                }
                message = timeout(read_timeout, stream.next()) => message,
            };

            if matches!(&input, Ok(Some(Ok(_)))) {
                frame_inactivity_deadline = Instant::now() + frame_inactivity_window;
                recovery.record_business_recovery();
                sink.source_queue_backpressure
                    .set_recovery_active(&spec.source_kind, false);
            }

            match input {
                Ok(Some(Ok(Message::Text(text)))) => {
                    let recv_time_utc_ms = now_ms();
                    let ingress_coordinate = allocate_aggtrade_websocket_ingress(
                        &ingress_sequences,
                        &sink,
                        recv_time_utc_ms,
                    )?;
                    let websocket_staging_reservation = sink
                        .inflight_budget
                        .acquire(
                            1,
                            aggtrade_websocket_staging_bytes(text.len(), true)?,
                            BUFFER_ACQUIRE_TIMEOUT,
                        )
                        .await?;
                    let raw_bytes = text.as_bytes().to_vec();
                    let value = match serde_json::from_str::<Value>(text.as_str()) {
                        Ok(value) => value,
                        Err(error) => {
                            drop(text);
                            emit_aggtrade_websocket_invalid(
                                raw_bytes,
                                recv_time_utc_ms,
                                ingress_coordinate,
                                BinanceAggTradeInvalidReason::InvalidJson,
                                error.to_string(),
                                &sink,
                                &collector_identity,
                                &spec,
                                &source_sequence_epoch_id,
                                current_connection_generation,
                                run_started,
                                websocket_staging_reservation,
                            )
                            .await?;
                            continue;
                        }
                    };
                    drop(text);
                    let (payload, stream_name) = match (value.get("stream"), value.get("data")) {
                        (None, None) => (&value, "btcusdt@aggTrade"),
                        (Some(Value::String(stream_name)), Some(payload)) => {
                            (payload, stream_name.as_str())
                        }
                        _ => {
                            drop(value);
                            emit_aggtrade_websocket_invalid(
                                raw_bytes,
                                recv_time_utc_ms,
                                ingress_coordinate,
                                BinanceAggTradeInvalidReason::InvalidPayload,
                                "combined_stream_requires_string_stream_and_data",
                                &sink,
                                &collector_identity,
                                &spec,
                                &source_sequence_epoch_id,
                                current_connection_generation,
                                run_started,
                                websocket_staging_reservation,
                            )
                            .await?;
                            continue;
                        }
                    };
                    let Some(event_type) = payload.get("e").and_then(Value::as_str) else {
                        drop(value);
                        emit_aggtrade_websocket_invalid(
                            raw_bytes,
                            recv_time_utc_ms,
                            ingress_coordinate,
                            BinanceAggTradeInvalidReason::InvalidPayload,
                            "missing_event_type",
                            &sink,
                            &collector_identity,
                            &spec,
                            &source_sequence_epoch_id,
                            current_connection_generation,
                            run_started,
                            websocket_staging_reservation,
                        )
                        .await?;
                        continue;
                    };
                    let event_type = event_type.to_owned();
                    if event_type == "serverShutdown" {
                        break "server_shutdown".to_owned();
                    }
                    if event_type != spec.default_event_type {
                        drop(value);
                        emit_aggtrade_websocket_invalid(
                            raw_bytes,
                            recv_time_utc_ms,
                            ingress_coordinate,
                            BinanceAggTradeInvalidReason::InvalidPayload,
                            format!("unexpected_event_type:{event_type}"),
                            &sink,
                            &collector_identity,
                            &spec,
                            &source_sequence_epoch_id,
                            current_connection_generation,
                            run_started,
                            websocket_staging_reservation,
                        )
                        .await?;
                        continue;
                    }
                    let websocket = match BinanceWsAggTrade::from_wire(
                        payload,
                        stream_name,
                        recv_time_utc_ms,
                        ingress_coordinate.clone(),
                    ) {
                        Ok(websocket) => websocket,
                        Err(error) => {
                            drop(value);
                            emit_aggtrade_websocket_invalid(
                                raw_bytes,
                                recv_time_utc_ms,
                                ingress_coordinate,
                                BinanceAggTradeInvalidReason::InvalidPayload,
                                error,
                                &sink,
                                &collector_identity,
                                &spec,
                                &source_sequence_epoch_id,
                                current_connection_generation,
                                run_started,
                                websocket_staging_reservation,
                            )
                            .await?;
                            continue;
                        }
                    };
                    drop(value);
                    drop(raw_bytes);
                    let native_id = websocket.shared.aggregate_trade_id;
                    let payload_conflict = match websocket_dedupe
                        .observe(native_id, websocket.source_native_payload_json.as_bytes())
                    {
                        BinanceIdDecision::Duplicate => {
                            sink.source_queue_backpressure.record_structural_dedupe(
                                &spec.source_kind,
                                websocket.timestamp_received,
                                1,
                            );
                            continue;
                        }
                        BinanceIdDecision::Conflict => true,
                        BinanceIdDecision::OutsideWindow | BinanceIdDecision::Unique => false,
                    };
                    let output = BinanceAggTradeOutput::Websocket(websocket);
                    let event = binance_aggtrade_raw_event(
                        &output,
                        &collector_identity,
                        &spec,
                        &source_sequence_epoch_id,
                        current_connection_generation,
                    )?;
                    let bytes = owned_event_bytes(&event);
                    if bytes > MAX_TYPED_ROW_BYTES {
                        sink.source_queue_backpressure.record_operational_drop(
                            &spec.source_kind,
                            recv_time_utc_ms,
                            1,
                        );
                        return Err(invalid_data(format!(
                            "operator_intervention_required:binance_aggtrade_output_row_too_large:bytes={bytes}:limit={MAX_TYPED_ROW_BYTES}"
                        ))
                        .into());
                    }
                    let mut reservation = websocket_staging_reservation;
                    reservation.shrink_to(1, bytes)?;
                    let admission_gaps = payload_conflict
                        .then(|| format!("binance_aggtrade_payload_conflict:id={native_id}"))
                        .into_iter()
                        .collect();
                    send_event_with_reservation_outcome(
                        &sink,
                        run_started,
                        event,
                        Some(reservation),
                        admission_gaps,
                    )
                    .await?;
                }
                Ok(Some(Ok(Message::Binary(payload)))) => {
                    let recv_time_utc_ms = now_ms();
                    let coordinate = allocate_aggtrade_websocket_ingress(
                        &ingress_sequences,
                        &sink,
                        recv_time_utc_ms,
                    )?;
                    let websocket_staging_reservation = sink
                        .inflight_budget
                        .acquire(
                            1,
                            aggtrade_websocket_staging_bytes(payload.len(), false)?,
                            BUFFER_ACQUIRE_TIMEOUT,
                        )
                        .await?;
                    emit_aggtrade_websocket_invalid(
                        payload.to_vec(),
                        recv_time_utc_ms,
                        coordinate,
                        BinanceAggTradeInvalidReason::InvalidPayload,
                        "unexpected_binary_application_message",
                        &sink,
                        &collector_identity,
                        &spec,
                        &source_sequence_epoch_id,
                        current_connection_generation,
                        run_started,
                        websocket_staging_reservation,
                    )
                    .await?;
                }
                Ok(Some(Ok(Message::Ping(payload)))) => {
                    let write_timeout = deadline_remaining(deadline)
                        .map(|remaining| remaining.min(Duration::from_secs(WS_WRITE_TIMEOUT_SECS)))
                        .unwrap_or_else(|| Duration::from_secs(WS_WRITE_TIMEOUT_SECS));
                    if write_timeout.is_zero() {
                        break "source_deadline_before_pong".to_owned();
                    }
                    match timeout(write_timeout, stream.send(Message::Pong(payload))).await {
                        Ok(Ok(())) => {}
                        Ok(Err(error)) => break format!("pong_send_error:{error}"),
                        Err(_) => break "pong_send_timeout".to_owned(),
                    }
                }
                Ok(Some(Ok(Message::Close(frame)))) => break format!("closed:{frame:?}"),
                Ok(Some(Ok(_))) => {}
                Ok(Some(Err(TungsteniteError::Capacity(CapacityError::MessageTooLong {
                    size,
                    max_size,
                })))) => {
                    let recv_time_utc_ms = now_ms();
                    let coordinate = allocate_aggtrade_websocket_ingress(
                        &ingress_sequences,
                        &sink,
                        recv_time_utc_ms,
                    )?;
                    let mut oversize_reservation = sink
                        .inflight_budget
                        .acquire(1, MAX_TYPED_ROW_BYTES, BUFFER_ACQUIRE_TIMEOUT)
                        .await?;
                    let observed_bytes_at_least = u64::try_from(size)
                        .map_err(|_| invalid_data("aggTrade oversize size overflow"))?;
                    let capture = BinanceAggTradeRawCapture::oversize_not_captured(
                        observed_bytes_at_least,
                        None,
                    )
                    .map_err(invalid_data)?;
                    let invalid = BinanceAggTradeInvalidInput::new(
                        BinanceAggTradeInvalidTransport::Websocket,
                        coordinate,
                        recv_time_utc_ms,
                        spec.url.clone(),
                        BinanceAggTradeInvalidReason::BodyTooLarge,
                        format!("observed={size}:configured_max={max_size}"),
                        capture,
                    )
                    .map_err(invalid_data)?;
                    let event = binance_aggtrade_invalid_raw_event(
                        &invalid,
                        &collector_identity,
                        &spec,
                        &source_sequence_epoch_id,
                        current_connection_generation,
                    )?;
                    drop(invalid);
                    let bytes = owned_event_bytes(&event);
                    oversize_reservation.shrink_to(1, bytes)?;
                    send_event_with_reservation(
                        &sink,
                        run_started,
                        event,
                        Some(oversize_reservation),
                    )
                    .await?;
                    break "oversize_application_message".to_owned();
                }
                Ok(Some(Err(error))) => break format!("error:{error}"),
                Ok(None) => break "stream_ended".to_owned(),
                Err(_) if deadline_reached(deadline) => break 'connections,
                Err(_) => break "frame_inactivity_timeout".to_owned(),
            }
        };

        if !wait_for_source_recovery(&mut recovery, &sink, deadline).await {
            break;
        }
    }
    Ok(())
}

async fn handle_aggtrade_source_control(control: AggTradeSourceControl) -> Result<bool> {
    let AggTradeSourceControl::Fence {
        stop_after_fence,
        resume_after_barrier,
        reply,
    } = control;
    let _ = reply.send(Ok(()));
    if let Some(resume) = resume_after_barrier {
        resume
            .await
            .map_err(|_| invalid_data("aggTrade barrier owner dropped source resume signal"))?;
    }
    Ok(stop_after_fence)
}
fn binance_aggtrade_raw_event(
    output: &BinanceAggTradeOutput,
    collector_identity: &CollectorIdentity,
    spec: &BinanceWsSpec,
    source_sequence_epoch_id: &str,
    connection_generation: u64,
) -> Result<RawEvent> {
    if connection_generation == 0 {
        return Err(invalid_data("aggTrade connection generation is zero").into());
    }
    let shared = output.shared();
    let BinanceAggTradeOutput::Websocket(websocket) = output;
    let websocket_ingress_sequence = websocket_ingress_sequence(&websocket.ingress_coordinate)?;
    let source_native_payload_json = output.source_native_payload_json().map_err(invalid_data)?;
    Ok(RawEvent {
        source_kind: spec.source_kind.clone(),
        source_event_type: spec.default_event_type.clone(),
        source_identifier: websocket.symbol.clone(),
        source_ts: Some(shared.trade_time_ms.to_string()),
        recv_time_utc_ms: output.timestamp_received(),
        collector_host_id: collector_identity.host_id.clone(),
        collector_region: collector_identity.region.clone(),
        source_endpoint: spec.url.clone(),
        raw_json: json!({
            "record_kind": "trade",
            "timestamp_received": output.timestamp_received(),
            "websocket_timestamp_received": output.websocket_timestamp_received(),
            "rest_backfill_timestamp_received": Value::Null,
            "ingest_source": output.ingest_source().as_str(),
            "event_type": websocket.event_type,
            "event_time": websocket.event_time_ms,
            "trade_time": shared.trade_time_ms,
            "symbol": websocket.symbol,
            "aggregate_trade_id": shared.aggregate_trade_id,
            "price": shared.price,
            "quantity": shared.quantity,
            "first_trade_id": shared.first_trade_id,
            "last_trade_id": shared.last_trade_id,
            "buyer_is_maker": shared.buyer_is_maker,
            "stream": websocket.stream,
            "ws_ignore": websocket.ws_ignore,
            "rest_was_best_price_match": Value::Null,
            "source_native_payload_json": source_native_payload_json,
            "source_sequence_epoch_id": source_sequence_epoch_id,
            "connection_generation": connection_generation,
            "websocket_ingress_sequence": websocket_ingress_sequence,
            "rest_response_ingress_sequence": Value::Null,
            "rest_response_item_index": Value::Null,
        })
        .to_string(),
        collector_admission: None,
        parquet_raw_layout_version: 1,
        parquet_raw_source_kind: spec.source_kind.clone(),
    })
}

fn websocket_ingress_sequence(coordinate: &BinanceAggTradeIngressCoordinate) -> Result<u64> {
    match coordinate {
        BinanceAggTradeIngressCoordinate::Websocket { sequence } if *sequence != 0 => Ok(*sequence),
        _ => Err(invalid_data("aggTrade websocket ingress coordinate is invalid").into()),
    }
}

#[derive(Serialize)]
struct BinanceAggTradeInvalidEvidenceEnvelope<'a> {
    capture_limit_bytes: u64,
    declared_content_length: Option<u64>,
    endpoint: &'a str,
    evidence_schema: &'static str,
    invalid_reason_code: &'a str,
    observed_bytes_at_least: u64,
    payload_base64: Option<&'a str>,
    payload_capture_status: &'a str,
    payload_encoding: Option<&'a str>,
    payload_length_bytes: Option<u64>,
    payload_sha256: Option<&'a str>,
    receive_time_utc_ms: i64,
    transport: &'a str,
}

#[derive(Serialize)]
struct BinanceAggTradeInvalidRawPayload<'a> {
    connection_generation: u64,
    ingest_source: &'a str,
    invalid_reason_code: &'a str,
    invalid_reason_detail: Option<&'a str>,
    payload_capture_status: &'a str,
    payload_encoding: Option<&'a str>,
    payload_length_bytes: Option<u64>,
    payload_sha256: Option<&'a str>,
    record_kind: &'static str,
    rest_response_ingress_sequence: Option<u64>,
    rest_response_item_index: Option<u64>,
    source_native_payload_json: &'a str,
    source_sequence_epoch_id: &'a str,
    timestamp_received: i64,
    websocket_ingress_sequence: Option<u64>,
}

fn binance_aggtrade_invalid_raw_event(
    invalid: &BinanceAggTradeInvalidInput,
    collector_identity: &CollectorIdentity,
    spec: &BinanceWsSpec,
    source_sequence_epoch_id: &str,
    connection_generation: u64,
) -> Result<RawEvent> {
    if connection_generation == 0 {
        return Err(invalid_data("aggTrade invalid connection generation is zero").into());
    }
    let websocket_ingress_sequence = Some(websocket_ingress_sequence(&invalid.ingress_coordinate)?);
    let (payload_encoding, payload_length_bytes, payload_sha256, payload_base64) = match invalid
        .raw_capture
        .status
    {
        crate::binance_aggtrade::BinanceAggTradeRawCaptureStatus::Complete => {
            let length = u64::try_from(invalid.raw_capture.bytes.len())
                .map_err(|_| invalid_data("aggTrade invalid payload length overflow"))?;
            let digest = format!("{:x}", Sha256::digest(&invalid.raw_capture.bytes));
            (
                Some("base64"),
                Some(length),
                Some(digest),
                Some(base64::engine::general_purpose::STANDARD.encode(&invalid.raw_capture.bytes)),
            )
        }
        crate::binance_aggtrade::BinanceAggTradeRawCaptureStatus::OversizeNotCaptured => (
            None,
            invalid.raw_capture.declared_content_length,
            None,
            None,
        ),
    };
    let capture_status = invalid.raw_capture.status.as_str();
    let source_native_payload_json =
        serde_json::to_string(&BinanceAggTradeInvalidEvidenceEnvelope {
            capture_limit_bytes: invalid.raw_capture.limit_bytes,
            declared_content_length: invalid.raw_capture.declared_content_length,
            endpoint: &invalid.endpoint,
            evidence_schema: "binance_aggtrade_invalid_evidence_v1",
            invalid_reason_code: invalid.reason.as_str(),
            observed_bytes_at_least: invalid.raw_capture.observed_bytes_at_least,
            payload_base64: payload_base64.as_deref(),
            payload_capture_status: capture_status,
            payload_encoding,
            payload_length_bytes,
            payload_sha256: payload_sha256.as_deref(),
            receive_time_utc_ms: invalid.timestamp_received,
            transport: invalid.transport.as_str(),
        })
        .map_err(|error| invalid_data(format!("serialize aggTrade invalid evidence:{error}")))?;
    drop(payload_base64);
    let invalid_reason_detail =
        (!invalid.reason_detail.is_empty()).then_some(invalid.reason_detail.as_str());
    let raw_json = serde_json::to_string(&BinanceAggTradeInvalidRawPayload {
        connection_generation,
        ingest_source: invalid.transport.as_str(),
        invalid_reason_code: invalid.reason.as_str(),
        invalid_reason_detail,
        payload_capture_status: capture_status,
        payload_encoding,
        payload_length_bytes,
        payload_sha256: payload_sha256.as_deref(),
        record_kind: "invalid_input",
        rest_response_ingress_sequence: None,
        rest_response_item_index: None,
        source_native_payload_json: &source_native_payload_json,
        source_sequence_epoch_id,
        timestamp_received: invalid.timestamp_received,
        websocket_ingress_sequence,
    })
    .map_err(|error| invalid_data(format!("serialize aggTrade invalid row:{error}")))?
    .into_boxed_str()
    .into_string();
    Ok(RawEvent {
        source_kind: spec.source_kind.clone(),
        source_event_type: "invalid_input".to_owned(),
        source_identifier: format!("{}:{}", invalid.transport.as_str(), invalid.reason.as_str()),
        source_ts: None,
        recv_time_utc_ms: invalid.timestamp_received,
        collector_host_id: collector_identity.host_id.clone(),
        collector_region: collector_identity.region.clone(),
        source_endpoint: invalid.endpoint.clone(),
        raw_json,
        collector_admission: None,
        parquet_raw_layout_version: 1,
        parquet_raw_source_kind: spec.source_kind.clone(),
    })
}

fn allocate_aggtrade_websocket_ingress(
    allocator: &BinanceAggTradeIngressSequenceAllocator,
    sink: &SourceEventSink,
    recv_time_utc_ms: i64,
) -> Result<BinanceAggTradeIngressCoordinate> {
    allocator.allocate_websocket().map_err(|error| {
        sink.source_queue_backpressure.record_operational_drop(
            "binance_aggtrade",
            recv_time_utc_ms,
            1,
        );
        record_gap(
            &sink.gaps,
            format!("binance_aggtrade_ingress_sequence_terminal:{error}"),
        );
        invalid_data(error.to_string()).into()
    })
}

fn binance_aggtrade_websocket_invalid_input(
    raw_bytes: Vec<u8>,
    recv_time_utc_ms: i64,
    endpoint: &str,
    ingress_coordinate: BinanceAggTradeIngressCoordinate,
    reason: BinanceAggTradeInvalidReason,
    reason_detail: impl Into<String>,
) -> Result<BinanceAggTradeInvalidInput> {
    let capture = BinanceAggTradeRawCapture::complete(raw_bytes, None).map_err(invalid_data)?;
    BinanceAggTradeInvalidInput::new(
        BinanceAggTradeInvalidTransport::Websocket,
        ingress_coordinate,
        recv_time_utc_ms,
        endpoint.to_owned(),
        reason,
        reason_detail,
        capture,
    )
    .map_err(|error| invalid_data(error).into())
}

fn aggtrade_websocket_staging_bytes(payload_bytes: usize, parse_json: bool) -> Result<usize> {
    let input_and_capture = payload_bytes
        .checked_mul(2)
        .ok_or_else(|| invalid_data("aggTrade websocket input staging size overflow"))?;
    let json_value = if parse_json {
        payload_bytes
            .checked_mul(BINANCE_AGGTRADE_JSON_VALUE_STAGING_MULTIPLIER)
            .ok_or_else(|| invalid_data("aggTrade websocket JSON staging size overflow"))?
    } else {
        0
    };
    input_and_capture
        .checked_add(json_value)
        .and_then(|bytes| {
            bytes.checked_add(BINANCE_AGGTRADE_INVALID_SERIALIZATION_STAGING_MAX_BYTES)
        })
        .ok_or_else(|| invalid_data("aggTrade websocket total staging size overflow").into())
}

#[allow(clippy::too_many_arguments)]
async fn emit_aggtrade_websocket_invalid(
    raw_bytes: Vec<u8>,
    recv_time_utc_ms: i64,
    ingress_coordinate: BinanceAggTradeIngressCoordinate,
    reason: BinanceAggTradeInvalidReason,
    reason_detail: impl Into<String>,
    sink: &SourceEventSink,
    collector_identity: &CollectorIdentity,
    spec: &BinanceWsSpec,
    source_sequence_epoch_id: &str,
    connection_generation: u64,
    run_started: Instant,
    mut staging_reservation: InflightReservation,
) -> Result<()> {
    let invalid = binance_aggtrade_websocket_invalid_input(
        raw_bytes,
        recv_time_utc_ms,
        &spec.url,
        ingress_coordinate,
        reason,
        reason_detail,
    )?;
    let event = binance_aggtrade_invalid_raw_event(
        &invalid,
        collector_identity,
        spec,
        source_sequence_epoch_id,
        connection_generation,
    )?;
    drop(invalid);
    let bytes = owned_event_bytes(&event);
    if bytes > MAX_TYPED_ROW_BYTES {
        return Err(invalid_data(format!(
            "operator_intervention_required:binance_aggtrade_invalid_row_too_large:bytes={bytes}:limit={MAX_TYPED_ROW_BYTES}"
        ))
        .into());
    }
    staging_reservation.shrink_to(1, bytes)?;
    send_event_with_reservation(sink, run_started, event, Some(staging_reservation)).await
}

fn binance_ws_payload(value: &Value) -> &Value {
    value.get("data").unwrap_or(value)
}

async fn discover_markets_with_wait(
    gamma: &GammaClient,
    wait: Duration,
    retry_delay: Duration,
) -> std::result::Result<BtcUpdownDiscovery, PolymarketDiscoveryError> {
    discover_markets_with_wait_clock(gamma, wait, retry_delay, now_ms).await
}

async fn discover_markets_with_wait_clock<N>(
    gamma: &GammaClient,
    wait: Duration,
    retry_delay: Duration,
    timeline_now_utc_ms: N,
) -> std::result::Result<BtcUpdownDiscovery, PolymarketDiscoveryError>
where
    N: Fn() -> i64,
{
    let started = Instant::now();
    let final_error = loop {
        let query_ms = timeline_now_utc_ms();
        let windows = discovery_windows(query_ms);
        let last_error = match fetch_exact_slug_candidates_with_clock(
            gamma,
            &windows.current.slug,
            &timeline_now_utc_ms,
        )
        .await
        {
            Ok(batch) => {
                let evaluation_ms = timeline_now_utc_ms();
                if !gamma_batch_is_current(&batch, evaluation_ms) {
                    format!(
                        "requested current slug {} expired before processing",
                        batch.requested_slug
                    )
                } else {
                    match select_btc_updown_markets(evaluation_ms, &batch.candidates, &[]) {
                        Ok(mut discovery) => {
                            let validation_completed_at_utc_ms = timeline_now_utc_ms();
                            stamp_polymarket_discovery_validation(
                                &mut discovery.current,
                                validation_completed_at_utc_ms,
                            )
                            .map_err(|error| {
                                PolymarketDiscoveryError::Integrity(error.to_string())
                            })?;
                            return Ok(discovery);
                        }
                        Err(error) => match classify_discovery_selection_error(error) {
                            PolymarketDiscoveryError::Unavailable(message) => message,
                            integrity @ PolymarketDiscoveryError::Integrity(_) => {
                                return Err(integrity);
                            }
                        },
                    }
                }
            }
            Err(PolymarketDiscoveryError::Unavailable(message)) => message,
            Err(integrity @ PolymarketDiscoveryError::Integrity(_)) => return Err(integrity),
        };
        if started.elapsed() >= wait {
            break last_error;
        }
        let delay = retry_delay.min(wait.saturating_sub(started.elapsed()));
        if delay.is_zero() {
            break last_error;
        }
        sleep(delay).await;
    };
    Err(PolymarketDiscoveryError::Unavailable(format!(
        "btc-updown-5m current discovery failed after wait_secs={}: {final_error}",
        wait.as_secs()
    )))
}

#[derive(Debug)]
struct GammaCandidateBatch {
    requested_slug: String,
    candidates: Vec<BtcUpdownMarketCandidate>,
}

fn classify_discovery_selection_error(error: DiscoverySelectionError) -> PolymarketDiscoveryError {
    match error {
        DiscoverySelectionError::MissingCurrentCandidate { .. }
        | DiscoverySelectionError::MissingNextCandidate { .. } => {
            PolymarketDiscoveryError::Unavailable(format!("{error:?}"))
        }
        DiscoverySelectionError::MultipleCurrentCandidates { .. }
        | DiscoverySelectionError::MultipleNextCandidates { .. }
        | DiscoverySelectionError::InvalidCurrent { .. }
        | DiscoverySelectionError::InvalidNext { .. }
        | DiscoverySelectionError::PairRelationInvalid => {
            PolymarketDiscoveryError::Integrity(format!("{error:?}"))
        }
    }
}

fn classify_gamma_sdk_error(
    error: polymarket_client_sdk_v2::error::Error,
) -> PolymarketDiscoveryError {
    if error.kind() == PolymarketSdkErrorKind::Status {
        return PolymarketDiscoveryError::Unavailable(error.to_string());
    }
    if let Some(reqwest_error) = error.downcast_ref::<reqwest::Error>() {
        if reqwest_error.is_builder() || reqwest_error.is_decode() {
            return PolymarketDiscoveryError::Integrity(error.to_string());
        }
        return PolymarketDiscoveryError::Unavailable(error.to_string());
    }
    if error.downcast_ref::<serde_json::Error>().is_some() {
        return PolymarketDiscoveryError::Integrity(error.to_string());
    }
    PolymarketDiscoveryError::Integrity(error.to_string())
}

fn gamma_batch_is_current_next(batch: &GammaCandidateBatch, evaluation_ms: i64) -> bool {
    discovery_windows(evaluation_ms).next.slug == batch.requested_slug
}

fn gamma_batch_is_current(batch: &GammaCandidateBatch, evaluation_ms: i64) -> bool {
    discovery_windows(evaluation_ms).current.slug == batch.requested_slug
}

fn gamma_discovery_is_current(discovery: &BtcUpdownDiscovery, evaluation_ms: i64) -> bool {
    discovery_windows(evaluation_ms).current.slug == discovery.current.slug
}

#[cfg(test)]
fn late_polymarket_identity_can_activate(
    source_received_at_utc_ms: i64,
    verified_at_utc_ms: i64,
    applied_at_utc_ms: i64,
    market_start_utc_ms: i64,
    market_end_utc_ms: i64,
) -> bool {
    source_received_at_utc_ms <= verified_at_utc_ms
        && verified_at_utc_ms <= applied_at_utc_ms
        && applied_at_utc_ms >= market_start_utc_ms
        && applied_at_utc_ms < market_end_utc_ms
}

#[cfg(test)]
async fn fetch_exact_slug_candidates(
    gamma: &GammaClient,
    slug: &str,
) -> std::result::Result<GammaCandidateBatch, PolymarketDiscoveryError> {
    fetch_exact_slug_candidates_with_clock(gamma, slug, now_ms).await
}

async fn fetch_exact_slug_candidates_with_clock<N>(
    gamma: &GammaClient,
    slug: &str,
    timeline_now_utc_ms: N,
) -> std::result::Result<GammaCandidateBatch, PolymarketDiscoveryError>
where
    N: Fn() -> i64,
{
    let mut request = MarketsRequest::default();
    request.slug = vec![slug.to_owned()];
    request.closed = Some(false);
    request.limit = Some(10);
    let metadata_fetch_start_utc_ms = timeline_now_utc_ms();
    let markets = timeout(
        Duration::from_secs(GAMMA_REQUEST_TIMEOUT_SECS),
        gamma.markets(&request),
    )
    .await
    .map_err(|_| {
        PolymarketDiscoveryError::Unavailable(format!(
            "Gamma request for {slug} exceeded {GAMMA_REQUEST_TIMEOUT_SECS}s"
        ))
    })?
    .map_err(classify_gamma_sdk_error)?;
    let metadata_received_utc_ms = timeline_now_utc_ms();
    let candidates = markets
        .iter()
        .map(|market| {
            let mut candidate = BtcUpdownMarketCandidate::from_sdk_market(market);
            candidate.metadata_fetch_start_utc_ms = Some(metadata_fetch_start_utc_ms);
            candidate.metadata_received_utc_ms = Some(metadata_received_utc_ms);
            candidate
        })
        .collect();
    Ok(GammaCandidateBatch {
        requested_slug: slug.to_owned(),
        candidates,
    })
}

fn bounded_ws_config() -> WsConfig {
    let mut config = WsConfig::default();
    config.connect_timeout = Some(Duration::from_secs(WS_CONNECT_TIMEOUT_SECS));
    config.reconnect.max_attempts = Some(3);
    config.reconnect.max_backoff = Duration::from_secs(5);
    config.heartbeat_interval = Duration::from_secs(10);
    config.require_text_pong = true;
    config.heartbeat_timeout = Duration::from_secs(20);
    config
}

fn bounded_rtds_ws_config() -> WsConfig {
    let mut config = WsConfig::default();
    config.connect_timeout = Some(Duration::from_secs(WS_CONNECT_TIMEOUT_SECS));
    config.reconnect.max_attempts = None;
    config.reconnect.max_backoff = Duration::from_secs(5);
    config.heartbeat_interval = Duration::from_secs(5);
    config.require_text_pong = false;
    config.heartbeat_timeout = Duration::from_secs(15);
    config
}

fn source_admission_authority(event: &RawEvent) -> Option<&'static str> {
    match event.source_kind.as_str() {
        "binance_aggtrade" => "binance_aggtrade",
        "binance_depth_snapshot" | "binance_depth_update" => "binance_depth",
        "polymarket_market_metadata" => "polymarket_market_metadata",
        _ => return None,
    }
    .into()
}

fn record_source_admission_integrity(
    event: &RawEvent,
    sink: &SourceEventSink,
    admission_source: &str,
    error: &str,
) {
    sink.source_queue_backpressure.record_operational_drop(
        &event.source_kind,
        event.recv_time_utc_ms,
        1,
    );
    record_gap(
        &sink.gaps,
        format!("{admission_source}_admission_integrity:{error}"),
    );
}

fn validate_source_admission_at(
    event: &RawEvent,
    sink: &SourceEventSink,
    time_utc_ms: i64,
) -> Result<Option<&'static str>> {
    let Some(admission_source) = source_admission_authority(event) else {
        return Ok(None);
    };
    if event.collector_admission.is_some() {
        let error = format!("{admission_source} event admitted more than once");
        record_source_admission_integrity(event, sink, admission_source, &error);
        return Err(invalid_data(error).into());
    }
    if time_utc_ms <= 0 {
        let error = format!("{admission_source} admission time is not positive");
        record_source_admission_integrity(event, sink, admission_source, &error);
        return Err(invalid_data(error).into());
    }
    if admission_source == "polymarket_market_metadata" {
        let row = serde_json::from_str::<Value>(&event.raw_json).map_err(|error| {
            let error =
                format!("Polymarket metadata draft JSON is invalid before admission:{error}");
            record_source_admission_integrity(event, sink, admission_source, &error);
            invalid_data(error)
        })?;
        let future_causal_time = [
            ("recv_time_utc_ms", Some(event.recv_time_utc_ms)),
            (
                "timestamp_received",
                row.get("timestamp_received").and_then(Value::as_i64),
            ),
            (
                "fixed_identity_verified_at_utc",
                row.get("fixed_identity_verified_at_utc")
                    .and_then(Value::as_i64),
            ),
            (
                "source_evidence_received_at_utc",
                row.get("source_evidence_received_at_utc")
                    .and_then(Value::as_i64),
            ),
            (
                "row_evidence_validation_completed_at_utc",
                row.get("row_evidence_validation_completed_at_utc")
                    .and_then(Value::as_i64),
            ),
            (
                "metadata_fetch_start_utc",
                row.get("metadata_fetch_start_utc").and_then(Value::as_i64),
            ),
            (
                "lifecycle_applied_at_utc",
                row.get("lifecycle_applied_at_utc").and_then(Value::as_i64),
            ),
            (
                "runtime_role_applied_at_utc",
                row.get("runtime_role_applied_at_utc")
                    .and_then(Value::as_i64),
            ),
        ]
        .into_iter()
        .find_map(|(field, value)| {
            value
                .filter(|value| *value > time_utc_ms)
                .map(|value| (field, value))
        });
        if let Some((field, value)) = future_causal_time {
            let error = format!(
                "Polymarket metadata causal time is after real admission clock:field={field}:value={value}:admission={time_utc_ms}"
            );
            record_source_admission_integrity(event, sink, admission_source, &error);
            return Err(invalid_data(error).into());
        }
    }
    Ok(Some(admission_source))
}

fn stamp_source_admission(event: &mut RawEvent, sink: &SourceEventSink) -> Result<()> {
    let time_utc_ms = now_ms();
    let Some(admission_source) = validate_source_admission_at(event, sink, time_utc_ms)? else {
        return Ok(());
    };
    let sequence = sink
        .source_queue_backpressure
        .reserve_admission_sequences(admission_source, 1)
        .inspect_err(|error| {
            record_source_admission_integrity(event, sink, admission_source, &error.to_string());
        })?;
    event.collector_admission = Some(RawEventAdmission {
        sequence,
        time_utc_ms,
    });
    Ok(())
}

fn stamp_source_admissions_atomically(
    events: &mut [InflightRawEvent],
    sink: &SourceEventSink,
) -> Result<()> {
    let time_utc_ms = now_ms();
    let mut admission_source = None;
    let mut admission_count = 0_usize;
    for event in events.iter() {
        let Some(source) = validate_source_admission_at(&event.event, sink, time_utc_ms)? else {
            continue;
        };
        if admission_source.is_some_and(|expected| expected != source) {
            let error = format!(
                "atomic ingress batch mixed admission authorities:{}:{source}",
                admission_source.unwrap_or_default()
            );
            record_source_admission_integrity(&event.event, sink, source, &error);
            return Err(invalid_data(error).into());
        }
        admission_source = Some(source);
        admission_count = admission_count.saturating_add(1);
    }
    let Some(admission_source) = admission_source else {
        return Ok(());
    };
    let first_sequence =
        sink.source_queue_backpressure
            .reserve_admission_sequences(admission_source, admission_count)
            .inspect_err(|error| {
                for event in events.iter().filter(|event| {
                    source_admission_authority(&event.event) == Some(admission_source)
                }) {
                    record_source_admission_integrity(
                        &event.event,
                        sink,
                        admission_source,
                        &error.to_string(),
                    );
                }
            })?;
    for (offset, event) in events
        .iter_mut()
        .filter(|event| source_admission_authority(&event.event) == Some(admission_source))
        .enumerate()
    {
        event.event.collector_admission = Some(RawEventAdmission {
            sequence: first_sequence + offset as u64,
            time_utc_ms,
        });
    }
    Ok(())
}

async fn send_event(sink: &SourceEventSink, run_started: Instant, event: RawEvent) -> Result<()> {
    send_event_with_outcome(sink, run_started, event)
        .await
        .map(|_| ())
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum EventAdmissionOutcome {
    Admitted,
    Deferred,
    Cutoff,
}

async fn send_event_with_admission_outcome(
    sink: &SourceEventSink,
    run_started: Instant,
    event: RawEvent,
) -> Result<EventAdmissionOutcome> {
    enqueue_event_with_reservation_outcome(sink, run_started, event, None, Vec::new()).await
}

async fn send_event_with_outcome(
    sink: &SourceEventSink,
    run_started: Instant,
    event: RawEvent,
) -> Result<bool> {
    send_event_with_admission_outcome(sink, run_started, event)
        .await
        .map(|outcome| outcome != EventAdmissionOutcome::Cutoff)
}

async fn send_event_with_reservation(
    sink: &SourceEventSink,
    run_started: Instant,
    event: RawEvent,
    existing_reservation: Option<InflightReservation>,
) -> Result<()> {
    send_event_with_reservation_outcome(sink, run_started, event, existing_reservation, Vec::new())
        .await
        .map(|_| ())
}

async fn send_event_with_reservation_outcome(
    sink: &SourceEventSink,
    run_started: Instant,
    event: RawEvent,
    existing_reservation: Option<InflightReservation>,
    admission_gaps: Vec<String>,
) -> Result<bool> {
    enqueue_event_with_reservation_outcome(
        sink,
        run_started,
        event,
        existing_reservation,
        admission_gaps,
    )
    .await
    .map(|outcome| outcome != EventAdmissionOutcome::Cutoff)
}

async fn enqueue_event_with_reservation_outcome(
    sink: &SourceEventSink,
    run_started: Instant,
    event: RawEvent,
    existing_reservation: Option<InflightReservation>,
    admission_gaps: Vec<String>,
) -> Result<EventAdmissionOutcome> {
    let source_kind = event.source_kind.clone();
    let recv_time_utc_ms = event.recv_time_utc_ms;
    let gate = sink
        .source_queue_backpressure
        .raw_day_gate()
        .ok_or_else(|| {
            invalid_data(format!(
                "raw-day gate missing from production enqueue path: source={source_kind}"
            ))
        })?;
    let producer = logical_producer_for_source_kind(&source_kind)?;
    let Some(raw_enqueue) = gate
        .begin_unadmitted_event_enqueue(producer, recv_time_utc_ms)
        .await?
    else {
        return Ok(EventAdmissionOutcome::Cutoff);
    };
    let owned_bytes = owned_event_bytes(&event);
    if owned_bytes > MAX_TYPED_ROW_BYTES {
        let gap = format!(
            "operator_intervention_required:max_typed_row_bytes_exceeded:{source_kind}:bytes={owned_bytes}:limit={MAX_TYPED_ROW_BYTES}"
        );
        sink.source_queue_backpressure
            .record_operational_drop(&source_kind, recv_time_utc_ms, 1);
        record_gap(&sink.gaps, gap.clone());
        return Err(invalid_data(gap).into());
    }
    let reservation = match existing_reservation {
        Some(reservation) => reservation,
        None => match sink
            .inflight_budget
            .acquire(1, owned_bytes, BUFFER_ACQUIRE_TIMEOUT)
            .await
        {
            Ok(reservation) => reservation,
            Err(error) => {
                sink.source_queue_backpressure.record_timeout();
                sink.source_queue_backpressure.record_drop(1);
                sink.source_queue_backpressure.record_operational_drop(
                    &source_kind,
                    recv_time_utc_ms,
                    1,
                );
                let gap = format!("global_inflight_budget_failed:{source_kind}:{error}");
                record_gap(&sink.gaps, gap);
                return Err(error.into());
            }
        },
    };
    let mut inflight_event = InflightRawEvent {
        event,
        control: None,
        admission_gaps,
        raw_day_permit: match &raw_enqueue {
            RawDayEnqueueDecision::Permit(enqueue) => Some(enqueue.permit.clone()),
            RawDayEnqueueDecision::Defer(_) => None,
        },
        _source_recv_monotonic_ms: monotonic_ms(run_started),
        _reservation: Some(reservation),
    };
    if let RawDayEnqueueDecision::Defer(epoch) = &raw_enqueue {
        sink.source_queue_backpressure.defer_raw_batch(
            producer,
            epoch.clone(),
            vec![inflight_event],
        )?;
        return Ok(EventAdmissionOutcome::Deferred);
    }
    let _enqueue_guard = sink.enqueue_lock.lock().await;
    let permit = match sink.tx.try_reserve() {
        Ok(permit) => permit,
        Err(mpsc::error::TrySendError::Full(())) => {
            sink.source_queue_backpressure.record_wait();
            match timeout(BUFFER_ACQUIRE_TIMEOUT, sink.tx.reserve()).await {
                Ok(Ok(permit)) => permit,
                Ok(Err(_)) => {
                    sink.source_queue_backpressure.record_drop(1);
                    sink.source_queue_backpressure.record_operational_drop(
                        &source_kind,
                        recv_time_utc_ms,
                        1,
                    );
                    let gap = format!("bounded_queue_send_failed:{source_kind}");
                    record_gap(&sink.gaps, gap.clone());
                    return Err(io::Error::new(io::ErrorKind::BrokenPipe, gap).into());
                }
                Err(_) => {
                    sink.source_queue_backpressure.record_timeout();
                    sink.source_queue_backpressure.record_drop(1);
                    sink.source_queue_backpressure.record_operational_drop(
                        &source_kind,
                        recv_time_utc_ms,
                        1,
                    );
                    let gap = format!("bounded_queue_backpressure_timeout:{source_kind}");
                    record_gap(&sink.gaps, gap.clone());
                    return Err(io::Error::new(io::ErrorKind::TimedOut, gap).into());
                }
            }
        }
        Err(mpsc::error::TrySendError::Closed(())) => {
            sink.source_queue_backpressure.record_drop(1);
            sink.source_queue_backpressure.record_operational_drop(
                &source_kind,
                recv_time_utc_ms,
                1,
            );
            let gap = format!("bounded_queue_send_closed:{source_kind}");
            record_gap(&sink.gaps, gap.clone());
            return Err(io::Error::new(io::ErrorKind::BrokenPipe, gap).into());
        }
    };
    stamp_source_admission(&mut inflight_event.event, sink)?;
    let admission_gaps = std::mem::take(&mut inflight_event.admission_gaps);
    permit.send(inflight_event);
    for gap in admission_gaps {
        record_gap_at(&sink.gaps, recv_time_utc_ms, gap);
    }
    Ok(EventAdmissionOutcome::Admitted)
}

async fn send_ingress_control(
    sink: &SourceEventSink,
    run_started: Instant,
    control: IngressControl,
    label: &str,
) -> Result<()> {
    let _enqueue_guard = sink.enqueue_lock.lock().await;
    let message = InflightRawEvent {
        event: RawEvent {
            source_kind: "__ingress_control".to_owned(),
            source_event_type: label.to_owned(),
            source_identifier: label.to_owned(),
            source_ts: None,
            recv_time_utc_ms: now_ms(),
            collector_host_id: String::new(),
            collector_region: String::new(),
            source_endpoint: String::new(),
            raw_json: "{}".to_owned(),
            collector_admission: None,
            parquet_raw_layout_version: 0,
            parquet_raw_source_kind: "__ingress_control".to_owned(),
        },
        control: Some(control),
        admission_gaps: Vec::new(),
        raw_day_permit: None,
        _source_recv_monotonic_ms: monotonic_ms(run_started),
        _reservation: None,
    };
    match sink.tx.try_send(message) {
        Ok(()) => Ok(()),
        Err(mpsc::error::TrySendError::Full(message)) => {
            match timeout(BUFFER_ACQUIRE_TIMEOUT, sink.tx.send(message)).await {
                Ok(Ok(())) => Ok(()),
                Ok(Err(_)) => Err(io::Error::new(
                    io::ErrorKind::BrokenPipe,
                    format!("ingress control queue closed: {label}"),
                )
                .into()),
                Err(_) => Err(io::Error::new(
                    io::ErrorKind::TimedOut,
                    format!("ingress control queue timeout: {label}"),
                )
                .into()),
            }
        }
        Err(mpsc::error::TrySendError::Closed(_)) => Err(io::Error::new(
            io::ErrorKind::BrokenPipe,
            format!("ingress control queue closed: {label}"),
        )
        .into()),
    }
}

async fn send_day_barrier(
    sink: &SourceEventSink,
    run_started: Instant,
    producer: &str,
    close: RawDayClose,
) -> Result<DayBarrierRelease> {
    let (reply_tx, reply_rx) = oneshot::channel();
    send_ingress_control(
        sink,
        run_started,
        IngressControl::DayBarrier {
            producer: producer.to_owned(),
            close,
            reply: reply_tx,
        },
        "utc_day_barrier",
    )
    .await?;
    match reply_rx.await {
        Ok(Ok(release)) => Ok(release),
        Ok(Err(error)) => Err(invalid_data(format!(
            "producer day barrier failed before coordinated release: producer={producer} error={error}"
        ))
        .into()),
        Err(_) => Err(invalid_data(format!(
            "producer day barrier reply dropped: producer={producer}"
        ))
        .into()),
    }
}

async fn send_source_hour_finalize(
    sink: &SourceEventSink,
    run_started: Instant,
    source_kind: &str,
    utc_hour: String,
) -> Result<()> {
    send_ingress_control(
        sink,
        run_started,
        IngressControl::FinalizeSourceHour {
            source_kind: source_kind.to_owned(),
            utc_hour,
        },
        "utc_hour_finalize",
    )
    .await
}

