    fn prepare_rollover_for_producer(
        gate: &RawDayGate,
        producer: &str,
        utc_day: &str,
        boundary_utc_ms: i64,
    ) -> RawDayClose {
        let close = gate.prepare_rollover(utc_day, boundary_utc_ms).unwrap();
        for other in LOGICAL_PRODUCERS {
            if *other != producer {
                gate.register_source_fence(other, &close).unwrap();
            }
        }
        close
    }

