            let error = build_polymarket_events(
                message,
                &discovery,
                &asset_to_slug,
                &identity,
                1_783_392_404_599,
                r#"{"source":"test"}"#,
            )
            .err()
            .expect("a target asset under the wrong condition must be terminal");
